INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04ab9997-34c2-4887-8427-b3fd5ec44984', '十二時偈 十二', '十二时偈 十二', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["人定亥，莫把三乘相疋配。","要知此意現真宗，密密心心超三昧。"]', '["人定亥，莫把三乘相疋配。","要知此意現真宗，密密心心超三昧。"]', '诗', 'shi', '', NULL, '十二時偈 十二 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e099ad0-904b-437c-b6b1-8e0016080145', '宗脉頌', '宗脉頌', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["如來一大事，出現於世間。","五千方便教，流傳幾百年。","四十九年說，未曾忤出言。","如來滅度後，付囑迦葉邊。","西天二十八，祖佛印相傳。","達摩觀東土，五葉氣相連。","九年來面壁，唯有喫茶言。","二祖爲上首，達摩廻西天。","六祖曹溪住，衣鉢後不傳。","派分三五六，各各達真源。","七八心忙亂，空花墜目前。","苦哉●眼士，認得止啼錢。","外道多毀謗，弟子得生天。","昔在靈山上，今日獲安然。","六門俱休歇，無心處處閑。","如有玄中客，但除入我山。","一味醍醐藥，萬病悉皆安。","因緣契會者，無心便安禪。","（以上十三首均見《祖堂集》卷十一）。"]', '["如来一大事，出現於世间。","五千方便教，流傳幾百年。","四十九年说，未曾忤出言。","如来滅度後，付囑迦葉邊。","西天二十八，祖佛印相傳。","達摩观东土，五葉氣相連。","九年来面壁，唯有喫茶言。","二祖爲上首，達摩廻西天。","六祖曹溪住，衣鉢後不傳。","派分三五六，各各達真源。","七八心忙亂，空花墜目前。","苦哉●眼士，認得止啼錢。","外道多毀謗，弟子得生天。","昔在靈山上，今日獲安然。","六门俱休歇，無心处处闲。","如有玄中客，但除入我山。","一味醍醐藥，万病悉皆安。","因緣契會者，無心便安禪。","（以上十三首均见《祖堂集》卷十一）。"]', '诗', 'shi', '', NULL, '宗脉頌 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f763a41f-bb88-44f6-95ca-db3a5e8d7948', '十二時歌', '十二时歌', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["夜半子，愚夫說相似。","鷄鳴丑，癡人捧龜首。","平旦寅，曉何人。","日出卯，韓情枯骨咬。","食時辰，歷歷明機是悟（《古尊宿語當》卷十五引作「悮」）真。","禺中巳，去來南北子。","日南午，認向途中苦。","日昳未，夏逢說寒氣。","晡時申，張三李四會言真。","日入酉，恒機何得守。","黃昏戌，看見時光誰受屈。","人定亥，直（一作「真」）得分明沉苦海。","（見《大正新修大藏經》第四十七冊宋僧守堅集《雲門匡真禪師廣錄》卷上。","此條承王小盾同志告知。","）。"]', '["夜半子，愚夫说相似。","鷄鳴丑，癡人捧龟首。","平旦寅，晓何人。","日出卯，韓情枯骨咬。","食时辰，歷歷明機是悟（《古尊宿語當》卷十五引作「悮」）真。","禺中巳，去来南北子。","日南午，認向途中苦。","日昳未，夏逢说寒氣。","晡时申，張三李四會言真。","日入酉，恒機何得守。","黄昏戌，看见时光誰受屈。","人定亥，直（一作「真」）得分明沉苦海。","（见《大正新修大藏經》第四十七冊宋僧守堅集《云门匡真禪師廣錄》卷上。","此條承王小盾同志告知。","）。"]', '诗', 'shi', '', NULL, '十二時歌 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d053634c-f6c2-4e94-8f5b-30526a12cc4a', '偈頌 一', '偈頌 一', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["雲門聳剔（《天聖廣燈錄》卷二十作「踢」、《五燈會元》卷十五作「峻」）白雲低，水急遊魚不敢棲。","入戶已知來見解，何勞更（《天聖廣燈錄》、《五燈會元》作「再」）舉轢中泥。"]', '["云门聳剔（《天聖廣灯錄》卷二十作「踢」、《五灯會元》卷十五作「峻」）白云低，水急游鱼不敢棲。","入戶已知来见解，何勞更（《天聖廣灯錄》、《五灯會元》作「再」）舉轢中泥。"]', '诗', 'shi', '', NULL, '偈頌 一 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68d5be51-b9f6-43fe-8744-a3141d64a090', '偈頌 二', '偈頌 二', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["藥病相治學路醫，扶籬摸壁小兒戲。","幽谷不語誰人測，管解師承孰不知。"]', '["藥病相治学路醫，扶籬摸壁小兒戲。","幽谷不語誰人測，管解師承孰不知。"]', '诗', 'shi', '', NULL, '偈頌 二 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32d1dc8a-3042-4489-910e-9864a3d59bfc', '偈頌 三', '偈頌 三', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["康氏圓形滯不明，魔深虛喪擊寒冰。","鳳羽展時超碧漢，晉鋒八博擬何憑。"]', '["康氏圓形滯不明，魔深虛喪擊寒冰。","鳳羽展时超碧漢，晉鋒八博擬何憑。"]', '诗', 'shi', '', NULL, '偈頌 三 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60918b7c-cb83-44ae-bbab-9a6732b1a956', '偈頌 四', '偈頌 四', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["是機是對對機迷，闢機（一作「塵」）塵遠遠機（《僧寶傳》卷二作「塵」）棲。","夕日日中誰有掛，因底底事隔情（《僧寶傳》作「塵」）迷。","。"]', '["是機是对对機迷，闢機（一作「塵」）塵远远機（《僧寶傳》卷二作「塵」）棲。","夕日日中誰有掛，因底底事隔情（《僧寶傳》作「塵」）迷。","。"]', '诗', 'shi', '', NULL, '偈頌 四 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e41b953d-8de2-4a55-9c96-e37181c9a53b', '偈頌 五', '偈頌 五', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["太陽溢目極玄微，誰人說道我渠非。","句中有路人皆響，覿面難遭第一機。"]', '["太陽溢目極玄微，誰人说道我渠非。","句中有路人皆响，覿面难遭第一機。"]', '诗', 'shi', '', NULL, '偈頌 五 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e78ec9c3-dc47-4616-9091-19791ad15777', '偈頌 六', '偈頌 六', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["丱歲依山人事稀，松下相逢話道奇。","鋒前一句超調御，擬問如何歷劫違。"]', '["丱歲依山人事稀，松下相逢話道奇。","鋒前一句超調御，擬问如何歷劫違。"]', '诗', 'shi', '', NULL, '偈頌 六 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0afb8d28-8b6c-4362-a50f-cf215959d7ac', '偈頌 七', '偈頌 七', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["翫古松高雲不齊，鴻鶬鶴抱幾年棲。","剖㲉同時殊有異，羽張騰漢碧霄低。"]', '["翫古松高云不齊，鴻鶬鹤抱幾年棲。","剖㲉同时殊有異，羽張腾漢碧霄低。"]', '诗', 'shi', '', NULL, '偈頌 七 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37a6b395-98c2-44e5-adea-f5a0325dc24b', '偈頌 八', '偈頌 八', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["萬像森羅極細微，素話當人却道非。","相逢相見呵呵笑，顧佇停機復是誰。"]', '["万像森羅極細微，素話當人却道非。","相逢相见呵呵笑，顧佇停機复是誰。"]', '诗', 'shi', '', NULL, '偈頌 八 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8112e984-db13-4330-9dc1-6573bfd3d27e', '偈頌 九', '偈頌 九', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["話盡途中事，言多何省機。","貴人言是妙，上士見知虧。"]', '["話尽途中事，言多何省機。","貴人言是妙，上士见知虧。"]', '诗', 'shi', '', NULL, '偈頌 九 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23ec2de3-b6d8-41be-abbf-88cedb2308e8', '偈頌 十', '偈頌 十', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["大道何曾討，無端入荒草。","卷來復卷去，不覺虛生老。"]', '["大道何曾討，無端入荒草。","卷来复卷去，不覺虛生老。"]', '诗', 'shi', '', NULL, '偈頌 十 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('311a418b-7294-494b-a00c-01eab8d2c13c', '偈頌 十一', '偈頌 十一', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["喪時光，藤林荒。","圖（《僧寶傳》作「徒」）人意，滯肌尩。"]', '["喪时光，藤林荒。","圖（《僧寶傳》作「徒」）人意，滯肌尩。"]', '诗', 'shi', '', NULL, '偈頌 十一 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33919baa-efb7-45e8-9e77-381a0725dc28', '偈頌 十二', '偈頌 十二', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["舉不顧，即差互。","擬思量，何劫悟。"]', '["舉不顧，即差互。","擬思量，何劫悟。"]', '诗', 'shi', '', NULL, '偈頌 十二 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3524c778-0ad6-4e26-aa46-ff840f65f145', '偈頌 十三', '偈頌 十三', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["咄咄咄，力韋（《僧寶傳》作「目」）希。","禪子訝，中眉垂。","（並同前）。"]', '["咄咄咄，力韋（《僧寶傳》作「目」）希。","禪子訝，中眉垂。","（並同前）。"]', '诗', 'shi', '', NULL, '偈頌 十三 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80a897fe-4485-4d69-bd8c-66575acb2a19', '偈頌 十四', '偈頌 十四', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["不露鋒（《五燈會元》卷十五作「風」）骨句，未語先分付。","進步口喃喃，知君大罔措。","（見同前書卷下）。"]', '["不露鋒（《五灯會元》卷十五作「风」）骨句，未語先分付。","進步口喃喃，知君大罔措。","（见同前书卷下）。"]', '诗', 'shi', '', NULL, '偈頌 十四 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4b20a11-a0d3-42aa-b615-7679a1e4e761', '偈頌 十五', '偈頌 十五', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["雲門顧鑒笑嘻嘻，擬議遭渠顧鑑咦。","任是張良多智巧，到頭於是也難施。","（《禪林僧寶傳》卷二）。"]', '["云门顧鑒笑嘻嘻，擬議遭渠顧鑑咦。","任是張良多智巧，到头於是也难施。","（《禪林僧寶傳》卷二）。"]', '诗', 'shi', '', NULL, '偈頌 十五 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d51a374-a7f9-4ef0-9049-b00e5cf8768c', '北邙行', '北邙行', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["前山後山高峨峨，喪車轔轔日日過。","哀歌幽怨滿巖谷，聞者潛悲《薤露歌》。","哀歌一聲千載別，孝子順孫徒泣血。","世間何物得堅牢，大海須彌竟磨滅。","人生還如露易晞，從來有會終別離。","苦海哀傷不暫輟，況復百年驚夢馳。","去人悠悠不復至，今人不會古人意。","栽松起石駐墓門，欲爲死者長年計。","魂魄悠揚形化土，五趣茫茫井輪度。","今人還葬古人墳，今墳古墳無定主。","洛陽城裏千萬人，終爲北邙山下塵。","沉迷不計歸時路，爲君孤坐長悲辛。","昔日送人哭長道，今爲孤墳臥芳草。","妖狐穿穴藏子孫，耕夫撥骨尋珠寶。","老木蕭蕭生野風，東西壞冢連晴空。","寒食已過誰享祀，冢畔餘花寂寞紅。","日月相催若流矢，貧富歸愚盡如此。","安得同遊常樂鄉，縱經劫火無生死。","（見明焦竑《焦氏類林》卷八）。"]', '["前山後山高峨峨，喪车轔轔日日過。","哀歌幽怨满巖谷，闻者潛悲《薤露歌》。","哀歌一声千載別，孝子順孫徒泣血。","世间何物得堅牢，大海須彌竟磨滅。","人生還如露易晞，從来有會終別離。","苦海哀傷不暫輟，況复百年驚梦驰。","去人悠悠不复至，今人不會古人意。","栽松起石駐墓门，欲爲死者长年計。","魂魄悠揚形化土，五趣茫茫井輪度。","今人還葬古人墳，今墳古墳無定主。","洛陽城裏千万人，終爲北邙山下塵。","沉迷不計归时路，爲君孤坐长悲辛。","昔日送人哭长道，今爲孤墳臥芳草。","妖狐穿穴藏子孫，耕夫撥骨尋珠寶。","老木蕭蕭生野风，东西壞冢連晴空。","寒食已過誰享祀，冢畔餘花寂寞紅。","日月相催若流矢，貧富归愚尽如此。","安得同游常乐乡，縱經劫火無生死。","（见明焦竑《焦氏類林》卷八）。"]', '诗', 'shi', '', NULL, '北邙行 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a33289c7-a5a1-4c75-a399-9702dd6f4741', '頌雲門三句語（幷餘頌八首） 函蓋乾坤', '頌云门三句語（幷餘頌八首） 函蓋乾坤', '88db5226-6533-45a0-86a2-eb3278186d85', '唐', '["乾坤並萬像，地獄及天堂，物物皆真現，頭頭總（《天聖廣燈錄》作「用」）不傷。"]', '["乾坤並万像，地獄及天堂，物物皆真現，头头總（《天聖廣灯錄》作「用」）不傷。"]', '诗', 'shi', '', NULL, '頌雲門三句語（幷餘頌八首） 函蓋乾坤 緣密 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e0fc4ab-ac03-4e3c-9e45-4efc78ffee0e', '頌雲門三句語（幷餘頌八首） 截斷衆流', '頌云门三句語（幷餘頌八首） 截斷衆流', '88db5226-6533-45a0-86a2-eb3278186d85', '唐', '["堆山積嶽來，一一盡塵埃。","更擬論玄妙，冰消瓦解摧。"]', '["堆山積嶽来，一一尽塵埃。","更擬論玄妙，冰消瓦解摧。"]', '诗', 'shi', '', NULL, '頌雲門三句語（幷餘頌八首） 截斷衆流 緣密 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a7f9337-a649-49c3-a2ab-5dfce25d681b', '頌雲門三句語（幷餘頌八首） 隨波逐浪', '頌云门三句語（幷餘頌八首） 隨波逐浪', '88db5226-6533-45a0-86a2-eb3278186d85', '唐', '["辯口利舌間，高低總不虧。","還如應病藥，診候在臨時。"]', '["辯口利舌间，高低總不虧。","還如應病藥，診候在臨时。"]', '诗', 'shi', '', NULL, '頌雲門三句語（幷餘頌八首） 隨波逐浪 緣密 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f267a7fd-4584-4985-bb6c-05eddf94c211', '頌雲門三句語（幷餘頌八首） 三句外別置一頌（《古尊宿語錄》作「問」）', '頌云门三句語（幷餘頌八首） 三句外別置一頌（《古尊宿語錄》作「问」）', '88db5226-6533-45a0-86a2-eb3278186d85', '唐', '["當人如舉唱，三句豈能該。","有問如何事，南嶽與天台。","。"]', '["當人如舉唱，三句豈能該。","有问如何事，南嶽與天台。","。"]', '诗', 'shi', '', NULL, '頌雲門三句語（幷餘頌八首） 三句外別置一頌（《古尊宿語錄》作「問」） 緣密 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1951ca3-119f-4108-96fe-3bdebaa382f2', '頌雲門三句語（幷餘頌八首） 褒貶句', '頌云门三句語（幷餘頌八首） 褒貶句', '88db5226-6533-45a0-86a2-eb3278186d85', '唐', '["金屑眼中翳，衣珠法上塵。"]', '["金屑眼中翳，衣珠法上塵。"]', '诗', 'shi', '', NULL, '頌雲門三句語（幷餘頌八首） 褒貶句 緣密 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('606960d8-4b5e-4890-964a-5f0f0264b827', '頌雲門三句語（幷餘頌八首） 辨親疎', '頌云门三句語（幷餘頌八首） 辨親疎', '88db5226-6533-45a0-86a2-eb3278186d85', '唐', '["黑豆未生前，商量已成顛。","更尋言語（《天聖廣燈錄》作「句」）會，特地隔西天。"]', '["黑豆未生前，商量已成顛。","更尋言語（《天聖廣灯錄》作「句」）會，特地隔西天。"]', '诗', 'shi', '', NULL, '頌雲門三句語（幷餘頌八首） 辨親疎 緣密 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c43e8bff-aebd-4344-962f-06f390cb7839', '頌雲門三句語（幷餘頌八首） 辨邪正', '頌云门三句語（幷餘頌八首） 辨邪正', '88db5226-6533-45a0-86a2-eb3278186d85', '唐', '["罔象談真旨，都緣未辨明。","守他山鬼窟，不免是精靈。"]', '["罔象談真旨，都緣未辨明。","守他山鬼窟，不免是精靈。"]', '诗', 'shi', '', NULL, '頌雲門三句語（幷餘頌八首） 辨邪正 緣密 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a65fc3bb-7e3c-49ec-acc5-6d10a16b92a2', '頌雲門三句語（幷餘頌八首） 通賓主', '頌云门三句語（幷餘頌八首） 通賓主', '88db5226-6533-45a0-86a2-eb3278186d85', '唐', '["自遠趨風問，分明向道休。","再三如不（《天聖廣燈錄》作「未」）曉，消得箇非遙。","（《天聖廣燈錄》作「更搖頭」）。"]', '["自远趨风问，分明向道休。","再三如不（《天聖廣灯錄》作「未」）晓，消得箇非遙。","（《天聖廣灯錄》作「更搖头」）。"]', '诗', 'shi', '', NULL, '頌雲門三句語（幷餘頌八首） 通賓主 緣密 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a052a3c-be74-47db-a7ba-d28110d5dad9', '頌雲門三句語（幷餘頌八首） 擡薦商量', '頌云门三句語（幷餘頌八首） 擡薦商量', '88db5226-6533-45a0-86a2-eb3278186d85', '唐', '["相見不揚眉，君東我亦西。","紅霞穿碧海，白日繞（《天聖廣燈錄》作「照」）須彌。"]', '["相见不揚眉，君东我亦西。","紅霞穿碧海，白日繞（《天聖廣灯錄》作「照」）須彌。"]', '诗', 'shi', '', NULL, '頌雲門三句語（幷餘頌八首） 擡薦商量 緣密 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12611d64-9e6e-4a22-a543-3986d19dcc2c', '頌雲門三句語（幷餘頌八首） 提綱商量', '頌云门三句語（幷餘頌八首） 提綱商量', '88db5226-6533-45a0-86a2-eb3278186d85', '唐', '["若欲正提綱，直須大地荒。","欲來衝雪刃，不免露（《天聖廣燈錄》作「碎」）鋒鋩。"]', '["若欲正提綱，直須大地荒。","欲来衝雪刃，不免露（《天聖廣灯錄》作「碎」）鋒鋩。"]', '诗', 'shi', '', NULL, '頌雲門三句語（幷餘頌八首） 提綱商量 緣密 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4199d8c-7f98-4ee6-8d0b-be2583e2dfa2', '頌雲門三句語（幷餘頌八首） 據實商量（《天聖廣燈錄》作「據實話會」）', '頌云门三句語（幷餘頌八首） 據實商量（《天聖廣灯錄》作「據實話會」）', '88db5226-6533-45a0-86a2-eb3278186d85', '唐', '["睡來合眼飯來餐，起坐終諸（《古尊宿語錄》作「須」）勿（《天聖廣燈錄》作「無」）兩般。","同道盡知言不惑，十方剎土目前觀（《天聖廣燈錄》作「看」）。"]', '["睡来合眼飯来餐，起坐終諸（《古尊宿語錄》作「須」）勿（《天聖廣灯錄》作「無」）兩般。","同道尽知言不惑，十方剎土目前观（《天聖廣灯錄》作「看」）。"]', '诗', 'shi', '', NULL, '頌雲門三句語（幷餘頌八首） 據實商量（《天聖廣燈錄》作「據實話會」） 緣密 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4d92c5b-5f02-474f-ba52-6bfa78ce7103', '頌雲門三句語（幷餘頌八首） 委（《天聖廣燈錄》作「迂」）曲商量', '頌云门三句語（幷餘頌八首） 委（《天聖廣灯錄》作「迂」）曲商量', '88db5226-6533-45a0-86a2-eb3278186d85', '唐', '["得用由來處處通，歸機施設認家風。","揚眉瞬目同（《天聖廣燈錄》作「開」）一眼，竪拂敲牀爲耳聾。","（以上十二首均見《大正藏》第四十七冊及《古尊宿語錄》卷十八收宋守堅輯《雲門匡真禪師廣錄》卷下。","《天聖廣燈錄》卷二十一以爲鼎州普安道禪師作，道禪師爲緣密之法嗣。","）。"]', '["得用由来处处通，归機施設認家风。","揚眉瞬目同（《天聖廣灯錄》作「开」）一眼，竪拂敲牀爲耳聾。","（以上十二首均见《大正藏》第四十七冊及《古尊宿語錄》卷十八收宋守堅輯《云门匡真禪師廣錄》卷下。","《天聖廣灯錄》卷二十一以爲鼎州普安道禪師作，道禪師爲緣密之法嗣。","）。"]', '诗', 'shi', '', NULL, '頌雲門三句語（幷餘頌八首） 委（《天聖廣燈錄》作「迂」）曲商量 緣密 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8460af42-4028-46fe-ae3f-551820e39a7c', '疊秀山', '叠秀山', 'a6234b1b-a192-473e-98ba-753daf76e535', '唐', '["平生賦性愛觀瀾，今日登臨疊秀山。","天錫卦爻分象外，地將圭笏出人間。","昭州本遶孤城小，五嶺山高衆垤難。","極且紫宸何處是，碧雲深處珮珊珊。","（見《粤西詩載》卷十三）。"]', '["平生賦性愛观瀾，今日登臨叠秀山。","天錫卦爻分象外，地將圭笏出人间。","昭州本遶孤城小，五嶺山高衆垤难。","極且紫宸何处是，碧云深处珮珊珊。","（见《粤西诗載》卷十三）。"]', '诗', 'shi', '', NULL, '疊秀山 周渭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fee240d6-353c-41f7-9195-972aaed482e2', '遊兼山', '游兼山', 'a6234b1b-a192-473e-98ba-753daf76e535', '唐', '["插空峭壁白雲迷，獨上高巔萬象低。","一路接天連楚界，兩峰拔地鎮南夷。","泉飛石澗遊魂冷，風捲松濤匹馬嘶。","踏破層崖心未折。","鳳凰山後鷓鴣啼。","（見光緒十五年陸履中纂《恭城縣志》卷四）。"]', '["插空峭壁白云迷，独上高巔万象低。","一路接天連楚界，兩峰拔地鎮南夷。","泉飞石澗游魂冷，风捲松濤匹马嘶。","踏破層崖心未折。","鳳凰山後鷓鴣啼。","（见光緒十五年陸履中纂《恭城縣志》卷四）。"]', '诗', 'shi', '', NULL, '遊兼山 周渭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5248a98e-ccdd-4785-b450-2869fd2a4033', '偈', '偈', '012ecf39-15ea-4398-8c3f-66b7edd922e3', '唐', '["以字不是八不成，森羅萬像此中明。","直饒巧說千般妙，不是謳阿（一作「漚和」）不是經。","（見《景德傳燈錄》卷二十二、《五燈會元》卷十五）。"]', '["以字不是八不成，森羅万像此中明。","直饒巧说千般妙，不是謳阿（一作「漚和」）不是經。","（见《景德傳灯錄》卷二十二、《五灯會元》卷十五）。"]', '诗', 'shi', '', NULL, '偈 智寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7329d526-6bfd-426a-86ad-6ce5b5096bdf', '送郡太守', '送郡太守', '502a4787-9702-4e2b-9f75-6e2c3111b56b', '唐', '["桄榔雨醉江城夜，橄欖風吟野驛秋。"]', '["桄榔雨醉江城夜，橄欖风吟野驛秋。"]', '诗', 'shi', '', NULL, '送郡太守 胡君防 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aeaf3cff-6e4f-47b6-9ee9-945b3aa83379', '咸陽閒望', '咸陽閒望', '502a4787-9702-4e2b-9f75-6e2c3111b56b', '唐', '["樓臺舊地牛羊滿，宮殿遺址禾黍平。"]', '["楼台旧地牛羊满，宮殿遺址禾黍平。"]', '诗', 'shi', '', NULL, '咸陽閒望 胡君防 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48dbdef3-a867-4847-b7b0-9f8441a5b27b', '水邊', '水邊', '502a4787-9702-4e2b-9f75-6e2c3111b56b', '唐', '["島日斜明僧寺閣，汀雲低影客船窗。","。"]', '["島日斜明僧寺閣，汀云低影客船窗。","。"]', '诗', 'shi', '', NULL, '水邊 胡君防 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba41becd-5306-440c-b950-f936aaf58a22', '句', '句', '502a4787-9702-4e2b-9f75-6e2c3111b56b', '唐', '["水邊閑詠處，雲島月斜明。","（均見《粤詩蒐逸》卷一引《連州志》本傳）（按：胡君防另有《贈魏野處士》詩，知宋真宗初尚在世。","）。"]', '["水邊闲詠处，云島月斜明。","（均见《粤诗蒐逸》卷一引《連州志》本傳）（按：胡君防另有《贈魏野处士》诗，知宋真宗初尚在世。","）。"]', '诗', 'shi', '', NULL, '句 胡君防 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef54e59e-3ddc-407f-88ac-3ee65d172647', '葛藤歌', '葛藤歌', 'cac2a6ae-a1cf-48df-b82e-7cde0d437d25', '唐', '["阿呵呵，是什麽，聽向精靈窟裏坐。","朕兆生兮與未生，驀口摑弓無罪過。","如今口使誰人摑，縱使摑弓復何責？","除是知音同道流，未言已過新羅國。","乾坤大地本來虛，靡用觀空作意除。","作意除兮終不了，還似霜鉤釣火魚。","恨余數載勤勞苦，爲剖玄中一玄語。","明明玄自不玄玄，更尚玄中求玄悟。","無法迷人及悟人，忽於平地致難辛。","丈夫須稟天生格，蹋破虛空莫問津。","單刀秀句枉施設，剜肉成瘡向誰說？","直鐃講得石點頭，終歸不離水中月。","更言者箇是如來，誑他自誑苦哀哉！若也不信葛藤語，一任青天掣電雷。","余家一任青天笑，碧落浮雲徒浩浩。","解說刀兮口不傷，今古豈無言語道。","閑來把筆動毫鋩，不欲{眉肩}然佇寂鄉。","無事強生多種解，爭如無事且尋常。","且尋常，猶被虛真笑一場。","可憐好箇究全子，喚作究全早壓良。","默不是，語乖張，到此分明總是狂。","爲報諸方毳侶道，最好波斯入大唐。","（《天聖廣燈錄》卷二十。","）。"]', '["阿呵呵，是什麽，听向精靈窟裏坐。","朕兆生兮與未生，驀口摑弓無罪過。","如今口使誰人摑，縱使摑弓复何責？","除是知音同道流，未言已過新羅国。","乾坤大地本来虛，靡用观空作意除。","作意除兮終不了，還似霜鉤釣火鱼。","恨余數載勤勞苦，爲剖玄中一玄語。","明明玄自不玄玄，更尚玄中求玄悟。","無法迷人及悟人，忽於平地致难辛。","丈夫須稟天生格，蹋破虛空莫问津。","單刀秀句枉施設，剜肉成瘡向誰说？","直鐃講得石点头，終归不離水中月。","更言者箇是如来，誑他自誑苦哀哉！若也不信葛藤語，一任青天掣電雷。","余家一任青天笑，碧落浮云徒浩浩。","解说刀兮口不傷，今古豈無言語道。","闲来把笔动毫鋩，不欲{眉肩}然佇寂乡。","無事強生多種解，爭如無事且尋常。","且尋常，猶被虛真笑一場。","可怜好箇究全子，喚作究全早壓良。","默不是，語乖張，到此分明總是狂。","爲報諸方毳侶道，最好波斯入大唐。","（《天聖廣灯錄》卷二十。","）。"]', '诗', 'shi', '', NULL, '葛藤歌 朗上座 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b073b3aa-0c7b-485b-93d3-09c375312c86', '落星寺', '落星寺', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["此星何事下穹蒼，獨爲僧居化渺茫。","樓閣兩回青嶂冷，軒窗風度白蘋香。","經秋遠鴈橫高漢，䫿風寒濤響夜堂。","盡日憑欄聊寫望，頓疑身忽在瀟湘。"]', '["此星何事下穹蒼，独爲僧居化渺茫。","楼閣兩回青嶂冷，軒窗风度白蘋香。","經秋远鴈橫高漢，䫿风寒濤响夜堂。","尽日憑欄聊寫望，頓疑身忽在瀟湘。"]', '诗', 'shi', '', NULL, '落星寺 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d433199c-67bc-405f-9b12-15759741c2b5', '西林水閣', '西林水閣', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["松楸連塔古，窗檻任閑開。","水遶清陰裏，人從熱處來。","噪風蟬帶鶴，欹樹石兼苔。","向曉東林下，遲遲捨此廻。","（以上二首均見《吉石庵叢書》本《廬山記》卷四）。"]', '["松楸連塔古，窗檻任闲开。","水遶清陰裏，人從熱处来。","噪风蟬带鹤，欹樹石兼苔。","向晓东林下，遲遲捨此廻。","（以上二首均见《吉石庵叢书》本《廬山記》卷四）。"]', '诗', 'shi', '', NULL, '西林水閣 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('739d8f00-e1aa-4dc4-9e8b-26f8c90b0eb3', '題天門山', '題天门山', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["可憐宋玉多才思，不見天門十六峰。","（見《輿地紀勝》卷七十《澧州》）。"]', '["可怜宋玉多才思，不见天门十六峰。","（见《輿地紀勝》卷七十《澧州》）。"]', '诗', 'shi', '', NULL, '題天門山 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('185b805a-2b4b-4584-972e-4a29b4d88652', '送人歸吳', '送人归吳', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["比說歸耕釣，迢迢向海涯。","春寒游子路，村晚主人家。","野岸紛垂柳，深山綠過茶。","重尋舊鄰里，菱藕正開花。","（影印文淵閣《四庫全書》本《白蓮集》卷一）（按：《全唐詩》卷八三八收此詩缺六字，今重錄。","）。"]', '["比说归耕釣，迢迢向海涯。","春寒游子路，村晚主人家。","野岸紛垂柳，深山綠過茶。","重尋旧鄰里，菱藕正开花。","（影印文淵閣《四庫全书》本《白蓮集》卷一）（按：《全唐诗》卷八三八收此诗缺六字，今重錄。","）。"]', '诗', 'shi', '', NULL, '送人歸吳 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cf91f52-fa8e-43e4-95ac-c9ab66571ef7', '寄王振拾遺', '寄王振拾遺', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["折檻意何如？平安信不虛。","近來焚諫草，深去覓山居。","志定榮枯外，身全寵辱餘。","分明知在處，難寄亂離書。","（同前。","）（按：《全唐詩》卷八三八收此詩缺九字，今重錄。","）。"]', '["折檻意何如？平安信不虛。","近来焚諫草，深去覓山居。","志定榮枯外，身全寵辱餘。","分明知在处，难寄亂離书。","（同前。","）（按：《全唐诗》卷八三八收此诗缺九字，今重錄。","）。"]', '诗', 'shi', '', NULL, '寄王振拾遺 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3ec940f-8c5d-4b3c-afa7-3533eaafc755', '送[韓]（劉）（據詩意及《白蓮集》卷九改）蛻秀才赴舉', '送[韓]（劉）（據诗意及《白蓮集》卷九改）蛻秀才赴舉', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["百發百中技，長[楊]（陽）獻賦年。","丹枝如技分，一箭的無偏。","文物兵銷國，關河雪霽天。","都人看春牓，韓字在誰前。","（同前）（按：《全唐詩》卷八三八收此詩缺五字，今重錄。","）。"]', '["百發百中技，长[楊]（陽）獻賦年。","丹枝如技分，一箭的無偏。","文物兵銷国，关河雪霽天。","都人看春牓，韓字在誰前。","（同前）（按：《全唐诗》卷八三八收此诗缺五字，今重錄。","）。"]', '诗', 'shi', '', NULL, '送[韓]（劉）（據詩意及《白蓮集》卷九改）蛻秀才赴舉 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b026297e-d09a-443e-a802-909e8a062f21', '寄勉二三子', '寄勉二三子', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["不見二三子，悠然吳楚間。","盡應生白髮，幾箇在青山。","暇日還宜愛，餘生莫放閒。","君聞國風否？千載詠關關。","（同前）（按：《全唐詩》卷八三八收此詩缺七字，今重錄。","）。"]', '["不见二三子，悠然吳楚间。","尽應生白髮，幾箇在青山。","暇日還宜愛，餘生莫放閒。","君闻国风否？千載詠关关。","（同前）（按：《全唐诗》卷八三八收此诗缺七字，今重錄。","）。"]', '诗', 'shi', '', NULL, '寄勉二三子 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('733a1139-5232-453a-a260-2f169770d40d', '與張先輩話別', '與張先輩話別', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["爲子同志者，各自話離心。","及第還全蜀，遊方歸二林。","巴江經峽漲，楚野入吳深。","地日傳消息，東西不易尋。","（同前卷二）（按：《全唐詩》卷八三九收此詩缺五字，今重錄。","）。"]', '["爲子同志者，各自話離心。","及第還全蜀，游方归二林。","巴江經峽漲，楚野入吳深。","地日傳消息，东西不易尋。","（同前卷二）（按：《全唐诗》卷八三九收此诗缺五字，今重錄。","）。"]', '诗', 'shi', '', NULL, '與張先輩話別 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88fdf361-e135-4adf-9f76-d645fa82fdc5', '渚宮莫問詩一十五首之十一', '渚宮莫问诗一十五首之十一', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["莫問休貪戀，浮雲逐性情。","人間高此道，禪外剩他名。","夏雨松邊坐，秋光水畔行。","更無時忌諱，容易得題成。","（同前卷五）（按：《全唐詩》卷八四二收此詩缺六字，今重錄。","又《全唐詩》卷八四一收《還族弟卷》第五句缺一字，前引四庫本《白蓮集》卷四作「詣」，《四部叢刊》本作「苦」。","卷八四三《聞西蟾從弟卜巖居嶽詩有寄》第八句缺一字，四庫本《白蓮集》卷六作「總」。","）。"]', '["莫问休貪戀，浮云逐性情。","人间高此道，禪外剩他名。","夏雨松邊坐，秋光水畔行。","更無时忌諱，容易得題成。","（同前卷五）（按：《全唐诗》卷八四二收此诗缺六字，今重錄。","又《全唐诗》卷八四一收《還族弟卷》第五句缺一字，前引四庫本《白蓮集》卷四作「詣」，《四部叢刊》本作「苦」。","卷八四三《闻西蟾從弟卜巖居嶽诗有寄》第八句缺一字，四庫本《白蓮集》卷六作「總」。","）。"]', '诗', 'shi', '', NULL, '渚宮莫問詩一十五首之十一 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1185c170-2092-4508-8924-ffcc8510d945', '古松', '古松', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["雷電不敢伐，鱗皺勢萬端。","蠹依枯節死，蛇入朽根盤。","影浸僧禪濕，聲吹鶴夢寒。","尋常風雨夜，應有鬼神看。","（《分門纂類唐歌詩》殘本卷九五《草木蟲魚類》七）。"]', '["雷電不敢伐，鱗皺勢万端。","蠹依枯節死，蛇入朽根盤。","影浸僧禪濕，声吹鹤梦寒。","尋常风雨夜，應有鬼神看。","（《分门纂類唐歌诗》殘本卷九五《草木蟲鱼類》七）。"]', '诗', 'shi', '', NULL, '古松 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac3ab931-c94f-4987-87e5-0ffe0b68000e', '句 一', '句 一', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["翠樓春酒蝦蟆陵，長安少年皆共矜。","（《升庵詩話》卷十三。","以上二則承周介民同志告知。","）。"]', '["翠楼春酒蝦蟆陵，长安少年皆共矜。","（《升庵诗話》卷十三。","以上二則承周介民同志告知。","）。"]', '诗', 'shi', '', NULL, '句 一 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('391ac1f9-1a57-4b2e-ad30-cb0977f8c2a9', '句 二', '句 二', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["相思坐溪石，微雨下山嵐。","（見《吟窗雜錄》卷十五）（按：《全唐詩》卷八四七收二句，缺三字，今重錄。","）。"]', '["相思坐溪石，微雨下山嵐。","（见《吟窗杂錄》卷十五）（按：《全唐诗》卷八四七收二句，缺三字，今重錄。","）。"]', '诗', 'shi', '', NULL, '句 二 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3521b8bc-6f02-49ec-8de0-1f50ab5a13da', '入道淺深頌 一', '入道淺深頌 一', 'dbab4829-134f-496c-b2e4-5a0f334d6ba1', '唐', '["露柱聲聲喚，猢猻繩不斷。","中下莫知由，上士方堪看。","。"]', '["露柱声声喚，猢猻繩不斷。","中下莫知由，上士方堪看。","。"]', '诗', 'shi', '', NULL, '入道淺深頌 一 竟脫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95494ca4-d2fa-4da4-8ce4-db7b971ab9d5', '入道淺深頌 二', '入道淺深頌 二', 'dbab4829-134f-496c-b2e4-5a0f334d6ba1', '唐', '["露柱不聲喚，猢猻繩子斷。","上士笑呵呵，中流若爲見。"]', '["露柱不声喚，猢猻繩子斷。","上士笑呵呵，中流若爲见。"]', '诗', 'shi', '', NULL, '入道淺深頌 二 竟脫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b9ffc10-4dad-4b1e-9187-408f1ae04ae9', '入道淺深頌 三', '入道淺深頌 三', 'dbab4829-134f-496c-b2e4-5a0f334d6ba1', '唐', '["猢猻與露柱，未免東西步。","任唱太平歌，徒話超佛祖。"]', '["猢猻與露柱，未免东西步。","任唱太平歌，徒話超佛祖。"]', '诗', 'shi', '', NULL, '入道淺深頌 三 竟脫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61432055-81fa-41d0-ac80-d8a02ac8046c', '入道淺深頌 四', '入道淺深頌 四', 'dbab4829-134f-496c-b2e4-5a0f334d6ba1', '唐', '["我見匠者誇，語默玄妙句。","不善本根源，巧布祗園事。"]', '["我见匠者誇，語默玄妙句。","不善本根源，巧布祗园事。"]', '诗', 'shi', '', NULL, '入道淺深頌 四 竟脫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02b2ded8-9bc5-4160-b415-11f2b4144fbc', '入道淺深頌 五', '入道淺深頌 五', 'dbab4829-134f-496c-b2e4-5a0f334d6ba1', '唐', '["少室與摩竭，第代稱揚許。","我今問汝徒，誰作將來主。","（見《景德傳燈錄》卷二十九，原署「敬脫和尚」。","）。"]', '["少室與摩竭，第代稱揚許。","我今问汝徒，誰作將来主。","（见《景德傳灯錄》卷二十九，原署「敬脫和尚」。","）。"]', '诗', 'shi', '', NULL, '入道淺深頌 五 竟脫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f219305f-0457-44dd-8b3c-07697f96b9ba', '寄南平王', '寄南平王', '6e6cdfff-831a-4e35-9886-70898c3c47f9', '唐', '["馬頭漸入揚州路，親眷應須洗眼看。","（見《太平廣記》卷九十八引《北夢瑣言》、《宋高僧傳》卷二十二《晉巴東懷濬傳》）。"]', '["马头漸入揚州路，親眷應須洗眼看。","（见《太平廣記》卷九十八引《北梦瑣言》、《宋高僧傳》卷二十二《晉巴东懷濬傳》）。"]', '诗', 'shi', '', NULL, '寄南平王 懷濬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('010abfdc-648b-45e9-9957-d31b97495de0', '荆臺（題擬）', '荆台（題擬）', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["百尺荆臺草徑荒，如何前日謂雲陽？","古今不盡遷移恨，依舊臺邊水渺茫。","（見《輿地紀勝》卷六四《江陵府》）。"]', '["百尺荆台草徑荒，如何前日謂云陽？","古今不尽遷移恨，依旧台邊水渺茫。","（见《輿地紀勝》卷六四《江陵府》）。"]', '诗', 'shi', '', NULL, '荆臺（題擬） 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ac09712-c024-4f1a-a426-90583e37e344', '句', '句', '41ac4e87-379e-4ec0-986a-54a840af9f18', '唐', '["科松爲落花。","（見《北夢瑣言》卷二）。"]', '["科松爲落花。","（见《北梦瑣言》卷二）。"]', '诗', 'shi', '', NULL, '句 孫光憲同寮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de8f3271-923a-475f-8383-a6bb25e3f896', '法身頌', '法身頌', '7baa98ec-3bca-48d9-b52e-3aceeee4db54', '唐', '["扶桑出日頭，黃河輥底流。","六六三十六，陝府出（《五燈會元》作「灌」）鐵牛。","（《天聖廣燈錄》卷二十四、《五燈會元》卷十四。","）。"]', '["扶桑出日头，黄河輥底流。","六六三十六，陝府出（《五灯會元》作「灌」）鐵牛。","（《天聖廣灯錄》卷二十四、《五灯會元》卷十四。","）。"]', '诗', 'shi', '', NULL, '法身頌 慧堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce7378e5-d433-4efb-adb1-efb9698d0b6c', '寓玉局山寺感懷', '寓玉局山寺感懷', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["一年一度喜春光，及至秋來又感傷。","白日似風留不住，青春如水去何忙。","眼前有路同歸路，身在他鄉憶故鄉。","若不傾心向真宰，也應憔悴鬢成霜。","（見民國五年刊周宗麟纂《大理縣志稿》卷三十。","）。"]', '["一年一度喜春光，及至秋来又感傷。","白日似风留不住，青春如水去何忙。","眼前有路同归路，身在他乡憶故乡。","若不傾心向真宰，也應憔悴鬢成霜。","（见民国五年刊周宗麟纂《大理縣志稿》卷三十。","）。"]', '诗', 'shi', '', NULL, '寓玉局山寺感懷 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f85eaebb-b47f-4170-9a28-7309c284b0ff', '詩', '诗', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["五百年中降嶽靈，神仙風骨鶴儀形。","劍光帶日衝南斗，鵬翼翻雲起北溟。","（見《錦繡萬花谷》卷二十三。","）。"]', '["五百年中降嶽靈，神仙风骨鹤儀形。","劍光带日衝南斗，鵬翼翻云起北溟。","（见《錦繡万花谷》卷二十三。","）。"]', '诗', 'shi', '', NULL, '詩 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81ca375b-3f57-48b7-a7c6-e381e114e4e6', '生死歌訣 一', '生死歌訣 一', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["切脈定知生死路，但向止濇中取。","看取濇脈喻止代，此是死期之大槩。","濇脈喻外有形證，未可斷他殂大命。","若無形證與代同，尺部見之皆死定。","欲知死期何以取？古賢推定五般土。","陽土須知不過陰，陰土遇陽當細數。","四季中央戊己同，萬物憑土以爲主。","孤陽寡陰即不中，譬取鰥夫及寡婦。","假如申年腎代止，十投一歲分明主。","尺部失主鬼稱尊，其人子年夏季死。","鬼賊脈在一年內，此事人間盡稱會。","春得肺脈死庚辛，愚者反嫌藥不對。","叔和謌訣精微，但何其中尋取義。","尺部伏似樹無根，陰毒傷寒合其類。","回陽着文後仍看，切骨若無堪下淚。","若人六脈動搖搖，又怕其中無胃氣。","屋漏雀啄惡見脾，餘部見之皆不畏。","死期常例有多門，彈石解索須細論。","此候不逾於一季，姻親泣送葬孤墳。","鰕遊若也及魚翔，一氣之期即不長。","十五日中尋鬼賊，水一火二木三量。","金四土五數已實，各隨部位好參詳。","每季土王十八日，此法古今永無失。","黃帝一法四分三，一法亦云三十日。","隨分遠近各不同，藏在玉函誇祕密。","唯有傷寒最無定，汗吐下後脈須靜。","忽然相反即難醫，外邊有怕乖形證。","脈息至少冷虛憊，至多熱壅水爲怪。","補虛瀉實更仍前，見此分明還可駭。","上醫四事盡須諳，脈病證治要相參。","有一乖違難措手，此即難醫大不堪。","更有久病及暴病，大都要知消詳慣。","久病脈變即不中，死候當須宜早辨。","暴病脈變亦多端，或善或惡依法看。","脈病相違即不效，要知大命必須𢬵。","關前爲陽關後陰，婦人反此是冠簪。","乘凌覆溢相侵奪，榮衛調和理更深。","欲識童男與童女，訣在寸關幷尺裏。","自然緊數甚分明，都緣未散精華氣。","小兒脈氣似大人，老少相違即不起。","本經自病最難醫，縱療何年有瘥時。","間藏七傳無外證，強將元散與扶持。","傷寒中風自難看，指下逢之脈繚亂。","合吐即瀉即非良，汗脈見時須發汗。","雖然得汗狀如珠，密密鋪排在病軀。","此候不堪休胗脈，其人朝夕命疕殂。","但於弦鈎毛石中，此狀見之當病劇。","徒誇五色大還丹，若願痊除空費力。","更有死脈多般樣，難經細說那志向，從上損下死即遲，死脈多從下損上。","連傳五臟死疾時，一朝炁少志調養。","再損之時促命期，如逢真箇堪惆悵。","病候脈狀多中取，要知大抵開門戶。","有一乖違即不中，但看強者推爲主。","復有久病更難看，或與健人脈一般。","忽然加至脈飜雙，結托尋衣好買棺。","若遇風疾及勞疾，妙法看時如抵聖。","風疾脾緩空費力，勞極心數命難存。","風疾無令脈至遲，勞疾至多藥無應。","傷寒中風得死脈，但將真藥與瓷闘。","藥靈病退脈須和，脈若準前命難救。","如此定知生死期，可作醫家箕本柄。","若能指下悟元機，便是靈臺掛明鏡。"]', '["切脈定知生死路，但向止濇中取。","看取濇脈喻止代，此是死期之大槩。","濇脈喻外有形證，未可斷他殂大命。","若無形證與代同，尺部见之皆死定。","欲知死期何以取？古賢推定五般土。","陽土須知不過陰，陰土遇陽當細數。","四季中央戊己同，万物憑土以爲主。","孤陽寡陰即不中，譬取鰥夫及寡婦。","假如申年腎代止，十投一歲分明主。","尺部失主鬼稱尊，其人子年夏季死。","鬼賊脈在一年內，此事人间尽稱會。","春得肺脈死庚辛，愚者反嫌藥不对。","叔和謌訣精微，但何其中尋取義。","尺部伏似樹無根，陰毒傷寒合其類。","回陽着文後仍看，切骨若無堪下泪。","若人六脈动搖搖，又怕其中無胃氣。","屋漏雀啄惡见脾，餘部见之皆不畏。","死期常例有多门，彈石解索須細論。","此候不逾於一季，姻親泣送葬孤墳。","鰕游若也及鱼翔，一氣之期即不长。","十五日中尋鬼賊，水一火二木三量。","金四土五數已實，各隨部位好參詳。","每季土王十八日，此法古今永無失。","黄帝一法四分三，一法亦云三十日。","隨分远近各不同，藏在玉函誇祕密。","唯有傷寒最無定，汗吐下後脈須静。","忽然相反即难醫，外邊有怕乖形證。","脈息至少冷虛憊，至多熱壅水爲怪。","補虛瀉實更仍前，见此分明還可駭。","上醫四事尽須諳，脈病證治要相參。","有一乖違难措手，此即难醫大不堪。","更有久病及暴病，大都要知消詳慣。","久病脈变即不中，死候當須宜早辨。","暴病脈变亦多端，或善或惡依法看。","脈病相違即不效，要知大命必須𢬵。","关前爲陽关後陰，婦人反此是冠簪。","乘凌覆溢相侵奪，榮衛調和理更深。","欲識童男與童女，訣在寸关幷尺裏。","自然緊數甚分明，都緣未散精华氣。","小兒脈氣似大人，老少相違即不起。","本經自病最难醫，縱療何年有瘥时。","间藏七傳無外證，強將元散與扶持。","傷寒中风自难看，指下逢之脈繚亂。","合吐即瀉即非良，汗脈见时須發汗。","雖然得汗狀如珠，密密鋪排在病軀。","此候不堪休胗脈，其人朝夕命疕殂。","但於弦鈎毛石中，此狀见之當病劇。","徒誇五色大還丹，若願痊除空費力。","更有死脈多般樣，难經細说那志向，從上損下死即遲，死脈多從下損上。","連傳五臟死疾时，一朝炁少志調養。","再損之时促命期，如逢真箇堪惆悵。","病候脈狀多中取，要知大抵开门戶。","有一乖違即不中，但看強者推爲主。","复有久病更难看，或與健人脈一般。","忽然加至脈飜雙，結托尋衣好買棺。","若遇风疾及勞疾，妙法看时如抵聖。","风疾脾緩空費力，勞極心數命难存。","风疾無令脈至遲，勞疾至多藥無應。","傷寒中风得死脈，但將真藥與瓷闘。","藥靈病退脈須和，脈若準前命难救。","如此定知生死期，可作醫家箕本柄。","若能指下悟元機，便是靈台掛明镜。"]', '诗', 'shi', '', NULL, '生死歌訣 一 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cdada66-75af-4ad7-8392-2f4e76388937', '生死歌訣 二', '生死歌訣 二', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["脈分虛實爲君說，弦數沉被幷冷熱。","關前陽脈數弦浮，關後陰沉遲細脈。","浮弦而數熱兼風，沉細爲寒氣上攻。","陽浮爲表陰沉裏，尺寸關中看子細。","學者要知生死期，九恠脈中定凶吉。","結促牢代四脈者，可取死生期歲月。","假令四十動一止，一臟無炁死之義。","三十動中一止時，三歲二臟死無炁。","脈來十動一止之，一歲死期堪下淚。","若還十動不滿者，動胖炁衰人不起。","須當以日定死期，蓋爲動中不應指。","三元正氣難拘束，魂魄冥冥隨風去。","一呼三寸陽炁出，一吸復然陰炁入。","陰陽呼吸定息勻，來往升降中不息。","肝脈達而風炁生，腎水下而雨滋濕。","肺炁清汽上屬天，地炁濁而通其嗌。","脾司出納象谷空，雷動於心聲霹靂。","水谷包容腸胃間，六經爲川流不息。","陽爲形表血爲陰，精氣爲榮悍爲衛。","絡有十五經十二，上應周天下臨地。","水漏百刻運流行，與周天度爲綱紀。","手足陽明江海水，天蝎金牛幷豫冀。","太陽手足合清淮，天秤白羊充淮裏。","陰陽人馬對寅申，燕益渭漯水氣深。","太陰巨蟹幷磨蝎，丑未湖河水難竭。","寶瓶獅子對周齊，汝水三河合應之。","巳上楚宮屬雙女，亥上雙魚時掉尾。","十二脈中合經水，內外相輸爲表裏。","人身血氣要充盈，六脈無邪無病體。","火之精氣主生神，水氣充盈生志意。","復胗濇脈何部中，敗血折精之脈候。","唯有三秋乃應時，餘月見之皆惡候。","洪鈎夏脈居寸口，堪笑愚夫多不曉。","脈若俱洪不帶鈎，鈎不外匯時血常走。","秋脈微毛若無濇，病者多應命單得。","設然肺部胗見之，濇謂秋中多結脈。","嚴冬尺脈要弦沉，腎部無邪體炁清。","忽然弦大多虛候，夢中涉水鬼隨人。","春怕庚辛秋丙丁，微毛洪數病相侵。","玉函歌訣最玄微，俗眼庸人難探頤。","若能精向義中求，審察元通神可比。","。"]', '["脈分虛實爲君说，弦數沉被幷冷熱。","关前陽脈數弦浮，关後陰沉遲細脈。","浮弦而數熱兼风，沉細爲寒氣上攻。","陽浮爲表陰沉裏，尺寸关中看子細。","学者要知生死期，九恠脈中定凶吉。","結促牢代四脈者，可取死生期歲月。","假令四十动一止，一臟無炁死之義。","三十动中一止时，三歲二臟死無炁。","脈来十动一止之，一歲死期堪下泪。","若還十动不满者，动胖炁衰人不起。","須當以日定死期，蓋爲动中不應指。","三元正氣难拘束，魂魄冥冥隨风去。","一呼三寸陽炁出，一吸复然陰炁入。","陰陽呼吸定息勻，来往升降中不息。","肝脈達而风炁生，腎水下而雨滋濕。","肺炁清汽上屬天，地炁濁而通其嗌。","脾司出納象谷空，雷动於心声霹靂。","水谷包容腸胃间，六經爲川流不息。","陽爲形表血爲陰，精氣爲榮悍爲衛。","絡有十五經十二，上應周天下臨地。","水漏百刻運流行，與周天度爲綱紀。","手足陽明江海水，天蝎金牛幷豫冀。","太陽手足合清淮，天秤白羊充淮裏。","陰陽人马对寅申，燕益渭漯水氣深。","太陰巨蟹幷磨蝎，丑未湖河水难竭。","寶瓶獅子对周齊，汝水三河合應之。","巳上楚宮屬雙女，亥上雙鱼时掉尾。","十二脈中合經水，內外相輸爲表裏。","人身血氣要充盈，六脈無邪無病體。","火之精氣主生神，水氣充盈生志意。","复胗濇脈何部中，敗血折精之脈候。","唯有三秋乃應时，餘月见之皆惡候。","洪鈎夏脈居寸口，堪笑愚夫多不晓。","脈若俱洪不带鈎，鈎不外匯时血常走。","秋脈微毛若無濇，病者多應命單得。","設然肺部胗见之，濇謂秋中多結脈。","嚴冬尺脈要弦沉，腎部無邪體炁清。","忽然弦大多虛候，梦中涉水鬼隨人。","春怕庚辛秋丙丁，微毛洪數病相侵。","玉函歌訣最玄微，俗眼庸人难探頤。","若能精向義中求，審察元通神可比。","。"]', '诗', 'shi', '', NULL, '生死歌訣 二 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da582368-3163-40cd-8d2f-e496b0e66d82', '生死歌訣 三', '生死歌訣 三', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["浮弦多是風頭痛，積聚體疼胸膈噎。","緊實號爲寒熱證，澁瀉煩燥小便澁。","芤脈蓋因陽耗散，鼻衂無時精炁竭。","脈沉兼优是重陰，氣刺胸膨癥塊結。","風寒相傳脈浮遲，外受寒邪內風熱。","肺受風寒痰欬嗽，左手見之心戰佚。","弱而兼濡是陽虛，汗出憎寒炁羸劣。","風濕風溫及濕溫，脈候交差要分別。","汗無重汗耳無知，妄語無瘖各部委是暍。","洪數脈來陽氣盛，目赤舌乾唇破裂。","浮而兼緊腎之虛，溫助寒邪益精血。","陽絕尺中脈細微，針灸勿令精炁絕。","促結代脈是脾虛，若見之時難救得，女人尺中須要盛，浮細沉遲是虛證。","忽然胗得寸中盈，六部無邪身有孕。","童女童男何以別？須看天真無損缺。","大凡童子脈來沉，童女尺中洪拍拍。","男子婦人精血衰，假饒覆溢脈無回。","一呼四至爲平脈，一呼一至死相催。","傷寒舌黑洗不紅，藥洗分明定吉凶。","汗若脈和無惡候，脈如躁疾命將殂。","中風目閉口開者，喉中拽鋸炁不敷。","脈若洪弦由可救，浮大多應命不甦。","男女五勞洪數脈，定知不久炁長吁。","大抵七表八裏脈，相連九道作程途。","表裏脈分輕重病，九怪傳來病不舒。","胗脈要分輕與少，始知生死可枝梧。","浮洪短促爲陽弱，沉細兼長陰有餘。","如此分張輕重斷，豈同俗眼一凡夫。","六部鬼賊是如何，造化陰陽事更多。","心火怕逢沉滑脈，肺金猶怕浮洪克。","唯有脾元惡木侵，四時寄旺本無形。","甲乙最嫌金炁重，腎中脈緩水無盈。","一位克重當須斷，二位克重却分輕。","三位克時難救療，縱然暫醒必歸冥。","水火相臨分上下，金木相侵事必凌。","水土二宮俱要靜，一宮有克少安寧。","高士要知刑克賊，孰能考究記心經。","春怕庚辛秋惡候，夏嫌水氣火相刑。","刑剋只分輕與重，自然切脈甚精明。","左手胗得重病脈，右手脈候却調勻。","只斷脈中須應病，故知命脈得和平。","假此一例餘倣此，醫門學者要勞心。","（以上三首均見《宛委別藏》影寫本杜光庭《廣成先生玉函經》。","）。"]', '["浮弦多是风头痛，積聚體疼胸膈噎。","緊實號爲寒熱證，澁瀉煩燥小便澁。","芤脈蓋因陽耗散，鼻衂無时精炁竭。","脈沉兼优是重陰，氣刺胸膨癥塊結。","风寒相傳脈浮遲，外受寒邪內风熱。","肺受风寒痰欬嗽，左手见之心戰佚。","弱而兼濡是陽虛，汗出憎寒炁羸劣。","风濕风溫及濕溫，脈候交差要分別。","汗無重汗耳無知，妄語無瘖各部委是暍。","洪數脈来陽氣盛，目赤舌乾唇破裂。","浮而兼緊腎之虛，溫助寒邪益精血。","陽絕尺中脈細微，針灸勿令精炁絕。","促結代脈是脾虛，若见之时难救得，女人尺中須要盛，浮細沉遲是虛證。","忽然胗得寸中盈，六部無邪身有孕。","童女童男何以別？須看天真無損缺。","大凡童子脈来沉，童女尺中洪拍拍。","男子婦人精血衰，假饒覆溢脈無回。","一呼四至爲平脈，一呼一至死相催。","傷寒舌黑洗不紅，藥洗分明定吉凶。","汗若脈和無惡候，脈如躁疾命將殂。","中风目閉口开者，喉中拽鋸炁不敷。","脈若洪弦由可救，浮大多應命不甦。","男女五勞洪數脈，定知不久炁长吁。","大抵七表八裏脈，相連九道作程途。","表裏脈分轻重病，九怪傳来病不舒。","胗脈要分轻與少，始知生死可枝梧。","浮洪短促爲陽弱，沉細兼长陰有餘。","如此分張轻重斷，豈同俗眼一凡夫。","六部鬼賊是如何，造化陰陽事更多。","心火怕逢沉滑脈，肺金猶怕浮洪克。","唯有脾元惡木侵，四时寄旺本無形。","甲乙最嫌金炁重，腎中脈緩水無盈。","一位克重當須斷，二位克重却分轻。","三位克时难救療，縱然暫醒必归冥。","水火相臨分上下，金木相侵事必凌。","水土二宮俱要静，一宮有克少安寧。","高士要知刑克賊，孰能考究記心經。","春怕庚辛秋惡候，夏嫌水氣火相刑。","刑剋只分轻與重，自然切脈甚精明。","左手胗得重病脈，右手脈候却調勻。","只斷脈中須應病，故知命脈得和平。","假此一例餘倣此，醫门学者要勞心。","（以上三首均见《宛委別藏》影寫本杜光庭《廣成先生玉函經》。","）。"]', '诗', 'shi', '', NULL, '生死歌訣 三 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45b173b7-7aab-4b2e-b2de-0b475ecfd4f4', '壽鄧將軍 一', '壽鄧將軍 一', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["文星一夜動天關，此日真仙降世間。","千里光華蟾影滿，九臯空闊鶴情閑。","臨戎暫許分憂寄，入相看隨急詔還。","自愧嘉辰無異禮，祇將吟咏祝崇山。"]', '["文星一夜动天关，此日真仙降世间。","千里光华蟾影满，九臯空闊鹤情闲。","臨戎暫許分憂寄，入相看隨急詔還。","自愧嘉辰無異禮，祇將吟咏祝崇山。"]', '诗', 'shi', '', NULL, '壽鄧將軍 一 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86eda77a-6743-4898-8856-b172e2a9b091', '壽鄧將軍 二', '壽鄧將軍 二', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["當年五百合生賢，自入青雲更不還。","嶽氣此時來世上，文星今日到人間。","降因天下悲姚宋，出爲儒門繼閔顏。","惟有感恩無路報，一生傾酒祝南山。","（影印本《詩淵》第六冊第四五四○頁。","）。"]', '["當年五百合生賢，自入青云更不還。","嶽氣此时来世上，文星今日到人间。","降因天下悲姚宋，出爲儒门繼閔顏。","惟有感恩無路報，一生傾酒祝南山。","（影印本《诗淵》第六冊第四五四○頁。","）。"]', '诗', 'shi', '', NULL, '壽鄧將軍 二 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('024a40d5-0f89-4e2f-9bfe-e9a6ff0bc074', '太陽真君呪', '太陽真君呪', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["東望扶桑宮，稽首朝鬱儀。","太陽洞明景，寥寥何所思。","令我拜金色，候天望英姿。","皇華將玉女，臨軒降此時。"]', '["东望扶桑宮，稽首朝鬱儀。","太陽洞明景，寥寥何所思。","令我拜金色，候天望英姿。","皇华將玉女，臨軒降此时。"]', '诗', 'shi', '', NULL, '太陽真君呪 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32d4eeb1-1812-40e3-966f-3110d7c7e496', '太陰真君呪', '太陰真君呪', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["仰望顧八表，惟月孕陰精。","中有大素皇，夫人駕綠軿。","曜華光二極，混明照三清。","慇懃求志道，五色下來迎。"]', '["仰望顧八表，惟月孕陰精。","中有大素皇，夫人駕綠軿。","曜华光二極，混明照三清。","慇懃求志道，五色下来迎。"]', '诗', 'shi', '', NULL, '太陰真君呪 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6aefb3af-a120-40e1-869e-72e9950c2d0b', '木德星君呪', '木德星君呪', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["歲星乘木德，展望耀東鄉。","淩天姿潤澤，正色滉明皇，尋華歌浩漾，擲水詠芝芳。","經時頻禱祝，獲福自然長。","。"]', '["歲星乘木德，展望耀东乡。","淩天姿潤澤，正色滉明皇，尋华歌浩漾，擲水詠芝芳。","經时頻禱祝，獲福自然长。","。"]', '诗', 'shi', '', NULL, '木德星君呪 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71d184fe-f347-40e6-9aad-20f1337449aa', '火德星君呪', '火德星君呪', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["芒角森龍鳳，威光叱十方。","丹罡耀午夜，朱火焰三邊。","晶明符正炁，劍戟炴兵權。","欃槍應滅跡，孛慧敢當前。"]', '["芒角森龙鳳，威光叱十方。","丹罡耀午夜，朱火焰三邊。","晶明符正炁，劍戟炴兵權。","欃槍應滅跡，孛慧敢當前。"]', '诗', 'shi', '', NULL, '火德星君呪 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc7cc4ae-3526-4695-843c-e6c2d3ecdcbb', '金德星君呪', '金德星君呪', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["太白淩清漢，騰霜耀素英。","亭亭浮瑞彩，皎皎盛長庚。","鋒高能禦寇，色潤每降兵。","推窮符曆數，合道與長生。"]', '["太白淩清漢，腾霜耀素英。","亭亭浮瑞彩，皎皎盛长庚。","鋒高能禦寇，色潤每降兵。","推窮符曆數，合道與长生。"]', '诗', 'shi', '', NULL, '金德星君呪 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f795216-d28c-4d8e-b859-8beb235b3394', '水德星君呪', '水德星君呪', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["妙哉符五炁，彷彿見真門。","嵯峨當丑位，壬癸洞靈君。","分輝凝皎潔，盻蠁赴思存。","仙歌將舞蹈，良久下金天。"]', '["妙哉符五炁，彷彿见真门。","嵯峨當丑位，壬癸洞靈君。","分輝凝皎潔，盻蠁赴思存。","仙歌將舞蹈，良久下金天。"]', '诗', 'shi', '', NULL, '水德星君呪 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cdfb62a-7220-44a0-9f27-29cd1cb4dc2f', '土德星君呪', '土德星君呪', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["高穹符戊己，藏陸起重霄。","五行尊暗曜，九土見光昭。","甘石推留伏，陶巫筭深寥。","上仙垂雨露，伏地禮空謠。"]', '["高穹符戊己，藏陸起重霄。","五行尊暗曜，九土见光昭。","甘石推留伏，陶巫筭深寥。","上仙垂雨露，伏地禮空謠。"]', '诗', 'shi', '', NULL, '土德星君呪 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcf5c273-57c9-4264-8134-2f2c18a322ed', '羅㬋星君呪', '羅㬋星君呪', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["神首循黑道，冥冥超至靈。","晴明期朔望，陽德晦陰精。","高鎮黃旛闕，矛戟耀霜鈴。","志心伺多福，稽首諷真經。"]', '["神首循黑道，冥冥超至靈。","晴明期朔望，陽德晦陰精。","高鎮黄旛闕，矛戟耀霜鈴。","志心伺多福，稽首諷真經。"]', '诗', 'shi', '', NULL, '羅㬋星君呪 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a06b0116-bd64-43f8-82ff-fb0d592ed224', '計都星君呪', '計都星君呪', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["處暗表陰德，豹尾鎮星宮。","怒指摧山嶽，權雄暝太空。","龍蛇生怪狀，變異忽昏濛。","主人長壽榮，禳應在恪恭。"]', '["处暗表陰德，豹尾鎮星宮。","怒指摧山嶽，權雄暝太空。","龙蛇生怪狀，变異忽昏濛。","主人长壽榮，禳應在恪恭。"]', '诗', 'shi', '', NULL, '計都星君呪 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22964416-8550-4c4d-8e1e-a2bfd14ed9da', '紫炁星君呪', '紫炁星君呪', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["授制宗元帝，含精耀紫微。","陰陽乘運極，幽顯閟靈機。","玉輿登馬漢，金鈴布斗飛。","四宿循周度，九土尊天威。"]', '["授制宗元帝，含精耀紫微。","陰陽乘運極，幽显閟靈機。","玉輿登马漢，金鈴布斗飞。","四宿循周度，九土尊天威。"]', '诗', 'shi', '', NULL, '紫炁星君呪 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('882fbafb-6465-4ec7-b689-db9b0e9bc641', '月孛星君呪', '月孛星君呪', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["太陰光玉緯，精魄育羣生。","青桂黃華輔，鬱羅保素靈。","毛頭分怪狀，彗尾或潛經。","舍次流災房，齋修洞香冥。"]', '["太陰光玉緯，精魄育羣生。","青桂黄华輔，鬱羅保素靈。","毛头分怪狀，彗尾或潛經。","舍次流災房，斋修洞香冥。"]', '诗', 'shi', '', NULL, '月孛星君呪 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bcd374f-0b28-4197-9e2e-3d0518656743', '本命呪', '本命呪', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["本命尊威赫，元辰位豹宮。","三元分品秩，六十衛躔躬。","仙吏牌神化，真官亦治功。","人倫無貴賤，終始賴含洪。","（《正統道藏》本杜光庭《道門科範大全集》卷四八。","）。"]', '["本命尊威赫，元辰位豹宮。","三元分品秩，六十衛躔躬。","仙吏牌神化，真官亦治功。","人倫無貴賤，終始賴含洪。","（《正統道藏》本杜光庭《道门科範大全集》卷四八。","）。"]', '诗', 'shi', '', NULL, '本命呪 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c1fd6e4-83af-4c6f-affc-2d5674a349a2', '賀府主令公甘雨應祈', '賀府主令公甘雨應祈', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["一炷名香達杳冥，旋聞風雨應精誠。","染來山嶽千重翠，洗盡塵埃六合清。","不獨旱苗蘇壠畝，便期嘉穀遍寰瀛。","須知至理調元化，丞相爲霖致太平。","（宋呂祖謙《詩律武庫後集》卷十。","）。"]', '["一炷名香達杳冥，旋闻风雨應精誠。","染来山嶽千重翠，洗尽塵埃六合清。","不独旱苗蘇壠畝，便期嘉穀遍寰瀛。","須知至理調元化，丞相爲霖致太平。","（宋呂祖謙《诗律武庫後集》卷十。","）。"]', '诗', 'shi', '', NULL, '賀府主令公甘雨應祈 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1dc7820-0976-472a-8fd5-22cbc8f65d64', '詩', '诗', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["數聲鷄唱錦夢樓，引得春風散錦川。","星斗似沈初報曉，羽儀如畫已朝天。","翠華尚未離三蜀，白日那堪又一年。","秖如明時位多感，瑤爐重炷祝堯烟。","（宋無名氏《翰苑新書前集》卷六十三。","《分門纂類唐宗時賢千家詩選》卷十六聞人祥正《集句》引首句。","）。"]', '["數声鷄唱錦梦楼，引得春风散錦川。","星斗似沈初報晓，羽儀如畫已朝天。","翠华尚未離三蜀，白日那堪又一年。","秖如明时位多感，瑤爐重炷祝堯烟。","（宋無名氏《翰苑新书前集》卷六十三。","《分门纂類唐宗时賢千家诗選》卷十六闻人祥正《集句》引首句。","）。"]', '诗', 'shi', '', NULL, '詩 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43669289-259e-4d68-b0a9-3d743d639e38', '通玄讚八首 一', '通玄讚八首 一', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["至道常虛寂，玄化應真精。","分神通一切，凝景在三清。","恍惚生有象，沖寞見無形。","逐運開緣會，因機說娒對。","修之登景漢，慢之墮幽囹。","天女散金華，神童唱玉聲。","十華迴寶蓋，九鳳遏雲營。","若能弘至賾，家國悉安寧。"]', '["至道常虛寂，玄化應真精。","分神通一切，凝景在三清。","恍惚生有象，沖寞见無形。","逐運开緣會，因機说娒对。","修之登景漢，慢之墮幽囹。","天女散金华，神童唱玉声。","十华迴寶蓋，九鳳遏云營。","若能弘至賾，家国悉安寧。"]', '诗', 'shi', '', NULL, '通玄讚八首 一 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8cf695d-5d1d-4951-a02a-a0710e07de5e', '通玄讚八首 二', '通玄讚八首 二', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["五億諸天界，三千道境中。","是非更有待，生死互無窮。","妄起貪瞋獄，虛成殺害宮。","謬言人我異，安知彼此同。","六骸俱不實，萬法悉歸空。","體道煩惱盡，心與色塵終。","未能求解脫，常只處攀籠。","若欲常自在，稽首至道宗。"]', '["五億諸天界，三千道境中。","是非更有待，生死互無窮。","妄起貪瞋獄，虛成殺害宮。","謬言人我異，安知彼此同。","六骸俱不實，万法悉归空。","體道煩惱尽，心與色塵終。","未能求解脫，常只处攀籠。","若欲常自在，稽首至道宗。"]', '诗', 'shi', '', NULL, '通玄讚八首 二 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ea83a59-2c2e-424c-aa2d-bb979d03feaf', '通玄讚八首 三', '通玄讚八首 三', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["天堂與地獄，凡夫及聖人。","悉從方寸起，非復有餘因。","悟則聰明友，迷爲愚瞽隣。","苦魂服務有識，罪魄亦含神。","何爲沈惱難，良由不信真。","棄此身上寶，染彼世間塵。","既依流浪海，還沒死生津。","若欲渡此苦，安坐自觀身。"]', '["天堂與地獄，凡夫及聖人。","悉從方寸起，非复有餘因。","悟則聰明友，迷爲愚瞽隣。","苦魂服務有識，罪魄亦含神。","何爲沈惱难，良由不信真。","棄此身上寶，染彼世间塵。","既依流浪海，還沒死生津。","若欲渡此苦，安坐自观身。"]', '诗', 'shi', '', NULL, '通玄讚八首 三 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1622742d-e4ca-4e98-8704-13b92881da5c', '通玄讚八首 四', '通玄讚八首 四', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["善哉元始尊，慈悲度一切。","德出虛空表，功滿塵沙界。","廣說大乘經，發生無上慧。","輪迴周億劫，教化通三世。","精貫有形中，妙窮無色際。","迹遍方方域，道應天天帝。","權實度天人，機緣隨巨細。","神用難可窮，方圓無不制。"]', '["善哉元始尊，慈悲度一切。","德出虛空表，功满塵沙界。","廣说大乘經，發生無上慧。","輪迴周億劫，教化通三世。","精貫有形中，妙窮無色際。","迹遍方方域，道應天天帝。","權實度天人，機緣隨巨細。","神用难可窮，方圓無不制。"]', '诗', 'shi', '', NULL, '通玄讚八首 四 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5f518a3-197d-4065-8fc8-11c4f59c475c', '通玄讚八首 五', '通玄讚八首 五', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["罪福猶鏡象，生死若輪迴。","但觀明裏去，誰識暗中來。","未慕三天闕，唯愁五苦臺。","罪魂隨運盡，幽魄應緣開。","精氣空浮爽，形骸久化灰。","且甘爲鬼質，誰念入仙胎。","徒願青書錄，終悲黑簿催。","法輪難再覩，長夜足堪哀。"]', '["罪福猶镜象，生死若輪迴。","但观明裏去，誰識暗中来。","未慕三天闕，唯愁五苦台。","罪魂隨運尽，幽魄應緣开。","精氣空浮爽，形骸久化灰。","且甘爲鬼質，誰念入仙胎。","徒願青书錄，終悲黑簿催。","法輪难再覩，长夜足堪哀。"]', '诗', 'shi', '', NULL, '通玄讚八首 五 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c442e76d-68eb-478e-9f15-5d38544c3fe4', '通玄讚八首 六', '通玄讚八首 六', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["我身良可惜，宜各修生道。","孰云白玉芝，多蒔黃金草。","結志行六度，專心論三寶。","白元來降接，赤子常攜抱。","朽年慙晚學，壯歲須及早。","知足自逍遙，貪榮更憂惱。","坐觀環堵大，靜覺乾坤小。","守一若無移，終天豈云老。"]', '["我身良可惜，宜各修生道。","孰云白玉芝，多蒔黄金草。","結志行六度，專心論三寶。","白元来降接，赤子常携抱。","朽年慙晚学，壯歲須及早。","知足自逍遙，貪榮更憂惱。","坐观环堵大，静覺乾坤小。","守一若無移，終天豈云老。"]', '诗', 'shi', '', NULL, '通玄讚八首 六 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80b7ddc3-fc87-4531-bb65-706325122ee4', '通玄讚八首 七', '通玄讚八首 七', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["三千分世界，五億化諸天。","一一開淨域，方方有聖緣。","九光生院草，七寶滿池蓮。","行館排朱日，飛臺映紫泉。","燒香皆玉女，說法盡神仙。","梵引九嘯鳳，鑪飄五色烟。","稽首虛皇闕，歌詠太上前。","慎莫忽宿命，當須信福田。"]', '["三千分世界，五億化諸天。","一一开淨域，方方有聖緣。","九光生院草，七寶满池蓮。","行館排朱日，飞台映紫泉。","燒香皆玉女，说法尽神仙。","梵引九嘯鳳，鑪飄五色烟。","稽首虛皇闕，歌詠太上前。","慎莫忽宿命，當須信福田。"]', '诗', 'shi', '', NULL, '通玄讚八首 七 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6aa1df49-6b4f-484a-92f3-054e8f32c58e', '通玄讚八首 八', '通玄讚八首 八', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["道化三元布，神凝萬像分。","龍漢開玄籙，天書下赤渾。","應期鏗法鼓，隨方啓妙門。","太上垂至賾，威德被乾坤。","神經三一侍，妙理五千文。","字列金華府，名傳玉帝君。","心中生寶日，身上起羅雲。","十仙何足友，載刼乃長存。"]', '["道化三元布，神凝万像分。","龙漢开玄籙，天书下赤渾。","應期鏗法鼓，隨方啓妙门。","太上垂至賾，威德被乾坤。","神經三一侍，妙理五千文。","字列金华府，名傳玉帝君。","心中生寶日，身上起羅云。","十仙何足友，載刼乃长存。"]', '诗', 'shi', '', NULL, '通玄讚八首 八 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1ef9ac2-b047-4a53-977d-f9022c9a64bc', '授經讚', '授經讚', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["飄飄太虛嶺，流景在上玄。","經始無終劫，常保天地人。","國主學理世，道士誦得仙。","賢者今奉受，依法以相傳。","時無至德子，保秘不妄宣。","宗之昇太清，棄之墮九泉。","我說無爲道，沖寂得自然。"]', '["飄飄太虛嶺，流景在上玄。","經始無終劫，常保天地人。","国主学理世，道士誦得仙。","賢者今奉受，依法以相傳。","时無至德子，保秘不妄宣。","宗之昇太清，棄之墮九泉。","我说無爲道，沖寂得自然。"]', '诗', 'shi', '', NULL, '授經讚 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35f0a92a-30e9-45e0-8eee-5516f1ec4eca', '光明讚', '光明讚', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["立功須及早，學道亦當時。","晝夜宜勤學，發意莫狐疑。","燒香常禮拜，誦經恒奉師。","勇猛加精進，專誠無想思。","四等將六度，三奔與五雌。","洗塵入空寂，虛心將自持。","唯期不轉退，豈爲人所嗤。","若能如是者，朝夕自仙飛。"]', '["立功須及早，学道亦當时。","晝夜宜勤学，發意莫狐疑。","燒香常禮拜，誦經恒奉師。","勇猛加精進，專誠無想思。","四等將六度，三奔與五雌。","洗塵入空寂，虛心將自持。","唯期不轉退，豈爲人所嗤。","若能如是者，朝夕自仙飞。"]', '诗', 'shi', '', NULL, '光明讚 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c921dc5-be75-4fec-82a0-9091c85b19a9', '真人讚六首 一', '真人讚六首 一', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["大道難無甚，可以有情求。","佇駕空洞中，迴眄翳滄流。","淨明三界外，蕭蕭玉京遊。","自無玄挺運，誰能悟冥趣。","落落天漢澄，俯仰即虛柔。","七玄散幽夜，返胎順沈浮。","冥期苟潛凝，陽九無虞憂。","覩此去來會，時復爲淹留。","外身而身存，真仙會良儔。"]', '["大道难無甚，可以有情求。","佇駕空洞中，迴眄翳滄流。","淨明三界外，蕭蕭玉京游。","自無玄挺運，誰能悟冥趣。","落落天漢澄，俯仰即虛柔。","七玄散幽夜，返胎順沈浮。","冥期苟潛凝，陽九無虞憂。","覩此去来會，时复爲淹留。","外身而身存，真仙會良儔。"]', '诗', 'shi', '', NULL, '真人讚六首 一 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bf22e19-795c-4061-87f6-2309daee9f92', '真人讚六首 二', '真人讚六首 二', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["亹亹玄中趣，湛湛清漢波。","代謝若旋環，椿木不改柯。","靜心念至真，隨運順離羅。","感應理常通，神適逮自徂。","澹游初無際，繁想洞九遐。","飛根散玄葉，理返非由他。","常能誦玉章，玄音徹霄霞。","甲申洪災至，椌翮王母家。","永享無終紀，豈知年劫多。"]', '["亹亹玄中趣，湛湛清漢波。","代謝若旋环，椿木不改柯。","静心念至真，隨運順離羅。","感應理常通，神適逮自徂。","澹游初無際，繁想洞九遐。","飞根散玄葉，理返非由他。","常能誦玉章，玄音徹霄霞。","甲申洪災至，椌翮王母家。","永享無終紀，豈知年劫多。"]', '诗', 'shi', '', NULL, '真人讚六首 二 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d44cce9-789c-4453-8b59-fd1755389558', '真人讚六首 三', '真人讚六首 三', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["玄者七寶林，十華幷彌羅。","紫烟冠靈暉，雲京秀玉阿。","上有福德堂，宮室互參差。","皆是清信士，真仙飛天家。","三界通玄路，五道清不邪。","善緣應根生，累功享福多。","牽對相尋續，大法諒不虛。","無有萬年人，皆與劫同徂。","依依歡樂世，發言成詠歌。","此世歡無極，常奈來運何。"]', '["玄者七寶林，十华幷彌羅。","紫烟冠靈暉，云京秀玉阿。","上有福德堂，宮室互參差。","皆是清信士，真仙飞天家。","三界通玄路，五道清不邪。","善緣應根生，累功享福多。","牽对相尋續，大法諒不虛。","無有万年人，皆與劫同徂。","依依歡乐世，發言成詠歌。","此世歡無極，常奈来運何。"]', '诗', 'shi', '', NULL, '真人讚六首 三 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb6d6fc3-1afd-4acf-b22b-d2ad9bdd00cf', '真人讚六首 四', '真人讚六首 四', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["八觀因緣門，四福從中生。","時見有心者，思悟感天靈。","吾今爲是故開說真妙經。","如從經中言，憶劫皆受榮。","習道行勸戒，以經度我形。","思念宿命根，洗拔先身嬰。","超越過三羅，八難於是冥。"]', '["八观因緣门，四福從中生。","时见有心者，思悟感天靈。","吾今爲是故开说真妙經。","如從經中言，憶劫皆受榮。","習道行勸戒，以經度我形。","思念宿命根，洗拔先身嬰。","超越過三羅，八难於是冥。"]', '诗', 'shi', '', NULL, '真人讚六首 四 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b228359e-9faa-42bb-86cd-928ed73e3513', '真人讚六首 五', '真人讚六首 五', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["魂返入定質，神操從是榮。","滅度如蛻胞，曠朗覩八清。","轉輪得神仙，由我改心精。","受報無窮量，志定入福庭。","七十二相好，皆從身中明。","頂負七寶光，照耀諸天形。","雲迅八景輿，風迴匡縁軿。","昇入玄玄門，期樂樂未央。","。"]', '["魂返入定質，神操從是榮。","滅度如蛻胞，曠朗覩八清。","轉輪得神仙，由我改心精。","受報無窮量，志定入福庭。","七十二相好，皆從身中明。","頂負七寶光，照耀諸天形。","云迅八景輿，风迴匡縁軿。","昇入玄玄门，期乐乐未央。","。"]', '诗', 'shi', '', NULL, '真人讚六首 五 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('208f813a-3c7b-4a70-9bfa-2b5f30a2ba3a', '真人讚六首 六', '真人讚六首 六', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["妙通轉我神，弘普無量功。","道成天地初，輪化發九重。","滅度歷生死，緣對各有宗。","孰悟去來苦，形魂無始終。","積善隆福基，身拔五難鋒。","脫離三亞道，蕭蕭入閑堂。","念度無邊境，思定感神通。","法輪三度迴，輔我高仙功。","迴我大椿步，飄昇太極宮。"]', '["妙通轉我神，弘普無量功。","道成天地初，輪化發九重。","滅度歷生死，緣对各有宗。","孰悟去来苦，形魂無始終。","積善隆福基，身拔五难鋒。","脫離三亞道，蕭蕭入闲堂。","念度無邊境，思定感神通。","法輪三度迴，輔我高仙功。","迴我大椿步，飄昇太極宮。"]', '诗', 'shi', '', NULL, '真人讚六首 六 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da7075fb-4094-459b-a4c0-36349fb919cd', '奉戒讚', '奉戒讚', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["奉戒爲身寶，永劫享靈期。","虛心會虛寂，精感在精思。","九鸞陪玉軼，八鳳薦金芝。","青童歌妙曲，玄女唱清詞。","神尊示光景，太上湛希夷。","天華雜香起，法雨散靈滋。","勤苦修生道，翹想作仙基。","精誠如不怠，鶴駕自當之。","（以上十七首，均見《正統道藏》本杜光庭《太上三洞傳授道德經紫虛籙拜表儀》。","）。"]', '["奉戒爲身寶，永劫享靈期。","虛心會虛寂，精感在精思。","九鸾陪玉軼，八鳳薦金芝。","青童歌妙曲，玄女唱清词。","神尊示光景，太上湛希夷。","天华杂香起，法雨散靈滋。","勤苦修生道，翹想作仙基。","精誠如不怠，鹤駕自當之。","（以上十七首，均见《正統道藏》本杜光庭《太上三洞傳授道德經紫虛籙拜表儀》。","）。"]', '诗', 'shi', '', NULL, '奉戒讚 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5f23f64-72dd-48fc-b25b-fe3fc696a15f', '受送頌', '受送頌', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["此法甚高妙，免汝九祖役。","是其人不授，令人與道隔。","非人而輒授，見世被考責。","死墮三途獄，萬劫悔無益。","（《正棄道藏》本杜光庭《太上三五正一盟威閱籙醮儀》。","）。"]', '["此法甚高妙，免汝九祖役。","是其人不授，令人與道隔。","非人而輒授，见世被考責。","死墮三途獄，万劫悔無益。","（《正棄道藏》本杜光庭《太上三五正一盟威閱籙醮儀》。","）。"]', '诗', 'shi', '', NULL, '受送頌 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fac018b-2549-43de-a573-e6929ddc7272', '天壇王屋山聖迹頌', '天壇王屋山聖迹頌', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["王屋天壇福地玄，清虛小有洞天仙。","無鄰勝境於人物，石感神通古今傳。","（《正統道藏》本杜光庭《天壇王屋山聖迹記》。","）。"]', '["王屋天壇福地玄，清虛小有洞天仙。","無鄰勝境於人物，石感神通古今傳。","（《正統道藏》本杜光庭《天壇王屋山聖迹記》。","）。"]', '诗', 'shi', '', NULL, '天壇王屋山聖迹頌 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f3a1def-5203-44cc-8a87-3f2373785157', '句 一', '句 一', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["五行正氣產黃花。","（宋史鑄《百菊集譜》卷六集句引。","）。"]', '["五行正氣產黄花。","（宋史鑄《百菊集譜》卷六集句引。","）。"]', '诗', 'shi', '', NULL, '句 一 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c9eff62-e90a-4615-a59a-ef951d9707dd', '句 二', '句 二', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["天地西南思早蟾，弓門環盡勢纖纖。","（元刻本林楨《聯新事備詩學大成》卷一。","）。"]', '["天地西南思早蟾，弓门环尽勢纖纖。","（元刻本林楨《聯新事備诗学大成》卷一。","）。"]', '诗', 'shi', '', NULL, '句 二 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e02f0332-111a-464a-8188-e4ac82f29ddc', '句 三', '句 三', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["可惜年華容易過。","（胡偉《宮詞》。","）。"]', '["可惜年华容易過。","（胡偉《宮词》。","）。"]', '诗', 'shi', '', NULL, '句 三 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e801c675-a8f5-4113-9e21-ff38731aa9f8', '步虛詞 一', '步虛词 一', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["旋行躡雲綱，乘虛步玄紀。","吟詠帝一尊，百關自調理。","俯命八海暗示，仰攜高仙子。","諸天散香花，蕭然靈風起。","宿願定命根，故致標高擬。","歡樂太上前，萬劫猶未始。"]', '["旋行躡云綱，乘虛步玄紀。","吟詠帝一尊，百关自調理。","俯命八海暗示，仰携高仙子。","諸天散香花，蕭然靈风起。","宿願定命根，故致標高擬。","歡乐太上前，万劫猶未始。"]', '诗', 'shi', '', NULL, '步虛詞 一 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0da6650-334b-4b4e-aad9-ebdfd34827c8', '步虛詞 二', '步虛词 二', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["嵯峨玄都山，十方宗皇一。","岧岧於寶臺，光明焰流日。","煒燁玉林華，蒨璨耀朱實。","常念餐元精，鍊液固形質。","金光散紫微，窈窕大乘逸。"]', '["嵯峨玄都山，十方宗皇一。","岧岧於寶台，光明焰流日。","煒燁玉林华，蒨璨耀朱實。","常念餐元精，鍊液固形質。","金光散紫微，窈窕大乘逸。"]', '诗', 'shi', '', NULL, '步虛詞 二 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f5872b5-e564-4aae-b340-57b130b4c41d', '步虛詞 三', '步虛词 三', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["俯仰存太上，華景秀丹田。","左顧提鬱儀，右盼攜結璘。","六度觀梵行，道德了袒新。","宿命積福應，聞經若至親。","天扔超世才，樂誦希微篇。","沖虛太和氣，吐納流霞津。","胎息靜百關，寥寥究三便。","泥丸洞明鏡，遂成金華仙。","魔王敬受事，故能朝諸天。","皆從齋戒起，累功結宿緣。","飛行淩太虛，提攜高上人。","（《正統道藏》本杜光庭《太上黃籙齋儀》卷一。","）。"]', '["俯仰存太上，华景秀丹田。","左顧提鬱儀，右盼携結璘。","六度观梵行，道德了袒新。","宿命積福應，闻經若至親。","天扔超世才，乐誦希微篇。","沖虛太和氣，吐納流霞津。","胎息静百关，寥寥究三便。","泥丸洞明镜，遂成金华仙。","魔王敬受事，故能朝諸天。","皆從斋戒起，累功結宿緣。","飞行淩太虛，提携高上人。","（《正統道藏》本杜光庭《太上黄籙斋儀》卷一。","）。"]', '诗', 'shi', '', NULL, '步虛詞 三 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e04c27f-75bc-4f37-b5e5-b7c78e189898', '步虛詞 四', '步虛词 四', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["控轡適十方，旋憇玄景阿。","仰觀劫仞臺，俯眄紫雲羅。","逍遙太上景，相與坐蓮華。","積學爲真人，恬然榮衛和。","永享無期壽，萬椿所奚足多。","（同前卷五。","）。"]', '["控轡適十方，旋憇玄景阿。","仰观劫仞台，俯眄紫云羅。","逍遙太上景，相與坐蓮华。","積学爲真人，恬然榮衛和。","永享無期壽，万椿所奚足多。","（同前卷五。","）。"]', '诗', 'shi', '', NULL, '步虛詞 四 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d79ad499-1bd9-419f-89d8-c24d9937da7a', '步虛詞 五', '步虛词 五', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["大道師玄寂，昇仙友無英。","公子度靈符，太一捧洞章。","舍利耀所以姿，龍駕倏來迎。","天尊眄雲輿，飄飄乘虛翔。","香花若飛雪，氛靄茂玄梁。","（同前卷六。","）。"]', '["大道師玄寂，昇仙友無英。","公子度靈符，太一捧洞章。","舍利耀所以姿，龙駕倏来迎。","天尊眄云輿，飄飄乘虛翔。","香花若飞雪，氛靄茂玄梁。","（同前卷六。","）。"]', '诗', 'shi', '', NULL, '步虛詞 五 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2147541-9726-4493-bd11-619f2a51c7d1', '步虛詞 六', '步虛词 六', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["頭腦禮金闕，攜手遨玉京。","騫樹圓景園，煥爛七寶林。","天獸三百名，師子巨萬尋。","飛龍躑躅吟，神鳳應節鳴。","靈風扇奇華，清香散人襟。","自無高仙才，焉能耽此心。","（同前卷七。","）。"]', '["头腦禮金闕，携手遨玉京。","騫樹圓景园，煥爛七寶林。","天獸三百名，師子巨万尋。","飞龙躑躅吟，神鳳應節鳴。","靈风扇奇华，清香散人襟。","自無高仙才，焉能耽此心。","（同前卷七。","）。"]', '诗', 'shi', '', NULL, '步虛詞 六 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4d7de05-5807-403b-8a64-79b2ff4e3a0a', '步虛詞 七', '步虛词 七', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["嚴我九龍駕，乘虛以逍遙。","八天如指掌，六合何足遼。","衆真誦洞玄，太上唱清謠。","香華隨風散，玉音成紫霄。","五苦一時迸，八難順經寥。","妙哉靈寶囿，興此大法橋。","（同前卷八。","）。"]', '["嚴我九龙駕，乘虛以逍遙。","八天如指掌，六合何足遼。","衆真誦洞玄，太上唱清謠。","香华隨风散，玉音成紫霄。","五苦一时迸，八难順經寥。","妙哉靈寶囿，兴此大法橋。","（同前卷八。","）。"]', '诗', 'shi', '', NULL, '步虛詞 七 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b0621cd-4ca0-427b-8f09-e5c9841dae5a', '步虛詞 八', '步虛词 八', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["稽首禮太上，燒香歸虛無。","流明隨手迴，法輪亦三周。","玄順四大興，靈慶及王侯。","七祖生天堂，煌煌耀景敷。","嘯歌冠太漠，天樂適我娛。","齊馨無上德，下仙不與儔。","妙想明玄覺，詵詵乘虛遊。","（同前卷廿二。","）。"]', '["稽首禮太上，燒香归虛無。","流明隨手迴，法輪亦三周。","玄順四大兴，靈慶及王侯。","七祖生天堂，煌煌耀景敷。","嘯歌冠太漠，天乐適我娛。","齊馨無上德，下仙不與儔。","妙想明玄覺，詵詵乘虛游。","（同前卷廿二。","）。"]', '诗', 'shi', '', NULL, '步虛詞 八 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64cffe86-ca8f-4ca0-8633-2a057d3b3cb7', '步虛詞 九', '步虛词 九', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["太極分高厚，輕清上屬天。","人能修至道，身乃作真仙。","行溢三千數，時丁四萬年。","丹臺開寶笈，金口爲流傳。","（同前卷廿六。","）。"]', '["太極分高厚，轻清上屬天。","人能修至道，身乃作真仙。","行溢三千數，时丁四万年。","丹台开寶笈，金口爲流傳。","（同前卷廿六。","）。"]', '诗', 'shi', '', NULL, '步虛詞 九 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('310d6374-3ec7-4ea3-be39-c219ed3a4e3d', '步虛詞 十', '步虛词 十', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["大梵三天主，虛皇五老尊。","尚難窺徼妙，豈復入名言。","寶座臨金殿，霞冠照玉軒。","萬真朝帝所，飛舃躡雲根。","（同前。","）。"]', '["大梵三天主，虛皇五老尊。","尚难窺徼妙，豈复入名言。","寶座臨金殿，霞冠照玉軒。","万真朝帝所，飞舃躡云根。","（同前。","）。"]', '诗', 'shi', '', NULL, '步虛詞 十 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('914e3c49-628b-45c9-91fa-a7998df66da3', '步虛詞 十一', '步虛词 十一', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["濛濛如細霧，冉冉曳銖衣。","妙逐祥烟上，輕隨綵鳳飛。","幾陪瑤室宴，忽指洞天歸。","佇立扶桑岸，高奔日帝暉。","（同前。","）。"]', '["濛濛如細霧，冉冉曳銖衣。","妙逐祥烟上，轻隨綵鳳飞。","幾陪瑤室宴，忽指洞天归。","佇立扶桑岸，高奔日帝暉。","（同前。","）。"]', '诗', 'shi', '', NULL, '步虛詞 十一 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c64321e-31fa-4513-bad5-a1585e1dcf43', '步虛詞 十二', '步虛词 十二', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["旋步雲綱上，天風颯爾吹。","飄裾淩斗柄，秉拂揖參旗。","獅子銜丹綬，麒麟導翠輜。","飛行周八極，幾見發春枝。","（同前卷二七。","）。"]', '["旋步云綱上，天风颯爾吹。","飄裾淩斗柄，秉拂揖參旗。","獅子銜丹綬，麒麟導翠輜。","飞行周八極，幾见發春枝。","（同前卷二七。","）。"]', '诗', 'shi', '', NULL, '步虛詞 十二 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a236fb53-8d24-4b11-881e-32be75225f59', '步虛詞 十三', '步虛词 十三', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["綠鬒巍丹幘，青霞絡羽衣。","晨趨陽德館，夜造月華扉。","摶弄周天火，韜潛起陸機。","玉房留不住，却向九霄飛。","（同前。","）。"]', '["綠鬒巍丹幘，青霞絡羽衣。","晨趨陽德館，夜造月华扉。","摶弄周天火，韜潛起陸機。","玉房留不住，却向九霄飞。","（同前。","）。"]', '诗', 'shi', '', NULL, '步虛詞 十三 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25ec3130-fb29-4ec9-9e2e-ff3fb56afe97', '步虛詞 十四', '步虛词 十四', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["昔在延恩殿，中霄降九皇。","六真分左右，黃霧遶軒廊。","廣內尊神御，仙兵護道場。","孝孫今繼志，咫尺對靈光。","（同前。","）。"]', '["昔在延恩殿，中霄降九皇。","六真分左右，黄霧遶軒廊。","廣內尊神御，仙兵護道場。","孝孫今繼志，咫尺对靈光。","（同前。","）。"]', '诗', 'shi', '', NULL, '步虛詞 十四 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c227a24d-8aae-4697-b4e1-9b05ba847ae8', '步虛詞 十五', '步虛词 十五', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["寶籙修真範，丹誠奉上蒼。","冰淵臨兆庶，宵旰致平康。","萬物消疵癘，三晨放吉祥。","步虛聲已徹，更詠洞玄章。","（同前卷廿八。","）。"]', '["寶籙修真範，丹誠奉上蒼。","冰淵臨兆庶，宵旰致平康。","万物消疵癘，三晨放吉祥。","步虛声已徹，更詠洞玄章。","（同前卷廿八。","）。"]', '诗', 'shi', '', NULL, '步虛詞 十五 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53f86d57-7db3-4241-8903-85737dc2bd3b', '步虛詞 十六', '步虛词 十六', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["宛宛神州地，巍巍衆妙壇。","鶴袍來羽客，鳬舃下仙官。","玉斝斟元醴，琅函啓大丹。","至誠何以祝。","四海永澄瀾。","（同前。","）。"]', '["宛宛神州地，巍巍衆妙壇。","鹤袍来羽客，鳬舃下仙官。","玉斝斟元醴，琅函啓大丹。","至誠何以祝。","四海永澄瀾。","（同前。","）。"]', '诗', 'shi', '', NULL, '步虛詞 十六 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b71834bb-f367-4159-9ee1-63e8ce67ea2e', '步虛詞 十七', '步虛词 十七', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["水噀魔宮懾，燈開夜府明。","九天風靜默，四極氣澄清。","嘯詠朱陵府，翶翔白玉京。","至誠何以祝，國祚永安榮。","（同前。","）。"]', '["水噀魔宮懾，灯开夜府明。","九天风静默，四極氣澄清。","嘯詠朱陵府，翶翔白玉京。","至誠何以祝，国祚永安榮。","（同前。","）。"]', '诗', 'shi', '', NULL, '步虛詞 十七 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('362e5f67-e021-4424-8af2-a6b89a9b5aa3', '步虛詞 十八', '步虛词 十八', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["始青黎元蓋，金香結珠煙。","飛晨總翹轡，稽首玉帝前。","帝心浩以舒，錫吾《太靈篇》。","是謂不滅道，萬天秉吾權。","吾行空洞中，下仙昩其淵。","（同前卷三十。","）。"]', '["始青黎元蓋，金香結珠煙。","飞晨總翹轡，稽首玉帝前。","帝心浩以舒，錫吾《太靈篇》。","是謂不滅道，万天秉吾權。","吾行空洞中，下仙昩其淵。","（同前卷三十。","）。"]', '诗', 'shi', '', NULL, '步虛詞 十八 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9488b371-720c-4424-bdf4-9381b8ae7e45', '步虛詞 十九', '步虛词 十九', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["一炁化之元，邈在兩儀先。","寶埒馳金馬，真香噴玉蓮。","飛空按龍轡，梵響導芝軿。","綿永長春刼，翶翔無色天。","初真難曉諭，以此戒中仙。","（同前。","）。"]', '["一炁化之元，邈在兩儀先。","寶埒驰金马，真香噴玉蓮。","飞空按龙轡，梵响導芝軿。","綿永长春刼，翶翔無色天。","初真难晓諭，以此戒中仙。","（同前。","）。"]', '诗', 'shi', '', NULL, '步虛詞 十九 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4d70546-e5f5-4890-be6b-832592bb9ec6', '步虛詞 二十', '步虛词 二十', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["高真明道德，垂世五千言。","解釋慚涼薄，殫誠測妙元。","霓旌嚴教典，羽唱徹雲軿。","瑞鶴儀空際，祥風拂暑煩。","穹窿玆響應，寶祚億斯年。","（同前。","）。"]', '["高真明道德，垂世五千言。","解釋慚涼薄，殫誠測妙元。","霓旌嚴教典，羽唱徹云軿。","瑞鹤儀空際，祥风拂暑煩。","穹窿玆响應，寶祚億斯年。","（同前。","）。"]', '诗', 'shi', '', NULL, '步虛詞 二十 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('405d8ea9-dab8-43c5-941d-b9cf09014658', '步虛詞 二十一', '步虛词 二十一', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["華夏吟哦遠，人聲自抑揚。","沖虛歸道德，曲折合宮商。","殿閣沉檀散，樓臺月露涼。","至誠何以祝，多稼永豐穰。","（同前卷四十。","）。"]', '["华夏吟哦远，人声自抑揚。","沖虛归道德，曲折合宮商。","殿閣沉檀散，楼台月露涼。","至誠何以祝，多稼永豐穰。","（同前卷四十。","）。"]', '诗', 'shi', '', NULL, '步虛詞 二十一 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f03cb0e-c63b-4f43-9614-60392600e5f9', '步虛詞 二十二', '步虛词 二十二', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["天真帝一宮，藹藹冠耀靈。","流渙法輪網，旋空入無形。","虛皇撫雲璈，衆真誦洞經。","高仙凜手讚，彌刼保利貞。","（同前卷二四。","同書卷九作《三啓頌》。","）。"]', '["天真帝一宮，藹藹冠耀靈。","流渙法輪網，旋空入無形。","虛皇撫云璈，衆真誦洞經。","高仙凜手讚，彌刼保利貞。","（同前卷二四。","同书卷九作《三啓頌》。","）。"]', '诗', 'shi', '', NULL, '步虛詞 二十二 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e013544-ad26-41b1-a0a7-ccff11d7f0c1', '三塗五苦頌八首 一', '三塗五苦頌八首 一', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["三才及萬物，倚伏各有靈。","終結大刼數，福盡天地傾。","往返於五道，苦哉更死生。","展轉三塗中，去來與禍幷。"]', '["三才及万物，倚伏各有靈。","終結大刼數，福尽天地傾。","往返於五道，苦哉更死生。","展轉三塗中，去来與禍幷。"]', '诗', 'shi', '', NULL, '三塗五苦頌八首 一 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30cbb83d-6e88-41d9-9376-87ec7690c3ba', '三塗五苦頌八首 二', '三塗五苦頌八首 二', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["大賢慎玆戒，忍世念割情。","愚夫不信法，罪通常自嬰。","吾念世無已，今故重告明。","若欲度斯禍，歸命太上經。"]', '["大賢慎玆戒，忍世念割情。","愚夫不信法，罪通常自嬰。","吾念世無已，今故重告明。","若欲度斯禍，归命太上經。"]', '诗', 'shi', '', NULL, '三塗五苦頌八首 二 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bc78684-1712-4b47-a4b3-afb37c3ac000', '三塗五苦頌八首 三', '三塗五苦頌八首 三', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["罪福不由他，諒自發爾身。","大賢故閉口，欲滅諸根。","滅念歸兼忘，倚伏待長泯。","弘道以安世，終當見正真。"]', '["罪福不由他，諒自發爾身。","大賢故閉口，欲滅諸根。","滅念归兼忘，倚伏待长泯。","弘道以安世，終當见正真。"]', '诗', 'shi', '', NULL, '三塗五苦頌八首 三 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df1bfc12-c110-4248-b1d3-a97be3f89353', '三塗五苦頌八首 四', '三塗五苦頌八首 四', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["淫嫉爲禍首，滅身之至患。","食養如斯禍，恐必致天殘。","知惡而不革，豈是道所安。","懷毒日齋直。","令我發長歎。"]', '["淫嫉爲禍首，滅身之至患。","食養如斯禍，恐必致天殘。","知惡而不革，豈是道所安。","懷毒日斋直。","令我發长歎。"]', '诗', 'shi', '', NULL, '三塗五苦頌八首 四 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c19f3ec1-226a-4e0f-b122-f8c3da26fa87', '三塗五苦頌八首 五', '三塗五苦頌八首 五', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["宿命有信然，弱喪謂之無。","皆欲眼前見，過目即言悠。","大賢明道教，慘慽憫頑夫。","依依念子苦，勤勤令我憂。"]', '["宿命有信然，弱喪謂之無。","皆欲眼前见，過目即言悠。","大賢明道教，慘慽憫頑夫。","依依念子苦，勤勤令我憂。"]', '诗', 'shi', '', NULL, '三塗五苦頌八首 五 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11f21285-cef9-4b1c-a564-66cccbc89e1a', '三塗五苦頌八首 六', '三塗五苦頌八首 六', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["人命已銷盡，亦猶膏中火。","四大暫相寓，五物權時假。","盛年當勤學，趣求存無我。","福盡身福散，冥冥地獄下。","上聖畏是故，尋道度斯禍。"]', '["人命已銷尽，亦猶膏中火。","四大暫相寓，五物權时假。","盛年當勤学，趣求存無我。","福尽身福散，冥冥地獄下。","上聖畏是故，尋道度斯禍。"]', '诗', 'shi', '', NULL, '三塗五苦頌八首 六 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('419c15f9-3d1a-4223-aa81-3906903714d2', '三塗五苦頌八首 七', '三塗五苦頌八首 七', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["學仙行爲急，奉戒制情心。","虛夷正氣居，仙聖自相尋。"]', '["学仙行爲急，奉戒制情心。","虛夷正氣居，仙聖自相尋。"]', '诗', 'shi', '', NULL, '三塗五苦頌八首 七 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8e525ec-af1c-49ed-b669-bc5dc3ccedf7', '三塗五苦頌八首 八', '三塗五苦頌八首 八', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["大賢樂經戒，受之爲身寶。","就學早苦晚，治身恨不早。","比當被幽賾，倏忽年已老。","執卷吟爾極，將更死通惱。","吾故及弱齡，棄世以學道。","（同前卷五十。","）。"]', '["大賢乐經戒，受之爲身寶。","就学早苦晚，治身恨不早。","比當被幽賾，倏忽年已老。","執卷吟爾極，將更死通惱。","吾故及弱齡，棄世以学道。","（同前卷五十。","）。"]', '诗', 'shi', '', NULL, '三塗五苦頌八首 八 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ecc2ed4-c6ba-4b1f-a647-636e90a0bc76', '解壇頌', '解壇頌', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["太空包有象，至道杳無形。","承和通妙氣，應感達中情。","倏忽周八極，依稀降萬靈。","微香陳素欵，委質表丹誠。","遠泛翔鸞蓋，遐攀綺鳳旌。","煙宮高鬱鬱，雲閣上亭亭。","瓊駕出霄漢，金龍入太清。","甘露洽人世，家國悉安寧。"]', '["太空包有象，至道杳無形。","承和通妙氣，應感達中情。","倏忽周八極，依稀降万靈。","微香陳素欵，委質表丹誠。","远泛翔鸾蓋，遐攀綺鳳旌。","煙宮高鬱鬱，云閣上亭亭。","瓊駕出霄漢，金龙入太清。","甘露洽人世，家国悉安寧。"]', '诗', 'shi', '', NULL, '解壇頌 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('310d23e5-96e4-4f55-8c43-d0cbfaf04d1e', '辭三師頌 一', '辞三師頌 一', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["經法隨玄妙，崇奉悉因師。","凡欲立善者，咸當禮願之。","氣專功易就，心慢侮難追。","若能勤繫念，朝日自仙飛。"]', '["經法隨玄妙，崇奉悉因師。","凡欲立善者，咸當禮願之。","氣專功易就，心慢侮难追。","若能勤繫念，朝日自仙飞。"]', '诗', 'shi', '', NULL, '辭三師頌 一 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ceff4276-454f-4357-b044-838bb6eb4419', '辭三師頌 二', '辞三師頌 二', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["道以齋爲重，法以朝爲常，不奉不信者，焉能遊帝出。","有骨入仙品，自然開紫房。","玄女登雲臺，但見金銀堂。","是故謝三師，稽首禮虛皇。"]', '["道以斋爲重，法以朝爲常，不奉不信者，焉能游帝出。","有骨入仙品，自然开紫房。","玄女登云台，但见金銀堂。","是故謝三師，稽首禮虛皇。"]', '诗', 'shi', '', NULL, '辭三師頌 二 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d554f125-2dcf-4eb0-a949-7baea2a12b15', '辭三師頌 三', '辞三師頌 三', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["岧岧玉京山，玄者何巍巍。","真人科虛步，朗朗長夜開。","大道由人弘，心至神自歸。","修齋行道畢，稽首辭三師。","（同前。","）。"]', '["岧岧玉京山，玄者何巍巍。","真人科虛步，朗朗长夜开。","大道由人弘，心至神自归。","修斋行道畢，稽首辞三師。","（同前。","）。"]', '诗', 'shi', '', NULL, '辭三師頌 三 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21294771-8958-4f25-9f8e-a0b0a33daa01', '七真讚 一', '七真讚 一', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["太上玄虛宗，弘道尊其經。","俯仰已得仙，歷刼無數齡。","巍巍太真德，寂寂因無生。","霄景結空構，乘虛自然征。","日月爲炳灼，安和樂未央。"]', '["太上玄虛宗，弘道尊其經。","俯仰已得仙，歷刼無數齡。","巍巍太真德，寂寂因無生。","霄景結空構，乘虛自然征。","日月爲炳灼，安和乐未央。"]', '诗', 'shi', '', NULL, '七真讚 一 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('800d9e22-9aee-4c7b-81d3-c8669a2b5ef1', '七真讚 二', '七真讚 二', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["學仙絕華念，念念相因積。","去來亂我神，神躁靡不歷。","滅念停虛閑，蕭蕭入空寂。","請經若饑渴，持志如金石。","保子飛玄路，五靈度符籍。"]', '["学仙絕华念，念念相因積。","去来亂我神，神躁靡不歷。","滅念停虛闲，蕭蕭入空寂。","請經若饑渴，持志如金石。","保子飞玄路，五靈度符籍。"]', '诗', 'shi', '', NULL, '七真讚 二 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f90a6cd-a6d9-4fc6-a6d3-640f994bd6cd', '七真讚 三', '七真讚 三', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["濟我六度行，故能解三羅。","清齋禮太素，吐納養雲牙。","逍遙金闕內，玉京爲余家。","自然生七寶，人人坐蓮花。","仰嚼玄都柰，俯酣空洞瓜。","容顏曜十日，奚計年刼多。","法鼓會天仙，鳴鐘徴大魔。"]', '["濟我六度行，故能解三羅。","清斋禮太素，吐納養云牙。","逍遙金闕內，玉京爲余家。","自然生七寶，人人坐蓮花。","仰嚼玄都柰，俯酣空洞瓜。","容顏曜十日，奚計年刼多。","法鼓會天仙，鳴鐘徴大魔。"]', '诗', 'shi', '', NULL, '七真讚 三 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71cc75fb-901a-443c-a5df-e29ce11215e4', '七真讚 四', '七真讚 四', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["靈風扇香華，璨爛開繁衿。","太真撫雲璈，衆仙彈靈琴。","雅歌三天景，散慧玉華林。","七祖升福堂，由此步玄音。","前世福未足，斯書邈難尋。","信道情不盡，圖飛乃反沈。","太上無爲道，弘之在兆心。"]', '["靈风扇香华，璨爛开繁衿。","太真撫云璈，衆仙彈靈琴。","雅歌三天景，散慧玉华林。","七祖升福堂，由此步玄音。","前世福未足，斯书邈难尋。","信道情不尽，圖飞乃反沈。","太上無爲道，弘之在兆心。"]', '诗', 'shi', '', NULL, '七真讚 四 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6197c977-a41c-4a43-811e-1204721230bb', '七真讚 五', '七真讚 五', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["學總之由丹信，奉師如至親。","挹景偶清虛，孜孜隨日新。","衆人未得度，終不度我身。","大願有重報，玄德必信然。","陰惡罪至深，對來若轉輪。"]', '["学總之由丹信，奉師如至親。","挹景偶清虛，孜孜隨日新。","衆人未得度，終不度我身。","大願有重報，玄德必信然。","陰惡罪至深，对来若轉輪。"]', '诗', 'shi', '', NULL, '七真讚 五 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c634076-ecdb-4bd4-badf-47a9104b9c36', '七真讚 六', '七真讚 六', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["學道甚亦苦，晨夜建福田。","種德猶植樹，積簣而成山。","子能耽玄尚，飄爾升青天，修是無爲道，當與善結緣。","太上至隱書，名曰智慧篇。","拔苦其大才，超俗以德真。","靈姿世所奇，曄若淵中蓮。"]', '["学道甚亦苦，晨夜建福田。","種德猶植樹，積簣而成山。","子能耽玄尚，飄爾升青天，修是無爲道，當與善結緣。","太上至隐书，名曰智慧篇。","拔苦其大才，超俗以德真。","靈姿世所奇，曄若淵中蓮。"]', '诗', 'shi', '', NULL, '七真讚 六 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38883685-f28c-4993-a248-f7d195dfd00e', '七真讚 七', '七真讚 七', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["人行各有本，皆由宿世功。","立德務及時，發願莫不從。","善惡俱待對，倚伏理難窮。","賢士奉法言，道亦在兼忘。","解是大智慧，上爲太極公。","寶怪罪連玉輿，命駕御九龍。","金華擎洞經，捧香悉仙童。","嘯歌徹玄都，鳴玉叩瓊鐘。"]', '["人行各有本，皆由宿世功。","立德務及时，發願莫不從。","善惡俱待对，倚伏理难窮。","賢士奉法言，道亦在兼忘。","解是大智慧，上爲太極公。","寶怪罪連玉輿，命駕御九龙。","金华擎洞經，捧香悉仙童。","嘯歌徹玄都，鳴玉叩瓊鐘。"]', '诗', 'shi', '', NULL, '七真讚 七 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a7cb416-153b-4049-b240-46c066cce523', '七真讚 八', '七真讚 八', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["竦身淩太清，超景逸紫霄。","保無持法網，遊玄極逍遙。","萬刼猶昨夜，千春如晨朝。","巍峩蔭雲華，手攀寶林條。","香烟自然生，玄階與扶搖。","靈幡順風散，繁想凝滯時消。","滅智弘大混，無爲爲清謠。","（同前卷五二。","）。"]', '["竦身淩太清，超景逸紫霄。","保無持法網，游玄極逍遙。","万刼猶昨夜，千春如晨朝。","巍峩蔭云华，手攀寶林條。","香烟自然生，玄階與扶搖。","靈幡順风散，繁想凝滯时消。","滅智弘大混，無爲爲清謠。","（同前卷五二。","）。"]', '诗', 'shi', '', NULL, '七真讚 八 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e92b1aca-1579-44a0-aedf-c8485981b991', '小學仙讚', '小学仙讚', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["學仙行爲急，奉戒制情心。","虛夷正炁居，仙聖自相尋。","若不信法言，胡爲棲山林。","（同前。","）。"]', '["学仙行爲急，奉戒制情心。","虛夷正炁居，仙聖自相尋。","若不信法言，胡爲棲山林。","（同前。","）。"]', '诗', 'shi', '', NULL, '小學仙讚 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2479f301-346c-4c5c-a570-97476275c785', '明燈頌', '明灯頌', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["太上散十方，華燈通精誠。","諸天悉輝耀，諸地皆朗明。","我身亦光徹，五藏生華榮。","炎景照太無，遐想被玉京。","（同前卷五六。","）。"]', '["太上散十方，华灯通精誠。","諸天悉輝耀，諸地皆朗明。","我身亦光徹，五藏生华榮。","炎景照太無，遐想被玉京。","（同前卷五六。","）。"]', '诗', 'shi', '', NULL, '明燈頌 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e2b8323-7d02-4411-92e9-5ff0ed56d492', '啓堂頌', '啓堂頌', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["勤行奉齋戒，誦經制六情。","故得乘空飛，耀景上玉清。","精心奉經教，吐納練五神。","功德冠諸人，轉輪上成仙。","（同前卷一。","）。"]', '["勤行奉斋戒，誦經制六情。","故得乘空飞，耀景上玉清。","精心奉經教，吐納練五神。","功德冠諸人，轉輪上成仙。","（同前卷一。","）。"]', '诗', 'shi', '', NULL, '啓堂頌 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82775129-4828-469f-9ad9-b5d06e826679', '出堂頌', '出堂頌', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["夙世恩德報，道心起然發。","身飛昇仙都，七祖咸解脫。","（同前。","）。"]', '["夙世恩德報，道心起然發。","身飞昇仙都，七祖咸解脫。","（同前。","）。"]', '诗', 'shi', '', NULL, '出堂頌 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2382a83f-9c5c-478a-9aa0-b6189a5e92fc', '投龍頌', '投龙頌', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["祈真登紫府，告命詣靈壇。","玉女謠梵響，金童奏香煙。","書名通九地，列字上三天，永享無期壽，剋成高上仙。","（同前卷四九。","）。"]', '["祈真登紫府，告命詣靈壇。","玉女謠梵响，金童奏香煙。","书名通九地，列字上三天，永享無期壽，剋成高上仙。","（同前卷四九。","）。"]', '诗', 'shi', '', NULL, '投龍頌 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e580a748-1b2e-4e13-9ad3-437830f06b61', '送神頌', '送神頌', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["渺渺空無象，悠悠感有情。","敬則承天貺，泄則被魔精。","吉凶隨運起，否泰應緣生。","道貴珠玉，神惟在至誠。","丹碧盡勤苦，懇欵竭中情。","自然通大聖，皆得降明靈。","捻香陳所願，稽首冀嘉禎。","天尊常寂靜，迴心禮杳冥。","（同前卷五十。","）。"]', '["渺渺空無象，悠悠感有情。","敬則承天貺，泄則被魔精。","吉凶隨運起，否泰應緣生。","道貴珠玉，神惟在至誠。","丹碧尽勤苦，懇欵竭中情。","自然通大聖，皆得降明靈。","捻香陳所願，稽首冀嘉禎。","天尊常寂静，迴心禮杳冥。","（同前卷五十。","）。"]', '诗', 'shi', '', NULL, '送神頌 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddb9dd2a-1b75-4fa2-a616-76cd8f2908f2', '還戒頌', '還戒頌', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["天尊大慈悲，說戒度衆生。","威德被幽顯，果報感神靈。","諸天來稽首，羣魔自西形。","過去超八難，見在保千齡。","齋福行當息，相共送虔誠。","流梵逸雲唱，飛香雜煙聲。","瓊鳳乘丹輦，金龍駕綠軿。","生死皆快樂，家國悉安寧。","（同前。","）。"]', '["天尊大慈悲，说戒度衆生。","威德被幽显，果報感神靈。","諸天来稽首，羣魔自西形。","過去超八难，见在保千齡。","斋福行當息，相共送虔誠。","流梵逸云唱，飞香杂煙声。","瓊鳳乘丹輦，金龙駕綠軿。","生死皆快乐，家国悉安寧。","（同前。","）。"]', '诗', 'shi', '', NULL, '還戒頌 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af55cd0e-3e78-4692-ad50-9d8177b1afe6', '三啓頌 一', '三啓頌 一', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["樂法以爲妻，愛經如珠玉。","持戒制六情。","念道遣所欲。","淡泊正氣停，蕭然神靜默。","天魔並敬護，世世享大福。","（同上一卷。","）。"]', '["乐法以爲妻，愛經如珠玉。","持戒制六情。","念道遣所欲。","淡泊正氣停，蕭然神静默。","天魔並敬護，世世享大福。","（同上一卷。","）。"]', '诗', 'shi', '', NULL, '三啓頌 一 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e2ca087-1cdc-47fc-ac28-cbb271e9f2f5', '三啓頌 二', '三啓頌 二', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["鬱鬱家國盛，濟濟經道興。","天人同其願，縹緲入大乘。","因心立福田，靡靡法輪昇。","七祖生天堂，我身白日騰。","（同前卷十一。","）。"]', '["鬱鬱家国盛，濟濟經道兴。","天人同其願，縹緲入大乘。","因心立福田，靡靡法輪昇。","七祖生天堂，我身白日腾。","（同前卷十一。","）。"]', '诗', 'shi', '', NULL, '三啓頌 二 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95888852-bb8e-4d57-815c-df6a5099a54a', '三啓頌 三', '三啓頌 三', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["大道洞玄虛，有念無不契。","鍊質入仙真，遂成金剛體。","超度三界難，地獄五苦解。","悉歸太上經，靜念稽首禮。","（同前卷十二。","）。"]', '["大道洞玄虛，有念無不契。","鍊質入仙真，遂成金剛體。","超度三界难，地獄五苦解。","悉归太上經，静念稽首禮。","（同前卷十二。","）。"]', '诗', 'shi', '', NULL, '三啓頌 三 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2695105-55e6-469d-9d75-bf7cc0e9b9a5', '楚詞頌', '楚词頌', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["衆生多障難，大道甚矜憐。","救度留科戒，咸令懺罪緣。","愆辜編地府，釁結已聞天。","發露祈真祐，精誠仰聖賢。","虔恭禮三寶，願當奏延年。","焚詞歸上界，奏名玉帝前。","（同前卷四九。","）。"]', '["衆生多障难，大道甚矜怜。","救度留科戒，咸令懺罪緣。","愆辜編地府，釁結已闻天。","發露祈真祐，精誠仰聖賢。","虔恭禮三寶，願當奏延年。","焚词归上界，奏名玉帝前。","（同前卷四九。","）。"]', '诗', 'shi', '', NULL, '楚詞頌 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d454e4e7-956c-491c-a67e-c350c1d2d823', '六十甲子歌（題擬） 一', '六十甲子歌（題擬） 一', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["甲子秋，耕民懷苦憂。","禾苗不成實，災厄害田疇。","但看入秋後，高田不可守。","辛苦臨冬春，父子離鄉走。","兄弟成路人，妻子爆糊口。","萬姓悉災迍，民隨千里走。","。"]', '["甲子秋，耕民懷苦憂。","禾苗不成實，災厄害田疇。","但看入秋後，高田不可守。","辛苦臨冬春，父子離乡走。","兄弟成路人，妻子爆糊口。","万姓悉災迍，民隨千里走。","。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 一 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1456ba4c-a26b-4531-8c6e-6da069105124', '六十甲子歌（題擬） 二', '六十甲子歌（題擬） 二', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["乙丑春，瘟災害萬民。","夏首災疫起，偏傷楚魯人。","家類悉糊口，吳地又分張。","民奔千里外，六畜悉逢殃。","高田但種植，低處傷苗秀。","災疫如去年，不得歸家守。"]', '["乙丑春，瘟災害万民。","夏首災疫起，偏傷楚魯人。","家類悉糊口，吳地又分張。","民奔千里外，六畜悉逢殃。","高田但種植，低处傷苗秀。","災疫如去年，不得归家守。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 二 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('933877d3-58a3-4837-8fae-18aaf517a904', '六十甲子歌（題擬） 三', '六十甲子歌（題擬） 三', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["丙寅首，猛獸成羣走。","四海悉揚波，源野連山阜。","高田宜種植，領畔幷山阜。","但看四五月，衆魚庭前走。"]', '["丙寅首，猛獸成羣走。","四海悉揚波，源野連山阜。","高田宜種植，領畔幷山阜。","但看四五月，衆鱼庭前走。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 三 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05de9f75-814f-4b3e-9fb6-a7bfaa23839f', '六十甲子歌（題擬） 四', '六十甲子歌（題擬） 四', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["丁卯中，未可逐時風。","春初無猛雨，秋中有大深。","低田災彌起，山際好施功。","歲中雖薄熱，倉儲不免空。"]', '["丁卯中，未可逐时风。","春初無猛雨，秋中有大深。","低田災彌起，山際好施功。","歲中雖薄熱，倉儲不免空。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 四 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5832e192-39dd-4257-9960-0ba7ec7ef940', '六十甲子歌（題擬） 五', '六十甲子歌（題擬） 五', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["戊辰裏，蟲蝗皆競起。","人民遭災疫，婦女悲生死。","災害是秋中，稻出山腰裏。","低處定難收，必是遭洪水。"]', '["戊辰裏，蟲蝗皆競起。","人民遭災疫，婦女悲生死。","災害是秋中，稻出山腰裏。","低处定难收，必是遭洪水。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 五 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9410796e-bf77-4476-a441-8a5ddf839854', '六十甲子歌（題擬） 六', '六十甲子歌（題擬） 六', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["己巳初，階前觀戲魚。","湖裏蛟龍出，乘舟在陸衢。","平路遭淹浸，禾稻澇皆無。","欲求乾淨處，須早竪樓居。"]', '["己巳初，階前观戲鱼。","湖裏蛟龙出，乘舟在陸衢。","平路遭淹浸，禾稻澇皆無。","欲求乾淨处，須早竪楼居。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 六 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f72354f-7095-4ef1-95a6-8e6ba3ae0eab', '六十甲子歌（題擬） 七', '六十甲子歌（題擬） 七', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["庚午首，水旱俱應有。","船行陸路中，牽馬湖中走。","夏旱憂百日，秋遭三六九。","禾定出高田，秋收早冬首。","晚刈必逢災，兵革起非久。"]', '["庚午首，水旱俱應有。","船行陸路中，牽马湖中走。","夏旱憂百日，秋遭三六九。","禾定出高田，秋收早冬首。","晚刈必逢災，兵革起非久。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 七 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78273dda-8b6b-4e58-8d96-9430f0ce31c5', '六十甲子歌（題擬） 八', '六十甲子歌（題擬） 八', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["辛未年，種植近山邊。","初春有大水，夏中必旱然。","吳地應無事，荆楚被災纏。","夏首雖微旱，秋泉遍滿源。","不免魚災起，家家被率牽。"]', '["辛未年，種植近山邊。","初春有大水，夏中必旱然。","吳地應無事，荆楚被災纏。","夏首雖微旱，秋泉遍满源。","不免鱼災起，家家被率牽。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 八 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dcbde41-7b6b-406c-828c-8134b1496040', '六十甲子歌（題擬） 九', '六十甲子歌（題擬） 九', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["壬申候，高田難保守。","乘車行瀆中，不見吳興部。","倉儲多偏促，家家無升斗。","北地遭連厄，九離皆並受。","兼疫發登萊，平復吳江口。","。"]', '["壬申候，高田难保守。","乘车行瀆中，不见吳兴部。","倉儲多偏促，家家無升斗。","北地遭連厄，九離皆並受。","兼疫發登萊，平复吳江口。","。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 九 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64fbca6a-7abe-4d0b-8597-203e37c6a230', '六十甲子歌（題擬） 十', '六十甲子歌（題擬） 十', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["癸酉年，高低不可憐。","春初先作旱，夏首水連連，末秋風火急，禾稻不豐鮮。","但看齊魯地，此處是荒年。"]', '["癸酉年，高低不可怜。","春初先作旱，夏首水連連，末秋风火急，禾稻不豐鲜。","但看齊魯地，此处是荒年。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 十 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8f56343-7fb4-4b20-b3ec-cbc347aaa204', '六十甲子歌（題擬） 十一', '六十甲子歌（題擬） 十一', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["甲戌中，春首被災蟲。","夏景逢災旱，秋冬又被洪。","高田虛種植，必定見蒿蓬。","欲知災厄地，燕魏及山東。"]', '["甲戌中，春首被災蟲。","夏景逢災旱，秋冬又被洪。","高田虛種植，必定见蒿蓬。","欲知災厄地，燕魏及山东。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 十一 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c5cfca9-2d57-4879-ad4f-38afcd53bead', '六十甲子歌（題擬） 十二', '六十甲子歌（題擬） 十二', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["乙亥初，水旱遍通渠。","災厄由此起，大鬼鎮城居。","遠應定九五，得失未年初。","種得禾苗處，高低然可居。"]', '["乙亥初，水旱遍通渠。","災厄由此起，大鬼鎮城居。","远應定九五，得失未年初。","種得禾苗处，高低然可居。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 十二 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97bba356-72cc-4640-82db-99a95342d824', '六十甲子歌（題擬） 十三', '六十甲子歌（題擬） 十三', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["丙子過，種田出江河。","作植民憂苦，種苗被害多。","災鼠成羣隊，十兒同一窠。","虔詣神祇佑，保護上期禾。"]', '["丙子過，種田出江河。","作植民憂苦，種苗被害多。","災鼠成羣隊，十兒同一窠。","虔詣神祇佑，保護上期禾。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 十三 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50627f7a-96eb-4952-ab75-67eeb09079c9', '六十甲子歌（題擬） 十四', '六十甲子歌（題擬） 十四', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["丁丑改，田夫難自在。","春初雖種植，秋首成河海。","牛馬被災傷，京兆最驚忙。","欲知苗秀處，稻出去年場。"]', '["丁丑改，田夫难自在。","春初雖種植，秋首成河海。","牛马被災傷，京兆最驚忙。","欲知苗秀处，稻出去年場。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 十四 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbd356cb-ec05-4a5d-9714-285be05eabcc', '六十甲子歌（題擬） 十五', '六十甲子歌（題擬） 十五', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["戊寅年，山頭好作田。","陸路成江澗，飢民死道邊。","魚鼈同兔走，高岸稱栽蓮。","但看孟夏末，庭前好闘船。"]', '["戊寅年，山头好作田。","陸路成江澗，飢民死道邊。","鱼鼈同兔走，高岸稱栽蓮。","但看孟夏末，庭前好闘船。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 十五 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a00490cc-548c-465b-a743-f1498db7c10f', '六十甲子歌（題擬） 十六', '六十甲子歌（題擬） 十六', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["己卯到，高處田苗好。","春初雖乏水，秋夏連江浩。","楚魯受其災，吳會蒙恩造。","其年皆豐稔，種作偏宜早。"]', '["己卯到，高处田苗好。","春初雖乏水，秋夏連江浩。","楚魯受其災，吳會蒙恩造。","其年皆豐稔，種作偏宜早。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 十六 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7ab2b4c-6026-4b1b-bedb-b006bb367943', '六十甲子歌（題擬） 十七', '六十甲子歌（題擬） 十七', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["庚辰至，燕魏人災起。","畜類亦如然，田苗被蟲死。","山際好施功，吳地耕民喜。","低處遭淹沒，中高甚豐美。","。"]', '["庚辰至，燕魏人災起。","畜類亦如然，田苗被蟲死。","山際好施功，吳地耕民喜。","低处遭淹沒，中高甚豐美。","。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 十七 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c2c8e4d-9a17-4018-9866-a5afc742a200', '六十甲子歌（題擬） 十八', '六十甲子歌（題擬） 十八', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["辛巳簉，頳尾戲庭溜。","魚行衢巷間，稻苗秀山阜。","種植但向前，施功莫在後。","低處有災殃，中高甚豐厚。"]', '["辛巳簉，頳尾戲庭溜。","鱼行衢巷间，稻苗秀山阜。","種植但向前，施功莫在後。","低处有災殃，中高甚豐厚。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 十八 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c50b2c2-8b4c-46a3-accd-0779ffbaa6a3', '六十甲子歌（題擬） 十九', '六十甲子歌（題擬） 十九', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["壬午春，水旱不調均。","旱處憂千里，低處戲遊鱗。","且但只飢荒，亦懼鉷災頻。","疫瘴連年起，飢餓亦多迍。"]', '["壬午春，水旱不調均。","旱处憂千里，低处戲游鱗。","且但只飢荒，亦懼鉷災頻。","疫瘴連年起，飢餓亦多迍。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 十九 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b6098ed-f6b8-4a2d-ad51-1fff007f71d1', '六十甲子歌（題擬） 二十', '六十甲子歌（題擬） 二十', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["癸未中，一井五家同，春夏逢玆瘴，秋來又被洪。","但看吳楚地，幷及山東。","向西荒災起，田父但施工。"]', '["癸未中，一井五家同，春夏逢玆瘴，秋来又被洪。","但看吳楚地，幷及山东。","向西荒災起，田父但施工。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 二十 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04d09155-3fa6-4f4b-bae7-fcb68752809f', '六十甲子歌（題擬） 二十一', '六十甲子歌（題擬） 二十一', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["甲申湊，憂懼應非久。","車行湖瀆中，驟馬三河口。","移居定不回，此是災中咎。","稻出五湖邊，不用耕山阜。"]', '["甲申湊，憂懼應非久。","车行湖瀆中，驟马三河口。","移居定不回，此是災中咎。","稻出五湖邊，不用耕山阜。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 二十一 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eea0e36d-0112-4d99-972f-a5e1b22063b4', '六十甲子歌（題擬） 二十二', '六十甲子歌（題擬） 二十二', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["乙酉遷，春旱必應然。","三家同一井，災從吳會連。","種作生涯處，皆慕五湖邊。","不用耕山阜，高處是荒田。"]', '["乙酉遷，春旱必應然。","三家同一井，災從吳會連。","種作生涯处，皆慕五湖邊。","不用耕山阜，高处是荒田。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 二十二 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35015af2-6eef-491e-b93b-b89625270ff8', '六十甲子歌（題擬） 二十三', '六十甲子歌（題擬） 二十三', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["丙戌年，秋來枯井泉。","夏首雖然水，向後地焦然。","此歲雲龍起，稻出五湖邊。","中高徒種植，必定被災纏。"]', '["丙戌年，秋来枯井泉。","夏首雖然水，向後地焦然。","此歲云龙起，稻出五湖邊。","中高徒種植，必定被災纏。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 二十三 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a29e570-7359-4e64-9705-a3a58c4277c4', '六十甲子歌（題擬） 二十四', '六十甲子歌（題擬） 二十四', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["丁亥餘，吳分好安居。","高低通見熟，荒歉在洪廬。","泗城皆厄難，燕楚最荒虛。","歲中雖薄稔，災水在春初。"]', '["丁亥餘，吳分好安居。","高低通见熟，荒歉在洪廬。","泗城皆厄难，燕楚最荒虛。","歲中雖薄稔，災水在春初。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 二十四 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b483d119-6742-4d82-afdd-5c123d1b26c4', '六十甲子歌（題擬） 二十五', '六十甲子歌（題擬） 二十五', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["戊子過，田叢好耕坡。","災蟲夏末有，秋中災害多。","水旱數相尋，蟲鼠不偏頗。","低田不須種，高處有微禾。","。"]', '["戊子過，田叢好耕坡。","災蟲夏末有，秋中災害多。","水旱數相尋，蟲鼠不偏頗。","低田不須種，高处有微禾。","。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 二十五 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0b52aaf-476c-42de-9431-9740274081d9', '六十甲子歌（題擬） 二十六', '六十甲子歌（題擬） 二十六', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["巳丑者，災殃遍天下。","瘟黃害鄭地，田夫船作馬。","六畜悉逢殃，種植中高野。","鬼行諸般病，着者難解謝。"]', '["巳丑者，災殃遍天下。","瘟黄害鄭地，田夫船作马。","六畜悉逢殃，種植中高野。","鬼行諸般病，着者难解謝。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 二十六 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56af82cf-8f52-4a32-860a-f2a1a1d30148', '六十甲子歌（題擬） 二十七', '六十甲子歌（題擬） 二十七', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["庚寅中，高地好施功。","雖復有微旱，水與去年同。","低地得微熟，中高最是豐。","野獸連羣走，高低路並通。"]', '["庚寅中，高地好施功。","雖复有微旱，水與去年同。","低地得微熟，中高最是豐。","野獸連羣走，高低路並通。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 二十七 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7296c1c7-58ac-420a-a57b-44564dcf09a5', '六十甲子歌（題擬） 二十八', '六十甲子歌（題擬） 二十八', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["辛卯禾，早種不須多。","秋洪作禍故，山際水成波。","早種又復旱，晚植那應好。","但看秋景後，魚戲於人道。"]', '["辛卯禾，早種不須多。","秋洪作禍故，山際水成波。","早種又复旱，晚植那應好。","但看秋景後，鱼戲於人道。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 二十八 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbffb9e0-972c-49cf-864c-1a23e18179fb', '六十甲子歌（題擬） 二十九', '六十甲子歌（題擬） 二十九', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["壬辰祀，禾被蟲災死。","幷及害萬民，六畜亦如是。","低禾不用耕，種植山腰裏。","早作劣堪收，晚種難準擬。"]', '["壬辰祀，禾被蟲災死。","幷及害万民，六畜亦如是。","低禾不用耕，種植山腰裏。","早作劣堪收，晚種难準擬。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 二十九 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2746f40c-b57a-4430-90a5-6a84f21f6442', '六十甲子歌（題擬） 三十', '六十甲子歌（題擬） 三十', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["癸巳紀，高低無準擬。","中田又被殃，粟麥歸山裏。","此嵗有災傷，低處多逢水。","舊有書喫除，新又多無備。"]', '["癸巳紀，高低無準擬。","中田又被殃，粟麦归山裏。","此嵗有災傷，低处多逢水。","旧有书喫除，新又多無備。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 三十 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('776aa906-85cc-406e-9d34-008ff5a8d32d', '六十甲子歌（題擬） 三十一', '六十甲子歌（題擬） 三十一', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["甲午初，水旱定難除。","車馬行湖底，船則納山居。","低田縱耕植，冬藏定是無。","欲知成家處，山際但耕鋤。"]', '["甲午初，水旱定难除。","车马行湖底，船則納山居。","低田縱耕植，冬藏定是無。","欲知成家处，山際但耕鋤。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 三十一 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('391e57aa-0106-4b3f-8b6c-9f9de66be2f7', '六十甲子歌（題擬） 三十二', '六十甲子歌（題擬） 三十二', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["乙未首，田種三江口。","吳地養民邦，京兆多災咎。","非但是炎災，妖災爭來湊。","流浪逐風波，值死寧非久。"]', '["乙未首，田種三江口。","吳地養民邦，京兆多災咎。","非但是炎災，妖災爭来湊。","流浪逐风波，值死寧非久。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 三十二 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89d53b21-3990-4ccb-856d-951ed9ef2515', '六十甲子歌（題擬） 三十三', '六十甲子歌（題擬） 三十三', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["丙申年，高低未可遷。","五湖堪種棘，來去並皆然。","若見當災處，斗米值千錢。","欲知安樂處，江南最可憐。","。"]', '["丙申年，高低未可遷。","五湖堪種棘，来去並皆然。","若见當災处，斗米值千錢。","欲知安乐处，江南最可怜。","。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 三十三 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('930112da-c1cd-42ed-aba7-8dfa042ea735', '六十甲子歌（題擬） 三十四', '六十甲子歌（題擬） 三十四', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["丁酉側，高低徒種植。","三家共一井，湖底生荆棘。","江東並出鄉，齊魯皆逐食。","西隴濠楚憂，東南未休息。"]', '["丁酉側，高低徒種植。","三家共一井，湖底生荆棘。","江东並出乡，齊魯皆逐食。","西隴濠楚憂，东南未休息。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 三十四 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d028ef7-9fde-4bca-bd58-9edfd977e7ed', '六十甲子歌（題擬） 三十五', '六十甲子歌（題擬） 三十五', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["戊戌木，江南豐稻穀。","燕魏定飢荒，三載留空屋。","男子被兵牽，亦有歸門哭。","妻子見分張，各自相追逐。"]', '["戊戌木，江南豐稻穀。","燕魏定飢荒，三載留空屋。","男子被兵牽，亦有归门哭。","妻子见分張，各自相追逐。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 三十五 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35e96399-0e6b-4093-8a9f-cd4cc8c6bb36', '六十甲子歌（題擬） 三十六', '六十甲子歌（題擬） 三十六', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["己亥間，江南最可憐。","不必看高下，通熟滿山川。","災臨西部地，飢荒似去年。","邊隅多擾擾，後更見憂煎。"]', '["己亥间，江南最可怜。","不必看高下，通熟满山川。","災臨西部地，飢荒似去年。","邊隅多擾擾，後更见憂煎。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 三十六 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa2370d0-c8f0-48ae-ab12-93080065fa5c', '六十甲子歌（題擬） 三十七', '六十甲子歌（題擬） 三十七', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["庚子末，居家無定活。","禾苗被害多，親戚相欺奪。","糊口並無餘，妻子單眠活。","江南雖得熟，向後亦號哭。","災殃則應逢，處處唯空屋。"]', '["庚子末，居家無定活。","禾苗被害多，親戚相欺奪。","糊口並無餘，妻子單眠活。","江南雖得熟，向後亦號哭。","災殃則應逢，处处唯空屋。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 三十七 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('207ba93a-2d52-4384-9d86-8d03a892f0da', '六十甲子歌（題擬） 三十八', '六十甲子歌（題擬） 三十八', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["辛丑於，災臨定不虛。","吳越炎千里，當之是夏初。","但看入秋首，蟲蝗處處有。","飢殍死他鄉，畜類多災咎。"]', '["辛丑於，災臨定不虛。","吳越炎千里，當之是夏初。","但看入秋首，蟲蝗处处有。","飢殍死他乡，畜類多災咎。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 三十八 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('731eb133-35a1-40d4-90ed-5a1bf5529280', '六十甲子歌（題擬） 三十九', '六十甲子歌（題擬） 三十九', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["壬寅金，猛獸結羣侵。","種植依山阜，庭戶闕過尋。","稻出高田裏，逢災是魏秦。","乘船於陸地，高城浪湧溟。"]', '["壬寅金，猛獸結羣侵。","種植依山阜，庭戶闕過尋。","稻出高田裏，逢災是魏秦。","乘船於陸地，高城浪湧溟。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 三十九 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('502a47eb-e085-445f-9737-9350881d2a47', '六十甲子歌（題擬） 四十', '六十甲子歌（題擬） 四十', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["癸卯嵗，晉魏逢災害。","值旱隔三秋，向應成兩載。","田疇多乏水，高低失準擬。","人物竟喧爭，阨據中城裏。"]', '["癸卯嵗，晉魏逢災害。","值旱隔三秋，向應成兩載。","田疇多乏水，高低失準擬。","人物竟喧爭，阨據中城裏。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 四十 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c1d3ad8-cfe2-4f07-a951-87a27e73f548', '六十甲子歌（題擬） 四十一', '六十甲子歌（題擬） 四十一', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["甲辰候，災蟲處處有。","其嵗足災殃，偏苦三江口。","粟麥最爲佳，春夏耕山阜。","江南雖薄熟，不免遭兵寇。","。"]', '["甲辰候，災蟲处处有。","其嵗足災殃，偏苦三江口。","粟麦最爲佳，春夏耕山阜。","江南雖薄熟，不免遭兵寇。","。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 四十一 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('622c982e-d2e6-4cfb-8aa2-b6b14297598c', '六十甲子歌（題擬） 四十二', '六十甲子歌（題擬） 四十二', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["乙巳至，地底蛟龍起。","此嵗主館荒，乘船於陸地。","蘇湖被波濤，吳地得全刈。","禾稻出高田，向去多宜利。"]', '["乙巳至，地底蛟龙起。","此嵗主館荒，乘船於陸地。","蘇湖被波濤，吳地得全刈。","禾稻出高田，向去多宜利。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 四十二 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88dcd2ff-c52f-42a9-8044-e8aed5ce93b6', '六十甲子歌（題擬） 四十三', '六十甲子歌（題擬） 四十三', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["丙午餘，水旱無定圖。","忽來即時沒，若旱井泉枯。","水族成兔鹿，雞犬變成魚。","稻出低田內，高處不須鋤。"]', '["丙午餘，水旱無定圖。","忽来即时沒，若旱井泉枯。","水族成兔鹿，雞犬变成鱼。","稻出低田內，高处不須鋤。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 四十三 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('583edc38-f40b-4d12-8fd2-4f4622199b38', '六十甲子歌（題擬） 四十四', '六十甲子歌（題擬） 四十四', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["丁未紀，種植山腰裏。","低處不須耕，墯民遭餓死。","非但逢災水，亦乃干戈舉。","吳地是平邦，厄在燕齊楚。"]', '["丁未紀，種植山腰裏。","低处不須耕，墯民遭餓死。","非但逢災水，亦乃干戈舉。","吳地是平邦，厄在燕齊楚。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 四十四 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fef79df2-5634-43b4-9af9-f6cba5403902', '六十甲子歌（題擬） 四十五', '六十甲子歌（題擬） 四十五', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["戊申末，江南民獨活。","高低緫得收，災蟲俱自滅。","此嵗八穀豐，人畜皆歡悅。","官吏逐階遷，諸道咸通徹。"]', '["戊申末，江南民独活。","高低緫得收，災蟲俱自滅。","此嵗八穀豐，人畜皆歡悅。","官吏逐階遷，諸道咸通徹。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 四十五 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58b1d235-e95d-495e-b97a-2b27fc871522', '六十甲子歌（題擬） 四十六', '六十甲子歌（題擬） 四十六', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["己酉年，耕民但作田。","蟲災𣆟𣆟有，瘟災亦易痊。","山坡堪種植。","斗米直三錢。","低處微傷水，中高甚可憐。"]', '["己酉年，耕民但作田。","蟲災𣆟𣆟有，瘟災亦易痊。","山坡堪種植。","斗米直三錢。","低处微傷水，中高甚可怜。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 四十六 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6acf7497-d96d-407c-b6de-71d11d0f8194', '六十甲子歌（題擬） 四十七', '六十甲子歌（題擬） 四十七', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["庚戌秋，人民不可愁。","江南雖小旱，亦未外方求。","倉諸皆得滿，禾稻美秋收。","田夫俱喜悅，四海盡風流。"]', '["庚戌秋，人民不可愁。","江南雖小旱，亦未外方求。","倉諸皆得满，禾稻美秋收。","田夫俱喜悅，四海尽风流。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 四十七 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93bc3a6c-4862-4379-aaf2-725660e759e1', '六十甲子歌（題擬） 四十八', '六十甲子歌（題擬） 四十八', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["辛亥湊，災疫當處受。","悖黨害平邦，發在滄陵口。","分野有凶災，時應歸隴右。","江南微薄熟，不利吳丘阜。"]', '["辛亥湊，災疫當处受。","悖黨害平邦，發在滄陵口。","分野有凶災，时應归隴右。","江南微薄熟，不利吳丘阜。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 四十八 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('163f680c-f182-4ce6-bc30-3be388189b86', '六十甲子歌（題擬） 四十九', '六十甲子歌（題擬） 四十九', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["壬子直，穀米無人食。","江南足可居，東道征無息。","泗城歸御道，驛路生荆棘。","諸處並荒忙，吳邦堪種植。","。"]', '["壬子直，穀米無人食。","江南足可居，东道征無息。","泗城归御道，驛路生荆棘。","諸处並荒忙，吳邦堪種植。","。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 四十九 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87db1d5d-9816-46f5-87fb-3b82becf43ea', '六十甲子歌（題擬） 五十', '六十甲子歌（題擬） 五十', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["癸丑來，人民定受災。","蓬瀛疫病起，齊魯厄殃摧。","瘟黃災競起，門戶乏人開。","迍蹇仍斯地，桑田又更回。"]', '["癸丑来，人民定受災。","蓬瀛疫病起，齊魯厄殃摧。","瘟黄災競起，门戶乏人开。","迍蹇仍斯地，桑田又更回。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 五十 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85e85aef-38ad-4b87-b2de-087766031cc1', '六十甲子歌（題擬） 五十一', '六十甲子歌（題擬） 五十一', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["甲寅候，江東足餬口。","倉儲諸處空，民戶離鄉走。","又乃發瘟災，遇厄難脫手。","低處必水傷，中高又無有。"]', '["甲寅候，江东足餬口。","倉儲諸处空，民戶離乡走。","又乃發瘟災，遇厄难脫手。","低处必水傷，中高又無有。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 五十一 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a8c2994-4727-4e57-8a5d-ecab76fe8ead', '六十甲子歌（題擬） 五十二', '六十甲子歌（題擬） 五十二', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["乙卯中，四海並交通。","無殃皆得熟，田父美施功。","粟麥最爲首，偏益在山東。","其年多有福，嵗內足狂風。","種植宜須早，高處莫施功。","中低耕最好，高處出蒿蓬。"]', '["乙卯中，四海並交通。","無殃皆得熟，田父美施功。","粟麦最爲首，偏益在山东。","其年多有福，嵗內足狂风。","種植宜須早，高处莫施功。","中低耕最好，高处出蒿蓬。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 五十二 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70206262-3f7a-4c05-9d29-e373e897c7fb', '六十甲子歌（題擬） 五十三', '六十甲子歌（題擬） 五十三', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["丙辰於，禾苗種陸衢。","安泰在濠楚，齊晉受殃殂。","亦復多災水，鹿兔雜羣魚。","是處民乏食，倉庫悉空虛。"]', '["丙辰於，禾苗種陸衢。","安泰在濠楚，齊晉受殃殂。","亦复多災水，鹿兔杂羣鱼。","是处民乏食，倉庫悉空虛。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 五十三 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcae8424-ba01-4965-bdcf-f854bfc77874', '六十甲子歌（題擬） 五十四', '六十甲子歌（題擬） 五十四', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["丁巳周，吳地足風流。","倉庫皆盈滿，滄茫人並遊。","但令逢聖主，遷官不在求。","高低是豐年，人民得自守。"]', '["丁巳周，吳地足风流。","倉庫皆盈满，滄茫人並游。","但令逢聖主，遷官不在求。","高低是豐年，人民得自守。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 五十四 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83ee2037-6ed3-4b76-80cd-9190afc2b0ea', '六十甲子歌（題擬） 五十五', '六十甲子歌（題擬） 五十五', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["戊午扣，家家有三口。","逢患在秋中，少皈多咨咎。","高低皆得收，荒災近末後。","此嵗是豐年，人民得自守。"]', '["戊午扣，家家有三口。","逢患在秋中，少皈多咨咎。","高低皆得收，荒災近末後。","此嵗是豐年，人民得自守。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 五十五 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09bb1bba-b13b-4eb6-9b17-d347e034013c', '六十甲子歌（題擬） 五十六', '六十甲子歌（題擬） 五十六', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["己未裏，畜養逢災厄。","五馬博一牛，定知其嵗後。","糧儲可散求，田中得薄熟。","雖乃逢斯難，不至懷苦憂。"]', '["己未裏，畜養逢災厄。","五马博一牛，定知其嵗後。","糧儲可散求，田中得薄熟。","雖乃逢斯难，不至懷苦憂。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 五十六 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1314a94c-ae86-40ed-bbdc-e1c56d4d4b9b', '六十甲子歌（題擬） 五十七', '六十甲子歌（題擬） 五十七', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["庚申年，稻穀出高田。","夏中有大水，低潛被蟲煎。","莫誇苗艷秀，濠楚亦如然。","低源勞種植，中高甚可憐。","。"]', '["庚申年，稻穀出高田。","夏中有大水，低潛被蟲煎。","莫誇苗艷秀，濠楚亦如然。","低源勞種植，中高甚可怜。","。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 五十七 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ab96e3a-b2ec-4d5b-bc89-89736fca39e8', '六十甲子歌（題擬） 五十八', '六十甲子歌（題擬） 五十八', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["辛酉後，中田將可守。","有旱損高源，大水淹湖部。","早稻被風災，偏苦吳門口。","高低未可安，中平的應有。"]', '["辛酉後，中田將可守。","有旱損高源，大水淹湖部。","早稻被风災，偏苦吳门口。","高低未可安，中平的應有。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 五十八 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c0b2d9e-286a-4e2e-a59c-4808b3dfd3d4', '六十甲子歌（題擬） 五十九', '六十甲子歌（題擬） 五十九', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["壬戌中，高低盡不同。","春夏應遭旱，江南船不通。","秋冬定有旱，低地好施功。","高田徒種植，終是見蒿蓬。","欲知受災處，揚楚及江東。"]', '["壬戌中，高低尽不同。","春夏應遭旱，江南船不通。","秋冬定有旱，低地好施功。","高田徒種植，終是见蒿蓬。","欲知受災处，揚楚及江东。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 五十九 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a54a3eb-da9d-42e1-b97f-906827109d96', '六十甲子歌（題擬） 六十', '六十甲子歌（題擬） 六十', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["癸亥周，吳分坐無憂。","中田最可託，低處不須求。","嵗後青龍伏，中平並可求。","秋冬雖有旱，還是得全收。","（《正統道藏》本杜光庭《太上洞淵神咒經》卷十八。","）（按：《太上洞淵神咒經》，敦煌遺書中有殘本多卷。","此組詩中有「官吏逐階遷，諸道咸通徹」之句。","以道爲行政區劃名，始於唐初。","因知此組詩應爲唐時之作。","以上從《道藏》中杜光庭編撰整理諸書中錄出的詩歌，雖未必皆爲杜光庭之作，但皆爲唐或唐以前人之作。","今姑錄存於杜光庭名下，祈讀者引用時有以注意之。","）。"]', '["癸亥周，吳分坐無憂。","中田最可託，低处不須求。","嵗後青龙伏，中平並可求。","秋冬雖有旱，還是得全收。","（《正統道藏》本杜光庭《太上洞淵神咒經》卷十八。","）（按：《太上洞淵神咒經》，敦煌遺书中有殘本多卷。","此組诗中有「官吏逐階遷，諸道咸通徹」之句。","以道爲行政區劃名，始於唐初。","因知此組诗應爲唐时之作。","以上從《道藏》中杜光庭編撰整理諸书中錄出的诗歌，雖未必皆爲杜光庭之作，但皆爲唐或唐以前人之作。","今姑錄存於杜光庭名下，祈读者引用时有以注意之。","）。"]', '诗', 'shi', '', NULL, '六十甲子歌（題擬） 六十 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bb6bc3a-8e03-4148-903c-f5727a17543c', '句', '句', 'a8f12c15-164e-40e6-9872-52206c7a093b', '唐', '["山遶一城藏古寺，江連二水送孤舟。","（見《錦繡萬花谷續集》卷十三「潼川府」引。","宋之潼川府即唐之梓州。","）。"]', '["山遶一城藏古寺，江連二水送孤舟。","（见《錦繡万花谷續集》卷十三「潼川府」引。","宋之潼川府即唐之梓州。","）。"]', '诗', 'shi', '', NULL, '句 李簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e6c4e94-2e2d-46fb-b824-81dc87fcd44f', '述懷', '述懷', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["白首成空事，無歡可替悲。","空餘酒中興，猶似少年時。","（見王安石《唐百宏壯詩選》卷十九。","李壁《王荆公詩箋注》卷四一引前二句。","）（按：《萬首唐人絕句》卷九三收此詩於崔櫓名下，《全唐詩》卷五六七沿之。","《唐百家詩選》早出，今兩存之。","）。"]', '["白首成空事，無歡可替悲。","空餘酒中兴，猶似少年时。","（见王安石《唐百宏壯诗選》卷十九。","李壁《王荆公诗箋注》卷四一引前二句。","）（按：《万首唐人絕句》卷九三收此诗於崔櫓名下，《全唐诗》卷五六七沿之。","《唐百家诗選》早出，今兩存之。","）。"]', '诗', 'shi', '', NULL, '述懷 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35baec1c-ec74-45d5-b75a-77e047733437', '句 一', '句 一', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["故人行役向邊州。","（《江湖小集》卷二十《梅花衲》引。","）。"]', '["故人行役向邊州。","（《江湖小集》卷二十《梅花衲》引。","）。"]', '诗', 'shi', '', NULL, '句 一 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bdf54b2-46ed-4e79-993e-5fc7ed4f40f2', '句 二', '句 二', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["上饒多勝景，樽酒不應同。","（《記纂淵海》卷十。","）。"]', '["上饒多勝景，樽酒不應同。","（《記纂淵海》卷十。","）。"]', '诗', 'shi', '', NULL, '句 二 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d24b9953-07b5-468e-b746-6355c9aefab2', '寄禪月大師', '寄禪月大師', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["新春新霽好晴和，間濶吾師鄙恡多。","不是爲窮常見隔，祇應嫌醉不相過。","雲離谷口俱無著，日到天心各幾何。","萬事不如碁一局，雨堂閑夜許來麽？","（《禪月集》卷十九。","）。"]', '["新春新霽好晴和，间濶吾師鄙恡多。","不是爲窮常见隔，祇應嫌醉不相過。","云離谷口俱無著，日到天心各幾何。","万事不如碁一局，雨堂闲夜許来麽？","（《禪月集》卷十九。","）。"]', '诗', 'shi', '', NULL, '寄禪月大師 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b21977d-f2b3-4849-93f8-a4bd3abfb6cf', '韋曲', '韋曲', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["滿耳鶯聲滿眼花，布衣藜杖是生涯。","時人若要知名姓，韋曲西頭第一家。","（《類編長安志》卷九。","）。"]', '["满耳鶯声满眼花，布衣藜杖是生涯。","时人若要知名姓，韋曲西头第一家。","（《類編长安志》卷九。","）。"]', '诗', 'shi', '', NULL, '韋曲 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e24e30d8-3a8d-4785-98fd-19c64e8b66cd', '戒童行（慈受二十偈意同）', '戒童行（慈受二十偈意同）', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["勸汝出家須決志，投師學業莫容易。","添香換水結因緣，佛殿僧堂勤掃地。","莫閑游，莫嬉戲，出入分疎說出處。","三朝四宿不見歸，妙法何曾聞一偈。","敬師兄，教師弟，莫向空門爭意氣。","上中下座用謙和，莫賤他人稱自貴。","衣食難，豈容易。","計功多少須慚愧。","隨緣飲啄任精粗，不用千般求細膩。","布素衣，隨時乩，知足便超功果位。","才能豈是皂羅衣，有道何須黃錦被。","清信男，清信女，捨却一身飼餓虎。","此因緣，苦中苦，不用再三說酸楚。","心中有罪自心知，自向心中懺悔取。","親明師，學智慧，別人睡時你慢睡。","出家兒，學妙理，習讀夜眠須早起。","三更睡到四更初，歸向釋迢尊殿裏。","挑明燈，換淨水，禮拜焚香作福祉。","報答三有及四恩，天龍八部生歡喜。","莫愚癡，莫懈怠，一超直入佛境界。","行亦禪，坐亦禪，了達真如觀自在。","（見日本《續藏經》本《禪門諸祖師偈頌》卷下之上。","）。"]', '["勸汝出家須決志，投師学業莫容易。","添香換水結因緣，佛殿僧堂勤掃地。","莫闲游，莫嬉戲，出入分疎说出处。","三朝四宿不见归，妙法何曾闻一偈。","敬師兄，教師弟，莫向空门爭意氣。","上中下座用謙和，莫賤他人稱自貴。","衣食难，豈容易。","計功多少須慚愧。","隨緣饮啄任精粗，不用千般求細膩。","布素衣，隨时乩，知足便超功果位。","才能豈是皂羅衣，有道何須黄錦被。","清信男，清信女，捨却一身飼餓虎。","此因緣，苦中苦，不用再三说酸楚。","心中有罪自心知，自向心中懺悔取。","親明師，学智慧，別人睡时你慢睡。","出家兒，学妙理，習读夜眠須早起。","三更睡到四更初，归向釋迢尊殿裏。","挑明灯，換淨水，禮拜焚香作福祉。","報答三有及四恩，天龙八部生歡喜。","莫愚癡，莫懈怠，一超直入佛境界。","行亦禪，坐亦禪，了達真如观自在。","（见日本《續藏經》本《禪门諸祖師偈頌》卷下之上。","）。"]', '诗', 'shi', '', NULL, '戒童行（慈受二十偈意同） 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f9c8b86-1cef-4093-afc5-97b0d4783717', '大隱四字龜鑑', '大隐四字龟鑑', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["在塵出塵，如何處身？","見善努力，見惡莫親。","縱居暗室，如對大賓。","樂情養性，逢危守貧。","如愚不愚，修仁得仁。","謙讓爲本，孤高作鄰。","少出爲貴，少語最珍。","學無廢日，時習知新。","榮辱慎動，是非勿詢。","常切責己，切忌尤人。","抱璞刖足，興文厄陳。","古聖尚比，吾徒奚伸？","安問世俗，自任天真。","奇哉快哉，坦蕩怡神。","（同前卷上之下。","）。"]', '["在塵出塵，如何处身？","见善努力，见惡莫親。","縱居暗室，如对大賓。","乐情養性，逢危守貧。","如愚不愚，修仁得仁。","謙讓爲本，孤高作鄰。","少出爲貴，少語最珍。","学無廢日，时習知新。","榮辱慎动，是非勿詢。","常切責己，切忌尤人。","抱璞刖足，兴文厄陳。","古聖尚比，吾徒奚伸？","安问世俗，自任天真。","奇哉快哉，坦蕩怡神。","（同前卷上之下。","）。"]', '诗', 'shi', '', NULL, '大隱四字龜鑑 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8185e905-cd77-4827-9779-678da3b4ae47', '題十八賢影堂詩', '題十八賢影堂诗', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["白藕池邊舊影堂，劉雷風骨盡龍章。","共輕天子諸侯貴，惟愛君師一法長。","陶令醉多招不得，謝公心亂入無方。","何人到此思高躅，風點苔痕過短墻。","（《大正藏》第四七冊元普度《廬山蓮宗寶鑑》卷四。","）。"]', '["白藕池邊旧影堂，劉雷风骨尽龙章。","共轻天子諸侯貴，惟愛君師一法长。","陶令醉多招不得，謝公心亂入無方。","何人到此思高躅，风点苔痕過短墻。","（《大正藏》第四七冊元普度《廬山蓮宗寶鑑》卷四。","）。"]', '诗', 'shi', '', NULL, '題十八賢影堂詩 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('935a21f5-ccaa-4dc1-9d3f-f491e9b74777', '題東林寺四首（之一）', '題东林寺四首（之一）', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["閑行閑坐思攀緣，多是東林古寺前。","小瀑便高三百尺，短松多是一千年。","盧楞伽畫苔漫（同書卷二引「浸」）盡，殷仲堪碑雨滴穿。","今欲更崇蓮社去，不知誰是古諸賢。","（見《古石庵叢書》本《廬山記》卷四。","）。"]', '["闲行闲坐思攀緣，多是东林古寺前。","小瀑便高三百尺，短松多是一千年。","盧楞伽畫苔漫（同书卷二引「浸」）尽，殷仲堪碑雨滴穿。","今欲更崇蓮社去，不知誰是古諸賢。","（见《古石庵叢书》本《廬山記》卷四。","）。"]', '诗', 'shi', '', NULL, '題東林寺四首（之一） 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40e27b16-afdb-4803-a385-29395f2f96a5', '讚念法華經僧', '讚念法华經僧', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["空王門下有真子，堪以空王爲了使。","常持菡萏《白蓮經》，屈指無人得相似。","長松下，深窗裏，歷歷清香韻宮徴。","短偈長行主客分，不使閒聲掛牙齒。","外人聞，聳雙耳，香風襲鼻寒毛起。","祇見天花落座前，空中必定有神鬼。","吾師吾師須努力，年深已是成功積。","桑田變海骨爲塵，相看長似紅蓮色。","（見斯四○三七卷。","）。"]', '["空王门下有真子，堪以空王爲了使。","常持菡萏《白蓮經》，屈指無人得相似。","长松下，深窗裏，歷歷清香韻宮徴。","短偈长行主客分，不使閒声掛牙齒。","外人闻，聳雙耳，香风襲鼻寒毛起。","祇见天花落座前，空中必定有神鬼。","吾師吾師須努力，年深已是成功積。","桑田变海骨爲塵，相看长似紅蓮色。","（见斯四○三七卷。","）。"]', '诗', 'shi', '', NULL, '讚念法華經僧 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89c41166-d4ca-44ca-a1df-86e1bcd0bc84', '詠鴈山十八寺', '詠鴈山十八寺', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["本覺凌雲到寶冠，[能]（張）仁古塔上飛泉。","普門羅漢石門裏，瑞鹿華巖天柱邊。","古洞靈峰真際並，靈巖霞嶂淨名連。","石梁不與雙峰遠，十八精藍絨鴈[巔]（嶺）。","（未字不韻，疑爲「山」之誤。","見《全浙詩話》卷九引《甌江逸志》。","陳耀東云見光緒《樂清縣志》卷十六，今據以校改。","）。"]', '["本覺凌云到寶冠，[能]（張）仁古塔上飞泉。","普门羅漢石门裏，瑞鹿华巖天柱邊。","古洞靈峰真際並，靈巖霞嶂淨名連。","石梁不與雙峰远，十八精藍絨鴈[巔]（嶺）。","（未字不韻，疑爲「山」之誤。","见《全浙诗話》卷九引《甌江逸志》。","陳耀东云见光緒《乐清縣志》卷十六，今據以校改。","）。"]', '诗', 'shi', '', NULL, '詠鴈山十八寺 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('414904dd-3f24-4a23-8268-3f9ac14148ef', '龍丘山（題擬）', '龙丘山（題擬）', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["幾朵碧芙蕖，王維圖未圖。","層層皆有瀑，一一合吾居。","雨歇如爭出，嚴霜不到枯。","世猶多事在，爲爾久躊躇。","（見康熙十五年刊楊廷望纂《衢州府志》卷三。","）。"]', '["幾朵碧芙蕖，王維圖未圖。","層層皆有瀑，一一合吾居。","雨歇如爭出，嚴霜不到枯。","世猶多事在，爲爾久躊躇。","（见康熙十五年刊楊廷望纂《衢州府志》卷三。","）。"]', '诗', 'shi', '', NULL, '龍丘山（題擬） 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e1cabb2-ad60-45fa-a0d2-c5c4a92649b6', '硯詩', '硯诗', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["低心蒙潤久，入匣更身安。","（見《類說》卷五九《硯譜》。","）。"]', '["低心蒙潤久，入匣更身安。","（见《類说》卷五九《硯譜》。","）。"]', '诗', 'shi', '', NULL, '硯詩 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe994f83-eef3-40e3-9bd7-2eefff7d5cd5', '句', '句', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["清風江上月，霜灑中石古。","（見《紺珠集》卷九《古今名賢集》引。","）。"]', '["清风江上月，霜灑中石古。","（见《紺珠集》卷九《古今名賢集》引。","）。"]', '诗', 'shi', '', NULL, '句 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dab10cae-60ed-4724-9507-8fcf3cff2687', '過竇道者', '過竇道者', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["經秦歷魏松千尺，浴海挽星月一輪。","（《祖庭事苑》卷四。","）。"]', '["經秦歷魏松千尺，浴海挽星月一輪。","（《祖庭事苑》卷四。","）。"]', '诗', 'shi', '', NULL, '過竇道者 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c548f3bf-9c9e-4a32-8dd9-6b5f3a09a04d', '送邊將', '送邊將', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["但看千騎去，知有幾人歸。","（見《吟窗雜錄》卷十四正字王玄《詩中旨格》引。","）（按：《全唐詩》卷八三七收此二句，缺題，今重錄。","又按：《全唐詩》收貫休詩缺文甚多，今據影印文淵閣《四庫全書》本《禪月集》多可補齊，錄如次。","全詩不重錄。","〖1〗《全唐詩》卷八二六《送姜道士歸南岳》第十一句缺二字，《禪月集》卷二此句作「落葉蕭蕭□杳窅」。","〖2〗《全唐詩》卷八二七《上孫使君》第三十九句缺一字，前書卷三此句作「瑞雪鎖戈鋋」。","〖3〗《全唐詩》卷八二八《送崔使君》第二七句缺二字，前書卷五此句作「望塵一氣連紫闥」。","〖4〗《全唐詩》卷八二九《秋居寄王相公三首》之一首句缺一字，前書卷八此句作「禪林蟬蛻落」。","〖5〗《全唐詩》卷八三○《桐江閒居作十二首》之七第四句缺二字、第八句缺一字，前書卷十此二句作「詩好抵瓊瑤」、「誰更美南朝」。","同詩之八第四句缺二字，前引書作「風栗似鹽苞」。","《嚴陵集》卷二引作「罔葛似鹽苞」。","〖6〗《全唐詩》卷八三○《送黃賓于赴舉》第三、第七句各缺一字，《禪月集》卷十此二句作「二階欣夜雪」、「經師無一事」。","〖7〗《全唐詩》卷八三一《夜對雪寄杜使君》第十四句缺一字，前書卷十二此句作「豐年已可敷」。","〖8〗同書同卷《避寇白沙驛作》第五句缺三字，前書卷十二此句作「寇亂時時作」。","〖9〗同書同卷《送友人之嶺外》第七句缺一字，前書卷十三此句作「明時好登進」。","〖10〗《全唐詩》卷八三二《別東林僧》第三句缺二字，前書卷十五此句作「明時好登進」。","〖11〗《禪月集》有自注云：「雙□□□□大夫宅。","」《送杜使君朝覲》末句缺一字，《四庫全書》本《禪月集》卷十四此句作「應許代天功」。","〖12〗《全唐詩》卷八三三《送僧歸山》第六句缺一句，《四部叢刊》本《禪月集》卷十六此句作「塢燥燒如靁」。","《四庫全書》本亦缺一字。","〖13〗《全唐詩》卷八三五《經弟妹墳》第五句缺二字，《四庫全書》本《禪月集》卷十九此句作「鴻衝碧漢霜中斷」。","）（〖14〗《全唐詩》卷八三五《大蜀皇帝潛龍日述聖德詩五首》之二第五句缺三字，第六句缺一字，前書卷二十此二句作「風清鼙角山河壯，劍肅神龍草木寒」。","〖15〗《全唐詩》卷八三六《東陽罹亂後懷王慥使君五首》之一第三句缺一字，前書卷二十二此句作「裂地鼓鼙軍羽急」。","〖16〗同書同卷《避地毘陵寒月上孫徽使君兼寄東陽王使君三首》之三首句缺一字，前書卷二十二此句作「殷雷車雨滴階聲」。","）。"]', '["但看千騎去，知有幾人归。","（见《吟窗杂錄》卷十四正字王玄《诗中旨格》引。","）（按：《全唐诗》卷八三七收此二句，缺題，今重錄。","又按：《全唐诗》收貫休诗缺文甚多，今據影印文淵閣《四庫全书》本《禪月集》多可補齊，錄如次。","全诗不重錄。","〖1〗《全唐诗》卷八二六《送姜道士归南岳》第十一句缺二字，《禪月集》卷二此句作「落葉蕭蕭□杳窅」。","〖2〗《全唐诗》卷八二七《上孫使君》第三十九句缺一字，前书卷三此句作「瑞雪鎖戈鋋」。","〖3〗《全唐诗》卷八二八《送崔使君》第二七句缺二字，前书卷五此句作「望塵一氣連紫闥」。","〖4〗《全唐诗》卷八二九《秋居寄王相公三首》之一首句缺一字，前书卷八此句作「禪林蟬蛻落」。","〖5〗《全唐诗》卷八三○《桐江閒居作十二首》之七第四句缺二字、第八句缺一字，前书卷十此二句作「诗好抵瓊瑤」、「誰更美南朝」。","同诗之八第四句缺二字，前引书作「风栗似鹽苞」。","《嚴陵集》卷二引作「罔葛似鹽苞」。","〖6〗《全唐诗》卷八三○《送黄賓于赴舉》第三、第七句各缺一字，《禪月集》卷十此二句作「二階欣夜雪」、「經師無一事」。","〖7〗《全唐诗》卷八三一《夜对雪寄杜使君》第十四句缺一字，前书卷十二此句作「豐年已可敷」。","〖8〗同书同卷《避寇白沙驛作》第五句缺三字，前书卷十二此句作「寇亂时时作」。","〖9〗同书同卷《送友人之嶺外》第七句缺一字，前书卷十三此句作「明时好登進」。","〖10〗《全唐诗》卷八三二《別东林僧》第三句缺二字，前书卷十五此句作「明时好登進」。","〖11〗《禪月集》有自注云：「雙□□□□大夫宅。","」《送杜使君朝覲》末句缺一字，《四庫全书》本《禪月集》卷十四此句作「應許代天功」。","〖12〗《全唐诗》卷八三三《送僧归山》第六句缺一句，《四部叢刊》本《禪月集》卷十六此句作「塢燥燒如靁」。","《四庫全书》本亦缺一字。","〖13〗《全唐诗》卷八三五《經弟妹墳》第五句缺二字，《四庫全书》本《禪月集》卷十九此句作「鴻衝碧漢霜中斷」。","）（〖14〗《全唐诗》卷八三五《大蜀皇帝潛龙日述聖德诗五首》之二第五句缺三字，第六句缺一字，前书卷二十此二句作「风清鼙角山河壯，劍肅神龙草木寒」。","〖15〗《全唐诗》卷八三六《东陽罹亂後懷王慥使君五首》之一第三句缺一字，前书卷二十二此句作「裂地鼓鼙軍羽急」。","〖16〗同书同卷《避地毘陵寒月上孫徽使君兼寄东陽王使君三首》之三首句缺一字，前书卷二十二此句作「殷雷车雨滴階声」。","）。"]', '诗', 'shi', '', NULL, '送邊將 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07483dda-9ef2-4f89-b3bd-e99dcd5adb6f', '爲貫休作（題擬）', '爲貫休作（題擬）', '5814e145-f829-4e87-a05d-baa99c491450', '唐', '["分袂無血淚，望處空闌干。","（見《四部叢刊》本《禪月集》附曇域《後序》引。","）。"]', '["分袂無血泪，望处空闌干。","（见《四部叢刊》本《禪月集》附曇域《後序》引。","）。"]', '诗', 'shi', '', NULL, '爲貫休作（題擬） 處默 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af855f33-4ce0-4628-98fd-0067b55cdcda', '冬夜宴柳駙馬陟宅得更字', '冬夜宴柳駙马陟宅得更字', '5216e078-555a-4540-bda4-099bd291516f', '唐', '["蘭堂夜宴在秦城，座上荷衣倍覺榮。","金鼎烹炮過百味，銅壺刻漏轉三更。","紅妝伎出催添燭，白雪哀遲待煖笙。","猶自何郎歡不足，桂華未謝玉峰傾。","（見蜀何光遠《鑑戒錄》卷八《屈名儒》。","）。"]', '["蘭堂夜宴在秦城，座上荷衣倍覺榮。","金鼎烹炮過百味，銅壺刻漏轉三更。","紅妝伎出催添燭，白雪哀遲待煖笙。","猶自何郎歡不足，桂华未謝玉峰傾。","（见蜀何光远《鑑戒錄》卷八《屈名儒》。","）。"]', '诗', 'shi', '', NULL, '冬夜宴柳駙馬陟宅得更字 盧延讓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a707d2f1-1979-44c6-b2dd-9e5a053696bd', '', '', '9dfd0345-e619-43f5-98ba-9cb12e359aba', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 宋光嗣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef13b6c7-5161-4a93-b10a-c8262b8363cf', '判行營將士申請裹糧', '判行營將士申請裹糧', '9dfd0345-e619-43f5-98ba-9cb12e359aba', '唐', '["纔請冬賜，又給行裝。","漢州咫尺，要甚裹糧？","綿州物賤，直到益昌。"]', '["纔請冬賜，又給行裝。","漢州咫尺，要甚裹糧？","綿州物賤，直到益昌。"]', '诗', 'shi', '', NULL, '判行營將士申請裹糧 宋光嗣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6da76f0f-3485-48fa-a971-ca144c133e2d', '判內庭求事人', '判內庭求事人', '9dfd0345-e619-43f5-98ba-9cb12e359aba', '唐', '["覓事撮巔拗（一作「領襭」），勾當須教了。","儻若有闕疑，禁君直到老。"]', '["覓事撮巔拗（一作「領襭」），勾當須教了。","儻若有闕疑，禁君直到老。"]', '诗', 'shi', '', NULL, '判內庭求事人 宋光嗣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e84eaa30-ad72-4303-9a72-9bb3cbdc900d', '判導江縣申狀封皮上著狀門府衙', '判導江縣申狀封皮上著狀门府衙', '9dfd0345-e619-43f5-98ba-9cb12e359aba', '唐', '["勅加開府，不是門府。","典押雙眇，令佐單瞽。","量提書罰，勝打十五。","令佐盤庚，典押歲取。","事了速歸，用修廨宇。"]', '["勅加开府，不是门府。","典押雙眇，令佐單瞽。","量提书罰，勝打十五。","令佐盤庚，典押歲取。","事了速归，用修廨宇。"]', '诗', 'shi', '', NULL, '判導江縣申狀封皮上著狀門府衙 宋光嗣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0992d97b-3c6f-44b3-bc30-68dc0bfcf459', '判小朝官郭延鈞進識字女子', '判小朝官郭延鈞進識字女子', '9dfd0345-e619-43f5-98ba-9cb12e359aba', '唐', '["進來便是宮人，狀內猶言女子。","應見容止可觀，遂令始製文字。","更遣阿母教招，恨不太真相似。","且圖親近官家，直向內廷求事。"]', '["進来便是宮人，狀內猶言女子。","應见容止可观，遂令始製文字。","更遣阿母教招，恨不太真相似。","且圖親近官家，直向內廷求事。"]', '诗', 'shi', '', NULL, '判小朝官郭延鈞進識字女子 宋光嗣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22808982-2397-4b37-8671-e008ba3e4a1d', '判神奇軍背軍官健李紹妻阿鄧乞改嫁', '判神奇軍背軍官健李紹妻阿鄧乞改嫁', '9dfd0345-e619-43f5-98ba-9cb12e359aba', '唐', '["淡紅衫子赤輝輝，不抹燕，不畫眉，未壻背軍緣甚事，女人別嫁欲何爲。","孤兒攜去君爭忍，抵子歸來我不知。","若有支持且須守，口中爭著兩把匙。"]', '["淡紅衫子赤輝輝，不抹燕，不畫眉，未壻背軍緣甚事，女人別嫁欲何爲。","孤兒携去君爭忍，抵子归来我不知。","若有支持且須守，口中爭著兩把匙。"]', '诗', 'shi', '', NULL, '判神奇軍背軍官健李紹妻阿鄧乞改嫁 宋光嗣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81fd7686-5915-40fe-a720-572123ba29a9', '判簡州刺史安太尉申院狀希酒場云係州收搉', '判簡州刺史安太尉申院狀希酒場云係州收搉', '9dfd0345-e619-43f5-98ba-9cb12e359aba', '唐', '["安胡安胡，空有髭鬚。","所見不遠，智解全愚。","酒場是太后教令，問你還有耳孔也無。"]', '["安胡安胡，空有髭鬚。","所见不远，智解全愚。","酒場是太后教令，问你還有耳孔也無。"]', '诗', 'shi', '', NULL, '判簡州刺史安太尉申院狀希酒場云係州收搉 宋光嗣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2aac7f42-bdeb-4cb5-8fde-2c8a31e056f8', '判內門捉得御廚雜使衙官偷肉', '判內门捉得御廚杂使衙官偷肉', '9dfd0345-e619-43f5-98ba-9cb12e359aba', '唐', '["斤斤肉是官家物，飽祭喉嚨（一作「隴頭」）更將出。","不能爲食斬君頭，領送右巡枷見骨。","（均見四處何光遠《鑑誡錄》卷六《戲判作》。","）。"]', '["斤斤肉是官家物，飽祭喉嚨（一作「隴头」）更將出。","不能爲食斬君头，領送右巡枷见骨。","（均见四处何光远《鑑誡錄》卷六《戲判作》。","）。"]', '诗', 'shi', '', NULL, '判內門捉得御廚雜使衙官偷肉 宋光嗣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b4f4a2d-5827-4cab-bf7e-b44be72f5b59', '應制', '應制', '4fd5a141-6637-4375-bf17-2525c97fbfe3', '唐', '["一段聖琉璃。","（見《說郛》卷六一《清異錄》。","）（〖1〗《清異錄》：「王衍伶官王家樂侍燕小池，水澄天見，家樂應制曰〖略〗。","」）。"]', '["一段聖琉璃。","（见《说郛》卷六一《清異錄》。","）（〖1〗《清異錄》：「王衍伶官王家乐侍燕小池，水澄天见，家乐應制曰〖略〗。","」）。"]', '诗', 'shi', '', NULL, '應制 王家樂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41244b03-6ed6-41dd-bab5-0aaa85a6ad75', '自製詞', '自製词', '36559e27-8f95-4a6a-bd64-4285e9dabeb6', '唐', '["畫羅衫子畫羅裙，能結束，稱腰身。","柳眉桃臉不勝春。","薄媚足精神。","可惜許，流落在風塵。","（見《分門古今類事》卷十三《該聞錄》引。","）（按：《全唐詩》卷八八九收此詞，題作《甘州曲》，無首句前四字。","第六句無「許」字，遂與下連作七字句。","今重錄之。","）（《該聞錄》，宋初李畋作。","）。"]', '["畫羅衫子畫羅裙，能結束，稱腰身。","柳眉桃臉不勝春。","薄媚足精神。","可惜許，流落在风塵。","（见《分门古今類事》卷十三《該闻錄》引。","）（按：《全唐诗》卷八八九收此词，題作《甘州曲》，無首句前四字。","第六句無「許」字，遂與下連作七字句。","今重錄之。","）（《該闻錄》，宋初李畋作。","）。"]', '诗', 'shi', '', NULL, '自製詞 王衍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('063ff17c-7fa5-4421-8a78-5842d6dc358c', '曲子', '曲子', '36559e27-8f95-4a6a-bd64-4285e9dabeb6', '唐', '["盡是（《五代詩話》引作「贏得」）一場傀儡。","（《類說》卷四三引《北夢瑣言》。","）。"]', '["尽是（《五代诗話》引作「贏得」）一場傀儡。","（《類说》卷四三引《北梦瑣言》。","）。"]', '诗', 'shi', '', NULL, '曲子 王衍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3819d678-dee1-4318-b1fd-c4c038433fe1', '采桑子（途中作）', '采桑子（途中作）', 'b894f643-d215-42d6-b2f0-e9a505899c75', '唐', '["初離蜀道心將碎，離恨綿綿。","春日如年，馬上時時聞杜鵑。","三千宮女皆花貌，妾最嬋娟。","此去朝天，只恐君王寵愛偏。","（見《能改齋漫錄》卷十六。","）（按：《全唐詩》卷八九九僅收此詞之上半闕。","一說後半片爲後人補作。","）。"]', '["初離蜀道心將碎，離恨綿綿。","春日如年，马上时时闻杜鵑。","三千宮女皆花貌，妾最嬋娟。","此去朝天，只恐君王寵愛偏。","（见《能改斋漫錄》卷十六。","）（按：《全唐诗》卷八九九僅收此词之上半闕。","一说後半片爲後人補作。","）。"]', '诗', 'shi', '', NULL, '采桑子（途中作） 花蘂夫人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38d808f0-defc-462c-9c64-86840fd863be', '宮詞', '宮词', 'b894f643-d215-42d6-b2f0-e9a505899c75', '唐', '["雨灑瑤階花盡開，君王應是看花來。","靜憑雕欄渾忘倦，忽聽笙簧殿外回。","（見毛氏汲古閣本《花蘂夫人宮詞》。","轉錄自《開明書店廿週年紀念文集》所刊浦江清《花蘂夫人宮詞考證》。","浦云此詩他本俱無，未詳來歷。","）。"]', '["雨灑瑤階花尽开，君王應是看花来。","静憑雕欄渾忘倦，忽听笙簧殿外回。","（见毛氏汲古閣本《花蘂夫人宮词》。","轉錄自《开明书店廿週年紀念文集》所刊浦江清《花蘂夫人宮词考證》。","浦云此诗他本俱無，未詳来歷。","）。"]', '诗', 'shi', '', NULL, '宮詞 花蘂夫人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('189b760a-5397-4e90-8850-7f2e0da46aea', '句', '句', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["猺女鬅鬆卍字螺。","（清沈雄《古今詞話·詞品》下卷。","）。"]', '["猺女鬅鬆卍字螺。","（清沈雄《古今词話·词品》下卷。","）。"]', '诗', 'shi', '', NULL, '句 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bbbfd59-4fec-4c4b-b050-2f732bb8aa13', '感皇恩', '感皇恩', 'f3e2faf5-0f25-4bef-b6e6-716598d254b4', '唐', '["最好是，長街裏，聽喝相公來。","（見宋江少虞《皇朝事實類苑》卷六六引《楊文公談苑》。","）。"]', '["最好是，长街裏，听喝相公来。","（见宋江少虞《皇朝事實類苑》卷六六引《楊文公談苑》。","）。"]', '诗', 'shi', '', NULL, '感皇恩 張格 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d648912-34f7-459f-902d-c6b0548977be', '贈孫真人', '贈孫真人', '22d20dee-bba6-4790-9ea6-b9bad895e928', '唐', '["世上屢更改，山中常晏安。","六爻窮《易》象，九轉鍊神丹。","洞裏花開晚，峯頭雪落殘。","爲余琴一弄，鶴舞下松端。","（影印本《詩淵》第一冊第四○七頁。","）。"]', '["世上屢更改，山中常晏安。","六爻窮《易》象，九轉鍊神丹。","洞裏花开晚，峯头雪落殘。","爲余琴一弄，鹤舞下松端。","（影印本《诗淵》第一冊第四○七頁。","）。"]', '诗', 'shi', '', NULL, '贈孫真人 可朋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80a23612-5ccd-4d5d-b219-dca2f089d11e', '贈友人', '贈友人', '22d20dee-bba6-4790-9ea6-b9bad895e928', '唐', '["來多不自（一作「似」）客，坐久却垂簾。","（見《吟窗雜錄》卷三二《古今詩僧》。","）。"]', '["来多不自（一作「似」）客，坐久却垂簾。","（见《吟窗杂錄》卷三二《古今诗僧》。","）。"]', '诗', 'shi', '', NULL, '贈友人 可朋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2aa693aa-01d7-4276-95b8-0bc842459279', '寄齊己', '寄齊己', '22d20dee-bba6-4790-9ea6-b9bad895e928', '唐', '["雖（一作「唯」）陪北楚三千客，多話東林十八賢。","（同前。","又見《唐詩紀事》卷七四。","）（按：以上四句《全唐詩》卷八四九已收，缺題，今重錄。","）。"]', '["雖（一作「唯」）陪北楚三千客，多話东林十八賢。","（同前。","又见《唐诗紀事》卷七四。","）（按：以上四句《全唐诗》卷八四九已收，缺題，今重錄。","）。"]', '诗', 'shi', '', NULL, '寄齊己 可朋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bae5ac26-e789-4136-a01b-afa5ae8fd389', '復爲翰林作（題擬）', '复爲翰林作（題擬）', '72eeb99b-0933-4b31-876c-2465ec0aa444', '唐', '["昔年追感淚橫流，今日尋悲是漫愁。","容易得來容易失，等閑成了等閑休。","皇圖本謂兒孫置，白刃番成骨肉讐。","梁漢後唐三世主，九泉相見大悠悠。","（見《類說》卷十九李畋《該聞錄》。","）（〖1〗《該聞錄》：「歐陽彬三蜀時爲翰林學士，唐明宗時入洛，責令歸蜀。","孟氏開國，復爲翰林，作詩云〖略〗。","」）。"]', '["昔年追感泪橫流，今日尋悲是漫愁。","容易得来容易失，等闲成了等闲休。","皇圖本謂兒孫置，白刃番成骨肉讐。","梁漢後唐三世主，九泉相见大悠悠。","（见《類说》卷十九李畋《該闻錄》。","）（〖1〗《該闻錄》：「歐陽彬三蜀时爲翰林学士，唐明宗时入洛，責令归蜀。","孟氏开国，复爲翰林，作诗云〖略〗。","」）。"]', '诗', 'shi', '', NULL, '復爲翰林作（題擬） 歐陽彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d5f7911-a098-49b6-84ff-217c413ae14c', '秋山圖歌', '秋山圖歌', 'bb073a2a-a950-41b2-b757-8e6089e7b854', '唐', '["空（按：《全唐詩》卷七六一題作《題黃居宷秋山圖》，今從《王氏畫苑叢書》本《益州名畫錄》卷中。","其第十七、十八句，《全唐詩》作「月檻參橋□，僧老坐搘筇」，檢《益州名畫錄》，此段應作：「月檻參差錦繡躍，星壇斑駁翠苔封。","傍岸牛羸行嚼草，過橋僧老坐嗜筇。","」《全唐詩》殆脫去十八字，今爲補出。","全詩甚長，不重錄。","）。"]', '["空（按：《全唐诗》卷七六一題作《題黄居宷秋山圖》，今從《王氏畫苑叢书》本《益州名畫錄》卷中。","其第十七、十八句，《全唐诗》作「月檻參橋□，僧老坐搘筇」，檢《益州名畫錄》，此段應作：「月檻參差錦繡躍，星壇斑駁翠苔封。","傍岸牛羸行嚼草，過橋僧老坐嗜筇。","」《全唐诗》殆脫去十八字，今爲補出。","全诗甚长，不重錄。","）。"]', '诗', 'shi', '', NULL, '秋山圖歌 徐光溥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c71014f7-540b-419f-82b1-9bc6a0eb9446', '歌', '歌', '782cd56a-eb4a-4253-817c-2024d9f76d6a', '唐', '["莫傳讀得五車書，莫言文似馬相如。","不如家有一鎰金，一囊珠，可以賂相公之子弟，結相公之僮奴。","便可朝爲屠沽，夕乘軒車。","（見《類說》卷二七《外史檮杌》。","末云：「詞多不備載。","」）。"]', '["莫傳读得五车书，莫言文似马相如。","不如家有一鎰金，一囊珠，可以賂相公之子弟，結相公之僮奴。","便可朝爲屠沽，夕乘軒车。","（见《類说》卷二七《外史檮杌》。","末云：「词多不備載。","」）。"]', '诗', 'shi', '', NULL, '歌 鄭奕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd38ced3-ea06-46c6-bb27-5ef0083c7938', '書壁（題擬）', '书壁（題擬）', '405f5127-5107-4ef2-afeb-68bf1b3e6c52', '唐', '["酒客乾喉去，唯存呷大夫。","（見《說郛》卷六一《清異錄》。","）（〖1〗《清異錄》：「家述、掌聿修仕僞蜀爲太子左贊善大夫。","兩人皆滑稽。","聿修伺述酒翁將竭，叩門求飲，未通大道，已見罍耻，濡筆書壁曰〖詩略〗。","」）。"]', '["酒客乾喉去，唯存呷大夫。","（见《说郛》卷六一《清異錄》。","）（〖1〗《清異錄》：「家述、掌聿修仕僞蜀爲太子左贊善大夫。","兩人皆滑稽。","聿修伺述酒翁將竭，叩门求饮，未通大道，已见罍耻，濡笔书壁曰〖诗略〗。","」）。"]', '诗', 'shi', '', NULL, '書壁（題擬） 掌聿修 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8672524d-bb03-407f-b2e7-05f326cf0cbb', '失題', '失題', 'bc411a10-e9f1-4dd0-9f6e-8cee20fc341d', '唐', '["閑行閑坐復閑吟，一片澄然太古心。","拾得好詩清似玉，練來虛府靜如琴。","已將蛇足師陳軫，懶把蠅頭愛華歆。","必也長磨到如此，退身何更羨雲岑。","（見《新編分門古今類事》卷十二引李畋《該聞錄》。","）。"]', '["闲行闲坐复闲吟，一片澄然太古心。","拾得好诗清似玉，練来虛府静如琴。","已將蛇足師陳軫，懶把蠅头愛华歆。","必也长磨到如此，退身何更羨云岑。","（见《新編分门古今類事》卷十二引李畋《該闻錄》。","）。"]', '诗', 'shi', '', NULL, '失題 田淳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08a180f2-88ed-48b4-b719-c3e31d4c05cd', '偈', '偈', '27cc0080-6751-4a42-8001-d19c610c0521', '唐', '["昔日古伽藍，名爲王董龕。","數載無僧俗，積歲少人瞻。","縣鎮興三善，率土盡莊嚴。","我佛□□□，□□□□□。","（《八瓊室金石補正》卷八一紹□撰《普慈縣永封里再興王董龕報國院碑記》附。","）。"]', '["昔日古伽藍，名爲王董龕。","數載無僧俗，積歲少人瞻。","縣鎮兴三善，率土尽莊嚴。","我佛□□□，□□□□□。","（《八瓊室金石補正》卷八一紹□撰《普慈縣永封里再兴王董龕報国院碑記》附。","）。"]', '诗', 'shi', '', NULL, '偈 李仁悅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70d11b1f-bdf5-4499-9665-57ab258b1c0b', '洞仙歌', '洞仙歌', 'e65bc0a5-ce99-4c63-ba0c-aba1f79385f0', '唐', '["冰肌玉骨，自清涼無汗。","貝闕琳宮恨初遠。","玉闌千倚遍，怯盡朝寒；回首處，何必留連穆滿。","芙蓉開過也，樓閣香融，千片紅英泛波面。","洞房深深鎖，莫放輕舟，瑤臺去，甘與塵祖師寰路斷。","更莫遣流紅到人間，怕一似當時，誤他劉阮。","（宋趙聞禮《陽春白雪》卷二。","）（按：蘇軾《洞仙歌序》，謂老尼能誦孟昶此詞首二句，不見全篇，乃爲足之。","後《漫叟詩話》、《本事曲》載孟昶《玉樓春》詞，以爲即原作，但宋時即有人疑爲後人據東坡詞隱括而成，並非孟作。","趙聞禮此詞，云爲「蜀帥謝元明因開摩訶池，得古石刻，遂見全篇。","」似較可信，然清宋翔鳳《樂府餘論》亦疑爲南宋人僞託，但幷無確證。","說詳王水照先生《蘇軾選集》。","《全唐詩》卷八收《避暑摩訶池上作》一首，即世傳之《玉樓春》詞。","）。"]', '["冰肌玉骨，自清涼無汗。","貝闕琳宮恨初远。","玉闌千倚遍，怯尽朝寒；回首处，何必留連穆满。","芙蓉开過也，楼閣香融，千片紅英泛波面。","洞房深深鎖，莫放轻舟，瑤台去，甘與塵祖師寰路斷。","更莫遣流紅到人间，怕一似當时，誤他劉阮。","（宋趙闻禮《陽春白雪》卷二。","）（按：蘇軾《洞仙歌序》，謂老尼能誦孟昶此词首二句，不见全篇，乃爲足之。","後《漫叟诗話》、《本事曲》載孟昶《玉楼春》词，以爲即原作，但宋时即有人疑爲後人據东坡词隐括而成，並非孟作。","趙闻禮此词，云爲「蜀帥謝元明因开摩訶池，得古石刻，遂见全篇。","」似較可信，然清宋翔鳳《乐府餘論》亦疑爲南宋人僞託，但幷無確證。","说詳王水照先生《蘇軾選集》。","《全唐诗》卷八收《避暑摩訶池上作》一首，即世傳之《玉楼春》词。","）。"]', '诗', 'shi', '', NULL, '洞仙歌 孟昶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('909823b5-8123-481c-ac20-339223b4e4aa', '出西郊遊古陌作（題擬）', '出西郊游古陌作（題擬）', '4f9d5608-9ade-483f-a5a5-5029114a230e', '唐', '["雖（《洞微志》作「誰」）言今古事難窮，大抵榮枯總是空。","算得生前隨夢蝶，爭如雲外指冥鴻。","暗添雪色眉根白，旋落花光臉上紅。","惆悵荒原懶回首，暮林蕭瑟起悲風。","（見宋佚名《新編分門古今類事》卷四引《名賢小說》。","）（〖1〗《名賢小說》謂處厚於「孟氏廣政丁卯歲下第」，遇一僧，謂處厚明春可及第，但以「百日爲程」。","次年「及放牓，處厚果第一。","」。","「處厚心惡百日之語，日出西郊遊古陌」，吟詩云云。","「及暮還家，暴卒。","」《增修詩話總龜》卷三十一引《洞微志》敘事甚略，不言其下第之年。","陸心源《宋詩紀事補遺》卷二收處厚詩，傳謂宋初進士，未允。","《文獻通考·選舉考》載宋初狀元，無處厚，可證。","惟廣政無丁卯年，疑原文所記有誤。","）。"]', '["雖（《洞微志》作「誰」）言今古事难窮，大抵榮枯總是空。","算得生前隨梦蝶，爭如云外指冥鴻。","暗添雪色眉根白，旋落花光臉上紅。","惆悵荒原懶回首，暮林蕭瑟起悲风。","（见宋佚名《新編分门古今類事》卷四引《名賢小说》。","）（〖1〗《名賢小说》謂处厚於「孟氏廣政丁卯歲下第」，遇一僧，謂处厚明春可及第，但以「百日爲程」。","次年「及放牓，处厚果第一。","」。","「处厚心惡百日之語，日出西郊游古陌」，吟诗云云。","「及暮還家，暴卒。","」《增修诗話總龟》卷三十一引《洞微志》敘事甚略，不言其下第之年。","陸心源《宋诗紀事補遺》卷二收处厚诗，傳謂宋初進士，未允。","《文獻通考·選舉考》載宋初狀元，無处厚，可證。","惟廣政無丁卯年，疑原文所記有誤。","）。"]', '诗', 'shi', '', NULL, '出西郊遊古陌作（題擬） 王處厚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('968cfb61-7c28-4c25-a4a9-c00d7d567d6c', '芙蓉堂', '芙蓉堂', 'c9e34a83-878f-419b-ae2d-d39070dd125e', '唐', '["昔時曾從漢梁王，濯錦江邊醉幾場。","拂石坐來衫袖冷，踏花歸去馬蹄香。","當初酒賤寧辭醉，今日愁來不易當。","暗想舊遊渾似夢，芙蓉城下水茫茫。","（見宋蔡夢弼《杜工部朝草堂詩箋》附《杜工部草堂詩話》卷一引揚湜《古今詞話》引。","《竹莊詩話》卷二十四引三、四兩句，題作《古詩》。","）（〖1〗蔡夢弼云：「《古今詞話》：『蜀人《將進酒》，嘗以爲少陵詩，作《瑞鷓鴣》唱之：〖詩略〗。","』此詩或謂杜甫，或謂鬼仙，或謂曲詞，未知孰是。","然詳味其言，唐人語也。","首先有『曾從漢梁王』之句，決非子美作也。","況集中不載，灼可見矣。","不知楊曼倩何所據云。","」〖2〗《文史》第二輯刊拙存《杜甫瑞鷓鴣詞考》云：「今按宋周麟之《海陵集》卷一《呈郫人李人僉判》詩有注云：『吾家本郫人。","先侍郎侍蜀日《芙蓉堂》詩有「踏花歸去馬蹄香」句。","』同卷《送呂道人》詩亦有注云：『余家本郫人，先侍郎仕孟蜀現爲翰林學士，有「拂石坐來衫袖冷，踏花歸去馬蹄香」之句傳於世。","嘗隱居青城山。","』世無有以他人作品爲祖先所作者。","周麟之云是其先人之詩，當屬可信。","此首實五代後蜀周某所作的詩，既非少陵作，亦非鬼仙詩。","楊湜云蜀人《將進酒》，疑原題即爲《將進酒》也。","此詩《全唐詩》失收，蓋以爲宋人作也。","」今從其說收入，唯詩題仍從周麟之所引。","）。"]', '["昔时曾從漢梁王，濯錦江邊醉幾場。","拂石坐来衫袖冷，踏花归去马蹄香。","當初酒賤寧辞醉，今日愁来不易當。","暗想旧游渾似梦，芙蓉城下水茫茫。","（见宋蔡梦弼《杜工部朝草堂诗箋》附《杜工部草堂诗話》卷一引揚湜《古今词話》引。","《竹莊诗話》卷二十四引三、四兩句，題作《古诗》。","）（〖1〗蔡梦弼云：「《古今词話》：『蜀人《將進酒》，嘗以爲少陵诗，作《瑞鷓鴣》唱之：〖诗略〗。","』此诗或謂杜甫，或謂鬼仙，或謂曲词，未知孰是。","然詳味其言，唐人語也。","首先有『曾從漢梁王』之句，決非子美作也。","況集中不載，灼可见矣。","不知楊曼倩何所據云。","」〖2〗《文史》第二輯刊拙存《杜甫瑞鷓鴣词考》云：「今按宋周麟之《海陵集》卷一《呈郫人李人僉判》诗有注云：『吾家本郫人。","先侍郎侍蜀日《芙蓉堂》诗有「踏花归去马蹄香」句。","』同卷《送呂道人》诗亦有注云：『余家本郫人，先侍郎仕孟蜀現爲翰林学士，有「拂石坐来衫袖冷，踏花归去马蹄香」之句傳於世。","嘗隐居青城山。","』世無有以他人作品爲祖先所作者。","周麟之云是其先人之诗，當屬可信。","此首實五代後蜀周某所作的诗，既非少陵作，亦非鬼仙诗。","楊湜云蜀人《將進酒》，疑原題即爲《將進酒》也。","此诗《全唐诗》失收，蓋以爲宋人作也。","」今從其说收入，唯诗題仍從周麟之所引。","）。"]', '诗', 'shi', '', NULL, '芙蓉堂 周□ shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f11e24c-acad-4e2f-bbe7-ef89bad82cc4', '登戎州江樓閑望', '登戎州江楼闲望', 'b5c5c12e-3c6b-4345-a5b8-f80832d623c0', '唐', '["滿目江山四望幽，白雲高卷嶂煙收。","日廻禽影穿疎木，風遞猿聲入小樓。","遠岫似屏橫碧落，斷帆如葉截中流。","[□□□□□□□，□□□□□□□]。","（見《輿地紀勝》卷一六三《敘州》。","）（按：《全唐詩》卷七六一收三四兩句。","）。"]', '["满目江山四望幽，白云高卷嶂煙收。","日廻禽影穿疎木，风遞猿声入小楼。","远岫似屏橫碧落，斷帆如葉截中流。","[□□□□□□□，□□□□□□□]。","（见《輿地紀勝》卷一六三《敘州》。","）（按：《全唐诗》卷七六一收三四兩句。","）。"]', '诗', 'shi', '', NULL, '登戎州江樓閑望 幸夤遜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('705b70d7-5b52-4b67-a1c0-c2486ceb8f5b', '雲', '云', 'b5c5c12e-3c6b-4345-a5b8-f80832d623c0', '唐', '["片片飛來靜又閑，樓頭江上復山前。","飄零盡日不歸去，帖破清光萬里天。","（見《宛委別藏》本《分門纂類唐宋時賢千家詩選》卷十二。","）。"]', '["片片飞来静又闲，楼头江上复山前。","飄零尽日不归去，帖破清光万里天。","（见《宛委別藏》本《分门纂類唐宋时賢千家诗選》卷十二。","）。"]', '诗', 'shi', '', NULL, '雲 幸夤遜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51a9cdbb-8ee3-4b9f-ba44-a7bf8b0e19b7', '雪（題擬）', '雪（題擬）', 'b5c5c12e-3c6b-4345-a5b8-f80832d623c0', '唐', '["巧剪銀花亂，輕飛玉葉狂。","（見《古今合璧事類備要爲前集》卷三。","）。"]', '["巧剪銀花亂，轻飞玉葉狂。","（见《古今合璧事類備要爲前集》卷三。","）。"]', '诗', 'shi', '', NULL, '雪（題擬） 幸夤遜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91f7d8af-e61e-437b-b4f2-76058c1d4528', '杏花（題擬）', '杏花（題擬）', 'b5c5c12e-3c6b-4345-a5b8-f80832d623c0', '唐', '["寒艷芳姿色盡明。","（見同書《別集》卷二八。","）。"]', '["寒艷芳姿色尽明。","（见同书《別集》卷二八。","）。"]', '诗', 'shi', '', NULL, '杏花（題擬） 幸夤遜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd1d9e4d-af24-4cd9-ac45-ace5cfd3a7ce', '句', '句', 'b5c5c12e-3c6b-4345-a5b8-f80832d623c0', '唐', '["片逐銀蟾落醉觥。","（《江湖小集》卷二十，李龏《梅花衲》引。","）。"]', '["片逐銀蟾落醉觥。","（《江湖小集》卷二十，李龏《梅花衲》引。","）。"]', '诗', 'shi', '', NULL, '句 幸夤遜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df7c80d9-00f1-4425-9b67-c271134c327a', '青城山觀', '青城山观', '61624a76-6732-40f0-9ec1-53a9bd05f375', '唐', '["靜見門庭紫氣生，前山嵐靄入樓青。","玉壇醮罷鬼神喜，金鼎藥成雞犬靈。","巖下水光分五色，壺中人壽過千齡。","何當一日拋凡骨，騎取蒼龍上杳冥。","（《增廣聖宋高僧詩選後集》卷中。","）。"]', '["静见门庭紫氣生，前山嵐靄入楼青。","玉壇醮罷鬼神喜，金鼎藥成雞犬靈。","巖下水光分五色，壺中人壽過千齡。","何當一日拋凡骨，騎取蒼龙上杳冥。","（《增廣聖宋高僧诗選後集》卷中。","）。"]', '诗', 'shi', '', NULL, '青城山觀 曉巒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82ed7b65-a868-4977-b4dd-d3efc3c2012e', '蜀中送人遊廬山', '蜀中送人游廬山', '61624a76-6732-40f0-9ec1-53a9bd05f375', '唐', '["君遊正值芳春月，蜀道千山皆秀發。","溪邊十里五里花，雲上三峯五峯雪。","君上匡山我舊居，松蘿拋擲十矯飾要。","君行試到山前問，山鳥只今相憶撫？","（影印本《詩淵》第六冊第四四四八頁。","）（按：此詩原署「唐僧巒」。","唐詩人名相近者惟僧鸞與曉曉巒二人。","此詩風格不類僧鸞之作，僧鸞又未見入蜀之跡，而曉巒恰爲蜀僧，故暫定爲曉巒作。","）。"]', '["君游正值芳春月，蜀道千山皆秀發。","溪邊十里五里花，云上三峯五峯雪。","君上匡山我旧居，松蘿拋擲十矯飾要。","君行試到山前问，山鸟只今相憶撫？","（影印本《诗淵》第六冊第四四四八頁。","）（按：此诗原署「唐僧巒」。","唐诗人名相近者惟僧鸾與晓晓巒二人。","此诗风格不類僧鸾之作，僧鸾又未见入蜀之跡，而晓巒恰爲蜀僧，故暫定爲晓巒作。","）。"]', '诗', 'shi', '', NULL, '蜀中送人遊廬山 曉巒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2aef0313-bd57-4775-b98c-96cc7d95ade1', '春（題擬）', '春（題擬）', '61624a76-6732-40f0-9ec1-53a9bd05f375', '唐', '["灘潄金沙過枕前，雨絲斜織麯塵煙。","綠楊紅杏宜寒食，紫雁黃鸝聒晝眠。","（見明刻本《錦繡萬花谷前集》卷三。","《古今合璧事類備要前集》卷二錄第二句。","）。"]', '["灘潄金沙過枕前，雨絲斜织麯塵煙。","綠楊紅杏宜寒食，紫雁黄鸝聒晝眠。","（见明刻本《錦繡万花谷前集》卷三。","《古今合璧事類備要前集》卷二錄第二句。","）。"]', '诗', 'shi', '', NULL, '春（題擬） 曉巒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f7d6bab-0a99-4648-b3cd-a504579dc4cd', '隱居（題擬）', '隐居（題擬）', '61624a76-6732-40f0-9ec1-53a9bd05f375', '唐', '["杖履獨遊栽藥圃，琴樓多在釣魚船。","晚來花下敲門者，不是神仙即酒仙。","（見前書卷二五「隱逸」門。","）。"]', '["杖履独游栽藥圃，琴楼多在釣鱼船。","晚来花下敲门者，不是神仙即酒仙。","（见前书卷二五「隐逸」门。","）。"]', '诗', 'shi', '', NULL, '隱居（題擬） 曉巒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('182d8634-634c-4ab8-ab6a-21bdd305bb69', '句', '句', '61624a76-6732-40f0-9ec1-53a9bd05f375', '唐', '["臨水鶴窺行道影，隔雲僧認讀書聲。","（同前。","）。"]', '["臨水鹤窺行道影，隔云僧認读书声。","（同前。","）。"]', '诗', 'shi', '', NULL, '句 曉巒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cdce00e-41d6-4590-9109-4f38789b6b96', '頌石鞏接三平', '頌石鞏接三平', 'e599c81c-f54f-401b-8de7-6bb8789255d8', '唐', '["解擘當胸箭，因何只半人。","爲從途路曉，所以不全身。","（見《景德傳燈錄》卷二十三。","）。"]', '["解擘當胸箭，因何只半人。","爲從途路晓，所以不全身。","（见《景德傳灯錄》卷二十三。","）。"]', '诗', 'shi', '', NULL, '頌石鞏接三平 靈巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f401606-2b12-48b0-aa3b-587783635810', '', '', '7ef559d4-1e4d-4863-a76e-9a2229447af1', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 李堯夫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('177af40c-c43f-45a5-ace7-48881b70055d', '中秋月', '中秋月', '7ef559d4-1e4d-4863-a76e-9a2229447af1', '唐', '["棲禽移晝向空飛，林麓虛明水大肥。","萬國仰瞻當此夕，片雲爭合閉清輝。","羣妖始覺神通小，列宿應慙照耀微。","達曙何人最關念，庾公樓上獨忘機。","（見《古今歲時雜詠》卷三十一。","）。"]', '["棲禽移晝向空飞，林麓虛明水大肥。","万国仰瞻當此夕，片云爭合閉清輝。","羣妖始覺神通小，列宿應慙照耀微。","達曙何人最关念，庾公楼上独忘機。","（见《古今歲时杂詠》卷三十一。","）。"]', '诗', 'shi', '', NULL, '中秋月 李堯夫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53a0a6c6-327c-49c8-ad7f-3de146f6b30d', '題白崖三洞', '題白崖三洞', '7ef559d4-1e4d-4863-a76e-9a2229447af1', '唐', '["嘉州地僻天西南，重疊江山遶城郭。","（見《輿地紀勝》卷一四六《嘉定府》。","）（按：詩末原署：「唐至和三年李堯夫《題白崖三洞》。","」至和爲宋仁宗年號，前五字顯誤。","堯夫爲蜀人，仁宗時未聞有同名者。","）。"]', '["嘉州地僻天西南，重叠江山遶城郭。","（见《輿地紀勝》卷一四六《嘉定府》。","）（按：诗末原署：「唐至和三年李堯夫《題白崖三洞》。","」至和爲宋仁宗年號，前五字显誤。","堯夫爲蜀人，仁宗时未闻有同名者。","）。"]', '诗', 'shi', '', NULL, '題白崖三洞 李堯夫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab7a2414-e203-447b-a340-746801f1378b', '答蜀相李昊', '答蜀相李昊', '7ef559d4-1e4d-4863-a76e-9a2229447af1', '唐', '["甘作堯時夫，不樂蜀中相。","（見《能改齋漫錄》卷五。","）。"]', '["甘作堯时夫，不乐蜀中相。","（见《能改斋漫錄》卷五。","）。"]', '诗', 'shi', '', NULL, '答蜀相李昊 李堯夫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('952bcf85-90e9-4ccd-b486-9cddb1dc8a74', '句 一', '句 一', '7ef559d4-1e4d-4863-a76e-9a2229447af1', '唐', '["水沉爲骨玉爲肌。","（《梅花字字香前集》。","）。"]', '["水沉爲骨玉爲肌。","（《梅花字字香前集》。","）。"]', '诗', 'shi', '', NULL, '句 一 李堯夫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90f0acaa-df36-4505-b1c8-c21a35bf8485', '句 二', '句 二', '7ef559d4-1e4d-4863-a76e-9a2229447af1', '唐', '["羣芳且莫相矜笑。","（《梅花字字香後集》。","）。"]', '["羣芳且莫相矜笑。","（《梅花字字香後集》。","）。"]', '诗', 'shi', '', NULL, '句 二 李堯夫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('173abfcb-ff3e-4366-b31c-9507ab866c17', '碁', '碁', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["碁理還將道理通，爲饒先手却由衰。","古人重到今人愛，萬局都無一局同。","靜算山川千里近，閑銷日月兩輪空。","誠知此道剛難進，況是平生不著功。","（《事文類聚前集》卷四二。","）（按：《韻語陽秋》卷十七引三、四兩句，《全唐詩》卷七六一收入。","）。"]', '["碁理還將道理通，爲饒先手却由衰。","古人重到今人愛，万局都無一局同。","静算山川千里近，闲銷日月兩輪空。","誠知此道剛难進，況是平生不著功。","（《事文類聚前集》卷四二。","）（按：《韻語陽秋》卷十七引三、四兩句，《全唐诗》卷七六一收入。","）。"]', '诗', 'shi', '', NULL, '碁 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a2c8bc3-5831-46ce-9027-bd686eb42bff', '憶鸛詩', '憶鸛诗', 'af132734-2411-4573-87b4-855f1b490562', '唐', '["積雨生殘稻，蒼苔拾舊籠。"]', '["積雨生殘稻，蒼苔拾旧籠。"]', '诗', 'shi', '', NULL, '憶鸛詩 卞震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9dff9e7-c737-4849-92a3-9cc2ae5d1c78', '途中詩', '途中诗', 'af132734-2411-4573-87b4-855f1b490562', '唐', '["風濤秋渡闕，煙雨晚村孤。"]', '["风濤秋渡闕，煙雨晚村孤。"]', '诗', 'shi', '', NULL, '途中詩 卞震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2013b41-2825-499c-a26f-8a1e3ca2bef3', '寄陳摶詩', '寄陳摶诗', 'af132734-2411-4573-87b4-855f1b490562', '唐', '["雙闕暫隨丹詔入，三峰尋與白雲歸。","（按：此二句疑爲震入宋後作。","）。"]', '["雙闕暫隨丹詔入，三峰尋與白云归。","（按：此二句疑爲震入宋後作。","）。"]', '诗', 'shi', '', NULL, '寄陳摶詩 卞震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8c906c7-ea68-4e42-86d0-6ddc349d657b', '東郊詩', '东郊诗', 'af132734-2411-4573-87b4-855f1b490562', '唐', '["芳草又牽爲客恨，白雲空寄未閑心。","（以上均見《吟窗雜錄》卷三十三《歷代吟譜》。","）（〖1〗《吟窗雜錄》軍車田錫序云：「蜀有胡台、李堯夫爲詩人，而卞公之名出其右。","」）。"]', '["芳草又牽爲客恨，白云空寄未闲心。","（以上均见《吟窗杂錄》卷三十三《歷代吟譜》。","）（〖1〗《吟窗杂錄》軍车田錫序云：「蜀有胡台、李堯夫爲诗人，而卞公之名出其右。","」）。"]', '诗', 'shi', '', NULL, '東郊詩 卞震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78cebfb1-a154-408f-a30e-9dce945e21ff', '及第後作（題擬）', '及第後作（題擬）', '84d96b04-d0c6-463e-9ad3-673c6d5fbb16', '唐', '["東堂令史報來時，仙桂云攀第九枝。","乍聽言音猶似夢，却思公道即無疑。","寒門髣髴春將到，幽徑朦朧月漸移。","殘漏聲中鞭馬去，紵袍重戴已相隨。","（見《新編分門古今類事》卷七引李畋《該聞錄》。","）（按：《該聞錄》云觀文「下第後，獻主司《鳳玉賦》，爲時所稱。","」次年試，夢人告以當在榜末及第。","「言訖，院吏報先輩第九人。","是年只放進士九人，果符所夢。","」據所述，當爲唐五代間事。","）。"]', '["东堂令史報来时，仙桂云攀第九枝。","乍听言音猶似梦，却思公道即無疑。","寒门髣髴春將到，幽徑朦朧月漸移。","殘漏声中鞭马去，紵袍重戴已相隨。","（见《新編分门古今類事》卷七引李畋《該闻錄》。","）（按：《該闻錄》云观文「下第後，獻主司《鳳玉賦》，爲时所稱。","」次年試，梦人告以當在榜末及第。","「言訖，院吏報先輩第九人。","是年只放進士九人，果符所梦。","」據所述，當爲唐五代间事。","）。"]', '诗', 'shi', '', NULL, '及第後作（題擬） 于觀文 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e0ab2f1-ad68-41a2-bd5d-71848fddf69d', '石窟寺', '石窟寺', 'c5f17c27-0af5-487a-a421-f0a197dce1ef', '唐', '["老去尋山意漸便，興來登覽獨怡然。","僧歸禪榻香盈帳，人喚漁舟晚濟川。","清洛冷光浮巨棟，靈崧積翠拱中天。","公餘底事頻來此，民遠官刑不用鞭。","（見上海圖書館膠卷複製天一閣藏書靖三十四年康紹第纂《鞏縣志》卷七。","）（按：詩下署：「唐牛承直，鞏縣知縣。","」後錄宋初李淑詩。","同書卷二《職官》載唘知縣：「牛承直，貫無考。","」）。"]', '["老去尋山意漸便，兴来登覽独怡然。","僧归禪榻香盈帳，人喚漁舟晚濟川。","清洛冷光浮巨棟，靈崧積翠拱中天。","公餘底事頻来此，民远官刑不用鞭。","（见上海圖书館膠卷複製天一閣藏书靖三十四年康紹第纂《鞏縣志》卷七。","）（按：诗下署：「唐牛承直，鞏縣知縣。","」後錄宋初李淑诗。","同书卷二《職官》載唘知縣：「牛承直，貫無考。","」）。"]', '诗', 'shi', '', NULL, '石窟寺 牛承直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef0e8fc0-11f8-4539-9dee-6c32f71104a3', '無題', '無題', '808c5ec4-72af-44eb-b196-857f3154ceec', '唐', '["茆屋江山上，夜來夢吳越。","巖溜穿白雲，桂花落明月。","子規啼空山，一聲一滴血。","何事□秋風，出門又離別。","（見《吟窗雜錄》卷二九《歷代吟譜》。","）。"]', '["茆屋江山上，夜来梦吳越。","巖溜穿白云，桂花落明月。","子規啼空山，一声一滴血。","何事□秋风，出门又離別。","（见《吟窗杂錄》卷二九《歷代吟譜》。","）。"]', '诗', 'shi', '', NULL, '無題 王肱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d013a94c-ab06-454b-9746-b7cd0062ea57', '缺題', '缺題', 'dc28df66-3232-48ff-abc5-4510bdc8b849', '唐', '["公族爲良雅，僧堂視事幽。","綱軒疏雨霽，金剎片雲秋。","樹色新蘭若，經聲小比丘。","從來東道意，無見不相留。"]', '["公族爲良雅，僧堂視事幽。","綱軒疏雨霽，金剎片云秋。","樹色新蘭若，經声小比丘。","從来东道意，無见不相留。"]', '诗', 'shi', '', NULL, '缺題 王漸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca31f885-825c-4cb7-9a2b-1c36e2f73f29', '五言同喬父君遊茅溪蘭若一[首]', '五言同喬父君游茅溪蘭若一[首]', 'dc28df66-3232-48ff-abc5-4510bdc8b849', '唐', '["松柏江頭寺，寅緣勝虎谿。","水雲晴過慢，沙鷺[濕]（溫）飛低。","蘭若曾巖抱，旃檀畫閣齊。","褰帷雙樹北，行道一燈留（疑當作「西」字。","）落日催軒騎，秋城限鼓鼙。","臨川興不盡，真賞寄丹梯。","（均見日本藏唐抄本《唐詩卷》。","）。"]', '["松柏江头寺，寅緣勝虎谿。","水云晴過慢，沙鷺[濕]（溫）飞低。","蘭若曾巖抱，旃檀畫閣齊。","褰帷雙樹北，行道一灯留（疑當作「西」字。","）落日催軒騎，秋城限鼓鼙。","臨川兴不尽，真賞寄丹梯。","（均见日本藏唐抄本《唐诗卷》。","）。"]', '诗', 'shi', '', NULL, '五言同喬父君遊茅溪蘭若一[首] 王漸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bade7462-ff30-49d1-90b8-decdcaecd5dd', '隣相反行', '隣相反行', '3498b4d5-2670-493a-8f35-5238068b2e4b', '唐', '["[東]（束）家有兒年十五，只向田園獨辛苦。","夜開溝水遶稻田，曉叱耕牛墾塉土。","西家有兒纔弱齡，儀容清峭雲鶴形。","涉書獵史無早暮，坐期朱紫如拾青。","東家西家兩相誚，西兒笑東到餢笑。","西云養志與榮名，彼此相非不相調。","東家自云雖辛苦，躬耕早暮及所（一作「莫及」）親。","男舂女爨二十載，堂上未爲衰老人。","朝機暮織還充體，餘者到兄還及[弟]（第）。","春秋伏臘長在家，不許妻奴暫違禮。","爾今二十方讀書，十年取第三十餘。","往來途路長離別，幾人夏日得昇公車。","縱令得官（一作「貴」）身須老，銜恤終天向誰道。","百年骨肉歸下泉，萬里槍榆長秋草。","我今躬耕奉所天，耘鋤刈獲當少年。","面上笑添今日喜，肩頭薪續廚中煙。","縱使此身頭雪白，又有兒孫還稼穡。","家藏一卷古《孝經》，世世相傳皆得力。","爲報西家知不知（一作「不」），何須謾笑東家兒。","生前不得供甘滑，歿後揚名徒爾爲。","（見《文苑英華》卷三五○。","）（按：明刻本《文苑英華》收此詩，不署名，前爲薛逢《醉春風》，《全唐詩》卷五四八遂誤收爲薛逢詩。","今據中華書局影印本新編用妻小改正。","）。"]', '["[东]（束）家有兒年十五，只向田园独辛苦。","夜开溝水遶稻田，晓叱耕牛墾塉土。","西家有兒纔弱齡，儀容清峭云鹤形。","涉书獵史無早暮，坐期朱紫如拾青。","东家西家兩相誚，西兒笑东到餢笑。","西云養志與榮名，彼此相非不相調。","东家自云雖辛苦，躬耕早暮及所（一作「莫及」）親。","男舂女爨二十載，堂上未爲衰老人。","朝機暮织還充體，餘者到兄還及[弟]（第）。","春秋伏臘长在家，不許妻奴暫違禮。","爾今二十方读书，十年取第三十餘。","往来途路长離別，幾人夏日得昇公车。","縱令得官（一作「貴」）身須老，銜恤終天向誰道。","百年骨肉归下泉，万里槍榆长秋草。","我今躬耕奉所天，耘鋤刈獲當少年。","面上笑添今日喜，肩头薪續廚中煙。","縱使此身头雪白，又有兒孫還稼穡。","家藏一卷古《孝經》，世世相傳皆得力。","爲報西家知不知（一作「不」），何須謾笑东家兒。","生前不得供甘滑，歿後揚名徒爾爲。","（见《文苑英华》卷三五○。","）（按：明刻本《文苑英华》收此诗，不署名，前爲薛逢《醉春风》，《全唐诗》卷五四八遂誤收爲薛逢诗。","今據中华书局影印本新編用妻小改正。","）。"]', '诗', 'shi', '', NULL, '隣相反行 王國華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c28791b-5663-423d-bbac-b7b22414c638', '感懷', '感懷', '25869133-b4ea-4b0d-a6f8-1cb83bdde46d', '唐', '["仙府寥寥殊未傳，白雲盡日對紗{車□}。","只將（下缺。","見伯三二一六卷。","）（按：伯三二丈六卷存詩五首。","前二首爲李冶《偶居》〖缺題〗和《八至篇》，其後三篇署「女道士元淳」，有總題《寄意五首》，《秦中春望》、《寄洛陽姊妹》二首完整，《全唐詩》已收。","次即本詩，惜已殘缺。","）。"]', '["仙府寥寥殊未傳，白云尽日对紗{车□}。","只將（下缺。","见伯三二一六卷。","）（按：伯三二丈六卷存诗五首。","前二首爲李冶《偶居》〖缺題〗和《八至篇》，其後三篇署「女道士元淳」，有總題《寄意五首》，《秦中春望》、《寄洛陽姊妹》二首完整，《全唐诗》已收。","次即本诗，惜已殘缺。","）。"]', '诗', 'shi', '', NULL, '感懷 元淳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('061a7330-d6d1-4944-8394-41386f4bc79f', '邊上秋望', '邊上秋望', '13a45c3e-5d20-4303-b496-3fba006e91de', '唐', '["草秋宜病馬，風疾稱饑鷹。","（見《吟窗雜錄》卷十四正字王玄《詩中旨格》。","）（按：《唐文拾遺》卷五十據《安陽金石錄》收元昉開元七年作《大唐鄴縣修定寺傳記》。","傳謂其爲「開元中修定寺僧」。","未詳與此詩作者是一人否。","今不取。","）。"]', '["草秋宜病马，风疾稱饑鷹。","（见《吟窗杂錄》卷十四正字王玄《诗中旨格》。","）（按：《唐文拾遺》卷五十據《安陽金石錄》收元昉开元七年作《大唐鄴縣修定寺傳記》。","傳謂其爲「开元中修定寺僧」。","未詳與此诗作者是一人否。","今不取。","）。"]', '诗', 'shi', '', NULL, '邊上秋望 元昉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65e6d5d2-bb56-4b6c-822d-97cd0b5b7051', '石門精室詩', '石门精室诗', '0bb0033b-16fd-4d3c-aacb-07ca5d2e2649', '唐', '["竟養浩氣稽顙（中缺）戲使石門。","（按：光緒元年劉沛纂《零陵縣志》卷十三君華嚴巖皇祐初殘題名云：「地□古刻石得元□□《石門精舍詩》，知其地也。","有竟養浩氣稽顙〖下缺〗戲使石門之稱，與遺跡〖下缺〗其傳。","皇祐乙丑祀明堂日。","」原刻爲政和間人磨去，今僅存殘文。","疑老□□即爲元結。","）。"]', '["竟養浩氣稽顙（中缺）戲使石门。","（按：光緒元年劉沛纂《零陵縣志》卷十三君华嚴巖皇祐初殘題名云：「地□古刻石得元□□《石门精舍诗》，知其地也。","有竟養浩氣稽顙〖下缺〗戲使石门之稱，與遺跡〖下缺〗其傳。","皇祐乙丑祀明堂日。","」原刻爲政和间人磨去，今僅存殘文。","疑老□□即爲元結。","）。"]', '诗', 'shi', '', NULL, '石門精室詩 元□□ shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7833730-854d-41ef-b389-5e38c0b35218', '題孟巖', '題孟巖', '46e579b0-d022-4b70-baa3-2b2c5027a7be', '唐', '["資中多秀異，自古出賢良。","川嶽炳靈氣，煙霞舒瑞光。","家家習詩禮，處處聞絲簧。","（見《輿地紀勝》卷一五七《資州》。","）（按：此詩原題「唐毛熙聖」作，疑即蜀詞人毛熙震之昆從。","）。"]', '["資中多秀異，自古出賢良。","川嶽炳靈氣，煙霞舒瑞光。","家家習诗禮，处处闻絲簧。","（见《輿地紀勝》卷一五七《資州》。","）（按：此诗原題「唐毛熙聖」作，疑即蜀词人毛熙震之昆從。","）。"]', '诗', 'shi', '', NULL, '題孟巖 毛熙聖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd25afdd-3fb1-44a0-be96-01ee1e7ff742', '贈還俗女真（題擬）', '贈還俗女真（題擬）', 'c37dff45-6916-46c0-8a2c-ff25a3818b88', '唐', '["脫却霞裾換（《綠窗新話》作「裙著」）繡裙，仙凡從此路[歧]（岐）（據《綠窗新話》改）分。","蛾眉再畫當時月，蟬鬢重梳舊日雲。","玉貌緩將鸞鏡照，錦衾兼把麝香薰。","屏幃乍得蕭郎愛，更沒心情憶老君。","（見《類說》卷十二《紀異記》《綠窗新話》卷下引《紀異錄》。","）。"]', '["脫却霞裾換（《綠窗新話》作「裙著」）繡裙，仙凡從此路[歧]（岐）（據《綠窗新話》改）分。","蛾眉再畫當时月，蟬鬢重梳旧日云。","玉貌緩將鸾镜照，錦衾兼把麝香薰。","屏幃乍得蕭郎愛，更沒心情憶老君。","（见《類说》卷十二《紀異記》《綠窗新話》卷下引《紀異錄》。","）。"]', '诗', 'shi', '', NULL, '贈還俗女真（題擬） 史君寶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e81cbb20-4bfe-420a-b556-1dd00e691d93', '題伏波廟', '題伏波廟', '8dc1827b-6b8e-41f5-bcbe-5cb89ba235f1', '唐', '["對令班南海，蠻兵避鬱林。","天涯分柱界，徼外貢輸金。","坐失奸臣意，誰明報主恩。","一棺忠勇骨，漂泊瘴煙深。","（見阮崱《安南志略》卷十六。","）。"]', '["对令班南海，蠻兵避鬱林。","天涯分柱界，徼外貢輸金。","坐失奸臣意，誰明報主恩。","一棺忠勇骨，漂泊瘴煙深。","（见阮崱《安南志略》卷十六。","）。"]', '诗', 'shi', '', NULL, '題伏波廟 司馬□ shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5719223-b746-4cb5-a8fc-c427fc3e7a6f', '句', '句', '431a6327-5a33-47cc-bbb4-14593e55fd34', '唐', '["寶劍匣中開似水，娥眉一笑塞雲輕。","（見《吟窗雜錄》卷十三僧虛中《流類手鑑》。","）。"]', '["寶劍匣中开似水，娥眉一笑塞云轻。","（见《吟窗杂錄》卷十三僧虛中《流類手鑑》。","）。"]', '诗', 'shi', '', NULL, '句 江津 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3441667b-7584-4fc1-94cc-321162bae82a', '天池寺', '天池寺', '465ac7e9-1fe5-4550-9f4e-43a149955944', '唐', '["漢王峰上擁樓臺，萬綠陰中石鏡開。","明月和僧窗外立，天風吹鶴日邊來。","一匡翠岫煙霞好，九疊雲屏海嶽魁。","爽氣蕩空塵世少，仙人爲我洗茶杯。","（見嘉靖《九江府志》卷十五。","）。"]', '["漢王峰上擁楼台，万綠陰中石镜开。","明月和僧窗外立，天风吹鹤日邊来。","一匡翠岫煙霞好，九叠云屏海嶽魁。","爽氣蕩空塵世少，仙人爲我洗茶杯。","（见嘉靖《九江府志》卷十五。","）。"]', '诗', 'shi', '', NULL, '天池寺 存初公 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ce11bf7-68f5-4e9b-ae1c-553b858b804b', '', '', '854ce9e9-1da0-483d-a578-050a12cca82d', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 吳翊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c27af81-d649-40bf-ba40-5c49a55d116d', '遊塞 一', '游塞 一', '854ce9e9-1da0-483d-a578-050a12cca82d', '唐', '["此地古今存，何年苦戰頻。"]', '["此地古今存，何年苦戰頻。"]', '诗', 'shi', '', NULL, '遊塞 一 吳翊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f94c43c-4f8e-4e56-9e0f-c8017b0a2746', '遊塞 二', '游塞 二', '854ce9e9-1da0-483d-a578-050a12cca82d', '唐', '["秋燒黃雲黯暮塵。","夜深聞鬼哭，一一是忠臣。"]', '["秋燒黄云黯暮塵。","夜深闻鬼哭，一一是忠臣。"]', '诗', 'shi', '', NULL, '遊塞 二 吳翊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eabbbb8f-ee8d-4083-ad6c-3527edada72c', '征婦詩', '征婦诗', '854ce9e9-1da0-483d-a578-050a12cca82d', '唐', '["塵鑑經春掩，霜衣隔歲裁。","（均見《吟窗雜錄》卷二九《歷代吟譜》。","）。"]', '["塵鑑經春掩，霜衣隔歲裁。","（均见《吟窗杂錄》卷二九《歷代吟譜》。","）。"]', '诗', 'shi', '', NULL, '征婦詩 吳翊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50339d3f-c94a-4cdf-b680-e00bbd9d12f8', '合肥懷古', '合肥懷古', 'b97e8d5d-eda7-420f-8657-caa2eedeabfb', '唐', '["合肥一都會，世號征戰地。","我來值明時，不呅兵戈事。","（見《輿地紀勝》卷四五《廬州》。","）。"]', '["合肥一都會，世號征戰地。","我来值明时，不呅兵戈事。","（见《輿地紀勝》卷四五《廬州》。","）。"]', '诗', 'shi', '', NULL, '合肥懷古 吳資 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98c3f375-82d5-4325-983b-c5cb90eba397', '大桐軍行', '大桐軍行', '4b309575-3cd6-4e49-8582-79c74e83ed1a', '唐', '["驅馬出關城，孤舟邊思盈。","風傳萬里去，目末兩鄉情。","北望單于道，[東臨]（臨東）大武營。","塞闕爍𧣹合，山浮夜泉明。","。"]', '["驱马出关城，孤舟邊思盈。","风傳万里去，目末兩乡情。","北望單于道，[东臨]（臨东）大武營。","塞闕爍𧣹合，山浮夜泉明。","。"]', '诗', 'shi', '', NULL, '大桐軍行 李斌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65a0a60a-e195-4dbe-bde1-4e3e14b45af7', '劍歌 一', '劍歌 一', '4b309575-3cd6-4e49-8582-79c74e83ed1a', '唐', '["我有一長劍，磨來十數年。","但藏玉匣裏，未向代人傳。","鍔露星將轉，珠開月共懸。","霜鋒暎牛斗，雪刃倚長天。","每欲清萬國，常懷定四邊。","希君持取用，方謂識龍泉。"]', '["我有一长劍，磨来十數年。","但藏玉匣裏，未向代人傳。","鍔露星將轉，珠开月共懸。","霜鋒暎牛斗，雪刃倚长天。","每欲清万国，常懷定四邊。","希君持取用，方謂識龙泉。"]', '诗', 'shi', '', NULL, '劍歌 一 李斌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0683a54e-8753-4bc7-b22a-0c5afdadf58a', '劍歌 二', '劍歌 二', '4b309575-3cd6-4e49-8582-79c74e83ed1a', '唐', '["我有夜光寶，自然明月□。","堪●漢祖劍，曾上魏王臺。","五色人難辨，千金匣始開。","不逢天子照，却復度關來。"]', '["我有夜光寶，自然明月□。","堪●漢祖劍，曾上魏王台。","五色人难辨，千金匣始开。","不逢天子照，却复度关来。"]', '诗', 'shi', '', NULL, '劍歌 二 李斌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1897587-960e-4e31-82e7-d326e6d64f10', '日南王', '日南王', '4b309575-3cd6-4e49-8582-79c74e83ed1a', '唐', '["附臣通趙國，奉使拜遼燕。","滄海行無驛，寧知路幾千？","猛風空裏驟，明月浪中懸。","水與天同色，山共白雲連。","隨朝去去遠，未見有歸年。","比來聞漢使，一別似張[騫]（{僭日=心}）。"]', '["附臣通趙国，奉使拜遼燕。","滄海行無驛，寧知路幾千？","猛风空裏驟，明月浪中懸。","水與天同色，山共白云連。","隨朝去去远，未见有归年。","比来闻漢使，一別似張[騫]（{僭日=心}）。"]', '诗', 'shi', '', NULL, '日南王 李斌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba833e5e-d953-479e-9365-1f7c3cd4c23a', '秋渡潁水', '秋渡潁水', '4b309575-3cd6-4e49-8582-79c74e83ed1a', '唐', '["蕩子乘春夜，行歌渡穎川。","雲浮初[蔽]（弊）月，風動乍搖船。","暗水空流響，驚人信莫前。","唯聞靡靡曲，砂上歎□捐。","（均見伯三六一九卷。","）。"]', '["蕩子乘春夜，行歌渡穎川。","云浮初[蔽]（弊）月，风动乍搖船。","暗水空流响，驚人信莫前。","唯闻靡靡曲，砂上歎□捐。","（均见伯三六一九卷。","）。"]', '诗', 'shi', '', NULL, '秋渡潁水 李斌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cb709d7-c584-41b9-84fb-d4e12653ab49', '詠歷溪在歷陽西一里', '詠歷溪在歷陽西一里', '72ffeda4-4554-4ae4-8976-b05081e443da', '唐', '["泠泠一帶清溪水，遠派來通歷陽市。","涓涓出自碧湖中，流入楚江煙霧裏。","（見《錦繡萬花谷續集》卷十。","）（按：《全唐詩》卷七七五收本詩，有缺文，今重錄。","詩題中〖歷溪〗，《全唐詩》作「𣻕溪}。","」）。"]', '["泠泠一带清溪水，远派来通歷陽市。","涓涓出自碧湖中，流入楚江煙霧裏。","（见《錦繡万花谷續集》卷十。","）（按：《全唐诗》卷七七五收本诗，有缺文，今重錄。","诗題中〖歷溪〗，《全唐诗》作「𣻕溪}。","」）。"]', '诗', 'shi', '', NULL, '詠歷溪在歷陽西一里 李聰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43f33a98-7e2d-4b3e-b26b-c21c4216d21d', '法華寺', '法华寺', '7dc6a92b-e3d0-4c36-bc3e-e5f78ba242f2', '唐', '["莓苔又絕壁，薜荔依高林。","（見《嘉泰吳興志》卷二十。","）。"]', '["莓苔又絕壁，薜荔依高林。","（见《嘉泰吳兴志》卷二十。","）。"]', '诗', 'shi', '', NULL, '法華寺 李驛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5a3c05a-9b05-4104-ac3b-e271f72bc857', '龍詩', '龙诗', '305c41cb-7f64-48cb-903c-0fcda3111eb5', '唐', '["上天須致雨，在野即眠雲。","（見《吟窗雜錄》卷十四《詩中旨格》。","《詩學指南》本作「李昌運」。","）。"]', '["上天須致雨，在野即眠云。","（见《吟窗杂錄》卷十四《诗中旨格》。","《诗学指南》本作「李昌運」。","）。"]', '诗', 'shi', '', NULL, '龍詩 李昌遇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0134714-5a21-4147-923a-009cbf83543b', '雞籠山', '雞籠山', '98e46e07-b029-420f-acdf-7c055034e394', '唐', '["山狀雞籠攢翠黛，水通滴瀝落水崖。","誰知內隱神仙宅，金疊雲房玉琢階。","（見《輿地紀勝》卷四八《和州》。","同卷《碑目》云：「唐李思聰《雞籠山》詩，在和州小廳東。","」清趙紹祖《安徽金石略》卷九亦著錄。","）。"]', '["山狀雞籠攢翠黛，水通滴瀝落水崖。","誰知內隐神仙宅，金叠云房玉琢階。","（见《輿地紀勝》卷四八《和州》。","同卷《碑目》云：「唐李思聰《雞籠山》诗，在和州小廳东。","」清趙紹祖《安徽金石略》卷九亦著錄。","）。"]', '诗', 'shi', '', NULL, '雞籠山 李思聰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3714c73f-e525-4d88-9fec-775eb3595d6a', '習家池大堤詩（題擬）', '習家池大堤诗（題擬）', '1ca9f413-9895-4cbf-b247-51b709220261', '唐', '["峴首何人碑，行客獨垂淚。","（見《輿地紀勝》卷八二《襄陽府》。","）。"]', '["峴首何人碑，行客独垂泪。","（见《輿地紀勝》卷八二《襄陽府》。","）。"]', '诗', 'shi', '', NULL, '習家池大堤詩（題擬） 李善美 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b716169-589c-48d0-9b64-15ba5e0f0076', '詠螢', '詠螢', '8d82174f-5e72-48e5-bba7-3ef6cd9e58bc', '唐', '["映水光難定，淩虛體自輕。","夜風吹不滅，秋露洗還明。","向燭仍藏焰，投書更有情。","猶將流亂影，來此傍簷楹。","（據中華書局影印本《文苑英華》卷三二九及該書新編目錄。","）（按：《全唐詩》卷二百六誤收作李嘉祐詩。","）。"]', '["映水光难定，淩虛體自轻。","夜风吹不滅，秋露洗還明。","向燭仍藏焰，投书更有情。","猶將流亂影，来此傍簷楹。","（據中华书局影印本《文苑英华》卷三二九及該书新編目錄。","）（按：《全唐诗》卷二百六誤收作李嘉祐诗。","）。"]', '诗', 'shi', '', NULL, '詠螢 李嘉運 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f48e083-2d7b-409b-b7df-55240426ef1b', '答姬寄詩', '答姬寄诗', '338f44a3-96d5-4e35-a5ff-d81481b4cfce', '唐', '["偶到揚州悔別家，親知留滯不因花。","塵侵寶鏡雖相待，長短歸時上面及瓜。","（見《增修詩話總龜前集》卷二十三引《南部新書》。","）（按：《全唐詩》卷八百一李主簿姬詩小注亦）（引有此詩。","）。"]', '["偶到揚州悔別家，親知留滯不因花。","塵侵寶镜雖相待，长短归时上面及瓜。","（见《增修诗話總龟前集》卷二十三引《南部新书》。","）（按：《全唐诗》卷八百一李主簿姬诗小注亦）（引有此诗。","）。"]', '诗', 'shi', '', NULL, '答姬寄詩 李主簿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b2f7e58-741d-414f-b282-c405e4db0380', '詩', '诗', '4891f0ba-f73e-4b7d-a276-700f9c008c85', '唐', '["却到城中事事傷，惠休歸放賈生亡。","誰人收得章句篋，獨我重經苔蘚房。","一命未沾爲逐客，萬緣初盡別空王。","[□□□□□□□，□□□□□□□]。","（見《吟窗雜錄》卷十四《炙轂子詩格》引。","）。"]', '["却到城中事事傷，惠休归放賈生亡。","誰人收得章句篋，独我重經苔蘚房。","一命未沾爲逐客，万緣初尽別空王。","[□□□□□□□，□□□□□□□]。","（见《吟窗杂錄》卷十四《炙轂子诗格》引。","）。"]', '诗', 'shi', '', NULL, '詩 李端公 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b5c1da9-6c8a-4221-8db0-c326d75e2f0c', '漁父歌滄浪賦附歌 一', '漁父歌滄浪賦附歌 一', '961c603f-1e47-4f3e-97b4-ebf015ea22c8', '唐', '["微風動兮百花塢，扣舷歸兮滿江南。","掛雲帆兮何足數，來濯纓兮滄浪浦。"]', '["微风动兮百花塢，扣舷归兮满江南。","掛云帆兮何足數，来濯纓兮滄浪浦。"]', '诗', 'shi', '', NULL, '漁父歌滄浪賦附歌 一 何蠲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09e503f0-2aaf-4625-a805-f3960d19d9cd', '漁父歌滄浪賦附歌 二', '漁父歌滄浪賦附歌 二', '961c603f-1e47-4f3e-97b4-ebf015ea22c8', '唐', '["泛蓬𦩘戲鳬鷖，澄水暗（一作「鏡」）兮照虹霓。","指塵路兮何足迷，來濯纓兮滄浪溪。","（見伯二四八八、二六二一、二七一二卷，茲從張錫厚校錄本。","）。"]', '["泛蓬𦩘戲鳬鷖，澄水暗（一作「镜」）兮照虹霓。","指塵路兮何足迷，来濯纓兮滄浪溪。","（见伯二四八八、二六二一、二七一二卷，茲從張錫厚校錄本。","）。"]', '诗', 'shi', '', NULL, '漁父歌滄浪賦附歌 二 何蠲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85dc08e8-65c6-4671-89b2-a195ef37ac26', '送鄭[郢]（逞）州', '送鄭[郢]（逞）州', '2231a5eb-c214-446c-a050-979d48b2734b', '唐', '["官從書府拜，吏向武閭迎。","（見《吟窗雜錄》卷二九《歷代吟譜》。","）（按：郁賢皓先生《唐刺史考》卷一九三載鄭姓任郢州刺史者，貞元十年有鄭某，十六年有鄭正則。","）。"]', '["官從书府拜，吏向武閭迎。","（见《吟窗杂錄》卷二九《歷代吟譜》。","）（按：郁賢皓先生《唐刺史考》卷一九三載鄭姓任郢州刺史者，貞元十年有鄭某，十六年有鄭正則。","）。"]', '诗', 'shi', '', NULL, '送鄭[郢]（逞）州 林鐸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f326daab-ef93-4fea-868e-ede4dadb3f79', '登山', '登山', '91eb908b-ce7c-414b-aaab-abcf9346f58d', '唐', '["數歇未到頂，穿雲勢漸孤。","（見《吟窗雜錄》卷十二沙門文彧《詩格》。","）。"]', '["數歇未到頂，穿云勢漸孤。","（见《吟窗杂錄》卷十二沙门文彧《诗格》。","）。"]', '诗', 'shi', '', NULL, '登山 林先輩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('374267c9-72dd-4e94-86e8-de2cda6bdfe4', '桃源（題擬）', '桃源（題擬）', 'b1e6dd54-362c-4942-b09b-01d6a4b761bd', '唐', '["扁舟却下五湖水，勝地重遊八跡壇。","（見《輿地紀勝》卷六八《常德府》。","）。"]', '["扁舟却下五湖水，勝地重游八跡壇。","（见《輿地紀勝》卷六八《常德府》。","）。"]', '诗', 'shi', '', NULL, '桃源（題擬） 孟安序 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a1571ad-998c-4422-bf99-72f284e9a283', '山行書情呈王十四', '山行书情呈王十四', '6478cc0b-80dd-4ed8-b993-05c754f16ce1', '唐', '["悠悠一徑入本來端，艱險千重渡轉難。","澗下厭聽流咽水，巖間愁望古松寒。","風沙終日情迷惑，霜雨侵宵夢不安。","憔悴途中無鏡照，却迴蓬鬢似君看。"]', '["悠悠一徑入本来端，艱險千重渡轉难。","澗下厭听流咽水，巖间愁望古松寒。","风沙終日情迷惑，霜雨侵宵梦不安。","憔悴途中無镜照，却迴蓬鬢似君看。"]', '诗', 'shi', '', NULL, '山行書情呈王十四 武涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2757fac9-03f7-4e3e-a841-b47037cbbc39', '遊花苑詞 一', '游花苑词 一', '6478cc0b-80dd-4ed8-b993-05c754f16ce1', '唐', '["侍女相邀上苑遊，笙歌嘹唳滿花樓。","玉顏自倚君王寵，無處金釵落不收。"]', '["侍女相邀上苑游，笙歌嘹唳满花楼。","玉顏自倚君王寵，無处金釵落不收。"]', '诗', 'shi', '', NULL, '遊花苑詞 一 武涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fd0e20b-0c6a-4575-8d52-61a687f89bc7', '遊花苑詞 二', '游花苑词 二', '6478cc0b-80dd-4ed8-b993-05c754f16ce1', '唐', '["君遊園苑百花新，花下紅妝採白蘋。","競將顏色比花色，花色無情不及人。","（均見伯三八一二卷。","）。"]', '["君游园苑百花新，花下紅妝採白蘋。","競將顏色比花色，花色無情不及人。","（均见伯三八一二卷。","）。"]', '诗', 'shi', '', NULL, '遊花苑詞 二 武涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d9f882d-795b-4e0c-8dc0-df4e80ec5862', '訪李真人', '訪李真人', 'f1235619-9ccb-4510-8be2-92d3d1cea2ed', '唐', '["八十康強鬢未華，琴書圖史是生涯。","是非應不關心慮，名利何曾掛齒牙。","野鶴無心棲道院，巖花流水入仙家。","□□□□□□□，近聞巢許出煙霞。","（見道光《寶慶府志》卷一○三《藝文略四·金石一》。","此詩承陶敏先生錄示。","）（按：《寶慶府志》云此詩刻石在郡南百里高霞山。","李真人名震，顯慶間修真於此，白晝衝舉。","周尚書源過訪留詩，勒碑新甲山仙宅。","萬曆間江涸碑見，獲此詩，泐第七句。","）。"]', '["八十康強鬢未华，琴书圖史是生涯。","是非應不关心慮，名利何曾掛齒牙。","野鹤無心棲道院，巖花流水入仙家。","□□□□□□□，近闻巢許出煙霞。","（见道光《寶慶府志》卷一○三《藝文略四·金石一》。","此诗承陶敏先生錄示。","）（按：《寶慶府志》云此诗刻石在郡南百里高霞山。","李真人名震，显慶间修真於此，白晝衝舉。","周尚书源過訪留诗，勒碑新甲山仙宅。","万曆间江涸碑见，獲此诗，泐第七句。","）。"]', '诗', 'shi', '', NULL, '訪李真人 周源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9663d610-59e1-4aab-ba21-93ba69b880c4', '紅梅', '紅梅', '4f3f957a-93e5-4157-8d50-4362fb4e6538', '唐', '["姑射仙人笑臉開，肯將脂粉涴香腮。","只因悮入桃源洞，惹得春風上面來。","（見《永樂大典》卷二八○九，中華書局影印本第三五冊。","）（按：《粤詩蒐逸》卷二引《連州志》謂濆爲渭弟。","若其言可信，則濆應爲南漢末至宋初入。","惜尚無從證定，姑仍從《全唐詩》收入事迹無考作者。","）。"]', '["姑射仙人笑臉开，肯將脂粉涴香腮。","只因悮入桃源洞，惹得春风上面来。","（见《永乐大典》卷二八○九，中华书局影印本第三五冊。","）（按：《粤诗蒐逸》卷二引《連州志》謂濆爲渭弟。","若其言可信，則濆應爲南漢末至宋初入。","惜尚無從證定，姑仍從《全唐诗》收入事迹無考作者。","）。"]', '诗', 'shi', '', NULL, '紅梅 周濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('881ae13d-036e-47e4-96cf-1c072df0c554', '題古寺', '題古寺', 'f4a6fd0b-90b9-4ff3-8b45-a0be45645eb8', '唐', '["梵林岑寂妙圓通，靈籟無聲起遠鐘。","青鳥夢回天際白，赤鳥翅展海頭紅。","晨光燦燦流殘月，曙色蒼蒼散曉風。","自古洗甚須淨地，何須假榻坐禪空。"]', '["梵林岑寂妙圓通，靈籟無声起远鐘。","青鸟梦回天際白，赤鸟翅展海头紅。","晨光燦燦流殘月，曙色蒼蒼散晓风。","自古洗甚須淨地，何須假榻坐禪空。"]', '诗', 'shi', '', NULL, '題古寺 周如錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b404e5c0-de25-4c39-8dcd-4516264dec20', '月波亭觀書', '月波亭观书', 'f4a6fd0b-90b9-4ff3-8b45-a0be45645eb8', '唐', '["癡兒事未了，山照已啣西。","數曲尋江路，層空步石梯。","棲高得月早，壁峭與天齊。","往矣初寮躅，摩挲舊碣題。","（見上海圖書館藏膠卷複製康熙六年刊蔣士昌纂《永明縣志》卷十二。","）（按：《題古寺》署「唐周如鍉，太守」，《月波亭觀書》署「唐周如錫，刺史」，顯爲一人，然未詳孰是，今並存之。","）。"]', '["癡兒事未了，山照已啣西。","數曲尋江路，層空步石梯。","棲高得月早，壁峭與天齊。","往矣初寮躅，摩挲旧碣題。","（见上海圖书館藏膠卷複製康熙六年刊蔣士昌纂《永明縣志》卷十二。","）（按：《題古寺》署「唐周如鍉，太守」，《月波亭观书》署「唐周如錫，刺史」，显爲一人，然未詳孰是，今並存之。","）。"]', '诗', 'shi', '', NULL, '月波亭觀書 周如錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74ed480d-840f-4ede-939e-9218fb9a5b2b', '題鼎湖山', '題鼎湖山', 'ebdd9fb3-0dcc-40b2-917e-55d888dd1619', '唐', '["紫陽洞府壓青山，白日騎龍去不還。","軒轅丹竈□□識，燒得金丹奉帝顏。","（見《吟窗雜錄》卷四九。","）。"]', '["紫陽洞府壓青山，白日騎龙去不還。","軒轅丹竈□□識，燒得金丹奉帝顏。","（见《吟窗杂錄》卷四九。","）。"]', '诗', 'shi', '', NULL, '題鼎湖山 季仲砥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('597c787a-3626-48b6-bbeb-052c1842ba12', '對雪聯語', '对雪聯語', 'e6bbc890-4a04-4ecd-a003-401f8d4a9696', '唐', '["麪堆金井，誰堆湯餅。","（尚隆之。","）玉滿天山，難刻佩環。","（吳永素。","見馮贄《雲仙雜記》卷五《姑臧記》。","）。"]', '["麪堆金井，誰堆湯餅。","（尚隆之。","）玉满天山，难刻佩环。","（吳永素。","见馮贄《云仙杂記》卷五《姑臧記》。","）。"]', '诗', 'shi', '', NULL, '對雪聯語 尚隆之　吳永素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb578e76-94e8-489a-9de7-aead391471f9', '瀟湘（題擬）', '瀟湘（題擬）', 'ae8569e1-b3a0-4760-baa7-13d6905ba193', '唐', '["川源通漢沔，舟楫下瀟湘。","（見《永樂大典》卷五七七○引《長沙府志》。","）。"]', '["川源通漢沔，舟楫下瀟湘。","（见《永乐大典》卷五七七○引《长沙府志》。","）。"]', '诗', 'shi', '', NULL, '瀟湘（題擬） 范崇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3e0829a-979e-4aaa-b3e8-5372fa6d2262', '句', '句', '169f691b-4a84-424a-b79a-4cdcd655daa3', '唐', '["喬木聳田園，青山亂商鄧。","（見《吟窗雜錄》卷七皎然《詩議》引。","）。"]', '["喬木聳田园，青山亂商鄧。","（见《吟窗杂錄》卷七皎然《诗議》引。","）。"]', '诗', 'shi', '', NULL, '句 范洒心 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17b70a89-e736-4300-b45a-30a1f23cb037', '謝客巖', '謝客巖', '44f86e00-3555-40a7-a698-adcd2de7b751', '唐', '["不見古君子，空餘舊林巒。","翠色媚車馬，爽氣嚴衣冠。","水天（《同治志》作「天水」）影交碧，松竹聲相寒。","（見上海圖書館據天一閣藏本所攝膠卷弘治《溫州府志》卷二十二、同治五年刊齊召南纂《溫州府志》卷四。","）（按：陸心源《宋詩紀事補遺》卷八十八收姚揆此詩。","）。"]', '["不见古君子，空餘旧林巒。","翠色媚车马，爽氣嚴衣冠。","水天（《同治志》作「天水」）影交碧，松竹声相寒。","（见上海圖书館據天一閣藏本所攝膠卷弘治《溫州府志》卷二十二、同治五年刊齊召南纂《溫州府志》卷四。","）（按：陸心源《宋诗紀事補遺》卷八十八收姚揆此诗。","）。"]', '诗', 'shi', '', NULL, '謝客巖 姚揆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e14573b-9d9d-4ca6-9fa9-18b4b9fd0aa1', '句 一', '句 一', '44f86e00-3555-40a7-a698-adcd2de7b751', '唐', '["憐香擘破花心齅。","（史鑄《百菊集譜》卷六集句引。","）。"]', '["怜香擘破花心齅。","（史鑄《百菊集譜》卷六集句引。","）。"]', '诗', 'shi', '', NULL, '句 一 姚揆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fd62a9a-664e-4ea7-9ef8-33065463c8ac', '句 二', '句 二', '44f86e00-3555-40a7-a698-adcd2de7b751', '唐', '["獨上南樓四望賒。","（《江湖小集》卷二十李龏《梅花衲》引。","）。"]', '["独上南楼四望賒。","（《江湖小集》卷二十李龏《梅花衲》引。","）。"]', '诗', 'shi', '', NULL, '句 二 姚揆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a22ff0f6-d1f4-48b8-9fd0-4b5a023eb446', '', '', 'f475841a-e7f2-4620-8411-a5629d4b9ad3', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 姚贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('288a5264-7c9d-4eb5-ac17-6d90ba87a3c2', '八分書歌', '八分书歌', 'f475841a-e7f2-4620-8411-a5629d4b9ad3', '唐', '["吳興姚贊能八分，一點一畫若崩雲。","又如春水綠波紋，上有鵁鶄鸂鶒羣。","（見宋陳思《書苑菁華》卷十七。","）（按：此首似爲他人稱許姚贊詩。","）。"]', '["吳兴姚贊能八分，一点一畫若崩云。","又如春水綠波紋，上有鵁鶄鸂鶒羣。","（见宋陳思《书苑菁华》卷十七。","）（按：此首似爲他人稱許姚贊诗。","）。"]', '诗', 'shi', '', NULL, '八分書歌 姚贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bf8e6d7-b8ab-4eb5-bb95-931a9524e10d', '宿上霄洞居詩', '宿上霄洞居诗', '95ca9601-8a45-45d8-a77a-5428ebe7d53f', '唐', '["一宿煙霞境，更無塵夢侵。","泉聲寒繞枕，山色冷歸衾。","自得希夷性，還忘名利心。","更闌不成寐，巖鳥共寒吟。"]', '["一宿煙霞境，更無塵梦侵。","泉声寒繞枕，山色冷归衾。","自得希夷性，還忘名利心。","更闌不成寐，巖鸟共寒吟。"]', '诗', 'shi', '', NULL, '宿上霄洞居詩 袁吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c34c4766-e19d-409c-a740-039c5f968a63', '宿赤松會仙閣詩', '宿赤松會仙閣诗', '95ca9601-8a45-45d8-a77a-5428ebe7d53f', '唐', '["道分相投氣味長，就中何處最片忘？","芙蓉閣上秋窗下，臥枕泉聲並石牀。","（均見光緒廿年刊鄧鍾玉撰《金華縣志》卷二，次詩又見同書卷五。","）。"]', '["道分相投氣味长，就中何处最片忘？","芙蓉閣上秋窗下，臥枕泉声並石牀。","（均见光緒廿年刊鄧鍾玉撰《金华縣志》卷二，次诗又见同书卷五。","）。"]', '诗', 'shi', '', NULL, '宿赤松會仙閣詩 袁吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0964755-927a-4bfa-a2d5-2fbad3f45711', '贈琴僧', '贈琴僧', 'd006c141-ca7a-4cbc-918c-6d9322c5ea93', '唐', '["不待江上移入座，便開（一作「聞」）三峽水來聲。","（《千載佳句》卷下《宴喜部·琴》。","）（按：《全唐詩逸》卷中錄此詩，缺一字，今重錄。","）。"]', '["不待江上移入座，便开（一作「闻」）三峽水来声。","（《千載佳句》卷下《宴喜部·琴》。","）（按：《全唐诗逸》卷中錄此诗，缺一字，今重錄。","）。"]', '诗', 'shi', '', NULL, '贈琴僧 唐樞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00bb583b-9299-4d91-842c-1fbf05c4458d', '詠千僧釜', '詠千僧釜', 'fb86daf4-384d-4ac0-8ab1-6384edf3c0fc', '唐', '["香積廚空鐵釜存，萬年鼎列鎮山門。","何時再作千僧供，飯罷潮音徹遠村。","（見同治十一年刊黃鳳樓纂《德化縣志》卷四九。","）。"]', '["香積廚空鐵釜存，万年鼎列鎮山门。","何时再作千僧供，飯罷潮音徹远村。","（见同治十一年刊黄鳳楼纂《德化縣志》卷四九。","）。"]', '诗', 'shi', '', NULL, '詠千僧釜 高瀛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('236b4146-b68a-4dc1-877c-955912633385', '一行算法', '一行算法', '17138ac6-4f34-4e28-9abd-0263f2da80cd', '唐', '["一行尋師觸處遊，到天台後始應休。","因知算法通天地，溪水尋常盡逆流。","（見《四庫珍本初集》本《天台集》卷下。","）（按：詩末原跋云：「一行窮大衍算法，求訪師資不遠千里。","嘗至天台國清寺，見一院古松，門有流水。","一行立於門屏，聞僧於庭前布算之聲，謂其徒曰：『今日當有弟子自遠來，求吾算法，已合在門，豈無人導達耶？","』即除一算，謂）（曰：『門前水合却西去，弟子當至。","』一行聞其言而入，稽首請法，授其術，而門外舊東流水，忽改而西流矣。","」《冊府元龜》卷八六九《總錄部·明算》所記，與上文大致相同。","）。"]', '["一行尋師觸处游，到天台後始應休。","因知算法通天地，溪水尋常尽逆流。","（见《四庫珍本初集》本《天台集》卷下。","）（按：诗末原跋云：「一行窮大衍算法，求訪師資不远千里。","嘗至天台国清寺，见一院古松，门有流水。","一行立於门屏，闻僧於庭前布算之声，謂其徒曰：『今日當有弟子自远来，求吾算法，已合在门，豈無人導達耶？","』即除一算，謂）（曰：『门前水合却西去，弟子當至。","』一行闻其言而入，稽首請法，授其術，而门外旧东流水，忽改而西流矣。","」《冊府元龟》卷八六九《總錄部·明算》所記，與上文大致相同。","）。"]', '诗', 'shi', '', NULL, '一行算法 孫誧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('389f23f4-04e8-4d61-98d4-b1d6201f8fd3', '', '', '4d1454b1-2c2e-45f9-8157-a406c832d18c', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 孫宗閔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec5e2249-dc9c-42a7-a6d9-141d9ebd59c6', '愷悌詩（幷序） 澄俗二章（章十句）', '愷悌诗（幷序） 澄俗二章（章十句）', '4d1454b1-2c2e-45f9-8157-a406c832d18c', '唐', '["（上缺）物有方。","口含大憲，手提國綱。","實邦之翰，爲民之防。","宵沉狺吠，晨無飲羊。","千古是仰，昭其耿光。","（按：此詩題稱二章，僅存後章，前章已失去。","）。"]', '["（上缺）物有方。","口含大憲，手提国綱。","實邦之翰，爲民之防。","宵沉狺吠，晨無饮羊。","千古是仰，昭其耿光。","（按：此诗題稱二章，僅存後章，前章已失去。","）。"]', '诗', 'shi', '', NULL, '愷悌詩（幷序） 澄俗二章（章十句） 孫宗閔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9802a89a-ca16-46b0-b874-98bb891f282d', '愷悌詩（幷序） 心如水兮二章（一章十句，一章八句）（心如水兮，志尚清潔矣。） 一', '愷悌诗（幷序） 心如水兮二章（一章十句，一章八句）（心如水兮，志尚清潔矣。） 一', '4d1454b1-2c2e-45f9-8157-a406c832d18c', '唐', '["我公之心，含淵濬潔。","挹之彌沖，酌而莫竭。","靈府汪洋，璇源瑩徹。","若鑑之明，如井之洌。","利物至柔，漱芳瀰潏。","。"]', '["我公之心，含淵濬潔。","挹之彌沖，酌而莫竭。","靈府汪洋，璇源瑩徹。","若鑑之明，如井之洌。","利物至柔，漱芳瀰潏。","。"]', '诗', 'shi', '', NULL, '愷悌詩（幷序） 心如水兮二章（一章十句，一章八句）（心如水兮，志尚清潔矣。） 一 孫宗閔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb802476-bbd8-46a2-b4c5-0bb13d10cbf3', '愷悌詩（幷序） 心如水兮二章（一章十句，一章八句）（心如水兮，志尚清潔矣。） 二', '愷悌诗（幷序） 心如水兮二章（一章十句，一章八句）（心如水兮，志尚清潔矣。） 二', '4d1454b1-2c2e-45f9-8157-a406c832d18c', '唐', '["行業滋茂，言泉洞開。","浸仁沐義，津賢育材。","潤無不灑，清而不回。","叔度之頃，公何遠哉。"]', '["行業滋茂，言泉洞开。","浸仁沐義，津賢育材。","潤無不灑，清而不回。","叔度之頃，公何远哉。"]', '诗', 'shi', '', NULL, '愷悌詩（幷序） 心如水兮二章（一章十句，一章八句）（心如水兮，志尚清潔矣。） 二 孫宗閔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33d22107-79da-40b8-8618-2442712998aa', '愷悌詩（幷序） 惠風二章（一章十二句，一章八句）（惠風，民被賜也。） 一', '愷悌诗（幷序） 惠风二章（一章十二句，一章八句）（惠风，民被賜也。） 一', '4d1454b1-2c2e-45f9-8157-a406c832d18c', '唐', '["習習惠風，施於千里。","吹淡民心，洽茲仁理。","動必響臻，應如草靡。","泠泠四馳，飄飄中起。","利物厚生，條綱振紀。","鼓音塤箎，發馨蘭芷。"]', '["習習惠风，施於千里。","吹淡民心，洽茲仁理。","动必响臻，應如草靡。","泠泠四驰，飄飄中起。","利物厚生，條綱振紀。","鼓音塤箎，發馨蘭芷。"]', '诗', 'shi', '', NULL, '愷悌詩（幷序） 惠風二章（一章十二句，一章八句）（惠風，民被賜也。） 一 孫宗閔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('113ce3cd-7c91-4888-84fe-8815014d15b9', '愷悌詩（幷序） 惠風二章（一章十二句，一章八句）（惠風，民被賜也。） 二', '愷悌诗（幷序） 惠风二章（一章十二句，一章八句）（惠风，民被賜也。） 二', '4d1454b1-2c2e-45f9-8157-a406c832d18c', '唐', '["獵野班春，蘇萌潤坼。","騰茂英英，揚光赫赫。","福介羣黎，歡飛廣陌。","敢繼周詩，式歌召伯。"]', '["獵野班春，蘇萌潤坼。","腾茂英英，揚光赫赫。","福介羣黎，歡飞廣陌。","敢繼周诗，式歌召伯。"]', '诗', 'shi', '', NULL, '愷悌詩（幷序） 惠風二章（一章十二句，一章八句）（惠風，民被賜也。） 二 孫宗閔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17807d01-db27-47d3-9bb2-95b5ccb50ac6', '愷悌詩（幷序） 慎獨二章（一章十句，一章八句）（慎獨，閉邪存其誠也。） 一', '愷悌诗（幷序） 慎独二章（一章十句，一章八句）（慎独，閉邪存其誠也。） 一', '4d1454b1-2c2e-45f9-8157-a406c832d18c', '唐', '["恐懼不覩，誡慎不聞。","我公慎獨，於斯洞分。","微既莫顯，隱何可云？","溫樹奚問，諫草自焚。","克謹天戒，允符帝文。"]', '["恐懼不覩，誡慎不闻。","我公慎独，於斯洞分。","微既莫显，隐何可云？","溫樹奚问，諫草自焚。","克謹天戒，允符帝文。"]', '诗', 'shi', '', NULL, '愷悌詩（幷序） 慎獨二章（一章十句，一章八句）（慎獨，閉邪存其誠也。） 一 孫宗閔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48260b00-a975-4116-95fc-06295f73d3c6', '愷悌詩（幷序） 慎獨二章（一章十句，一章八句）（慎獨，閉邪存其誠也。） 二', '愷悌诗（幷序） 慎独二章（一章十句，一章八句）（慎独，閉邪存其誠也。） 二', '4d1454b1-2c2e-45f9-8157-a406c832d18c', '唐', '["仲舒格言，許緒深旨。","靈懷發中，神資素履。","吻契洵猷，踐揚前軌。","藹藹令名，爛光青史。"]', '["仲舒格言，許緒深旨。","靈懷發中，神資素履。","吻契洵猷，踐揚前軌。","藹藹令名，爛光青史。"]', '诗', 'shi', '', NULL, '愷悌詩（幷序） 慎獨二章（一章十句，一章八句）（慎獨，閉邪存其誠也。） 二 孫宗閔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c762bf41-b389-4160-ade0-cd7101d5f02c', '愷悌詩（幷序） 良哉二章（一章十句，一章十二句）（良哉，協帝賚也。） 一', '愷悌诗（幷序） 良哉二章（一章十句，一章十二句）（良哉，協帝賚也。） 一', '4d1454b1-2c2e-45f9-8157-a406c832d18c', '唐', '["巨望彌聳，其德不回。","乃眷西顧，賚公賢才。","帝曰欽往，時稱良哉。","乃邦之彥，實民之懷。","飛榮驪闕，進秩蘭臺。","。"]', '["巨望彌聳，其德不回。","乃眷西顧，賚公賢才。","帝曰欽往，时稱良哉。","乃邦之彥，實民之懷。","飞榮驪闕，進秩蘭台。","。"]', '诗', 'shi', '', NULL, '愷悌詩（幷序） 良哉二章（一章十句，一章十二句）（良哉，協帝賚也。） 一 孫宗閔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a8d9fb5-e27c-4909-a514-1c000b9a73a0', '愷悌詩（幷序） 良哉二章（一章十句，一章十二句）（良哉，協帝賚也。） 二', '愷悌诗（幷序） 良哉二章（一章十句，一章十二句）（良哉，協帝賚也。） 二', '4d1454b1-2c2e-45f9-8157-a406c832d18c', '唐', '["銅虎分符，朱藩戒路。","棠郊去思，潼江來暮。","恂恂德心，汪汪軌度。","寬不容姧，直上不抵忤。","煌煌發輝，綽綽垂裕。","翊彼天聰，克昌景祚。"]', '["銅虎分符，朱藩戒路。","棠郊去思，潼江来暮。","恂恂德心，汪汪軌度。","寬不容姧，直上不抵忤。","煌煌發輝，綽綽垂裕。","翊彼天聰，克昌景祚。"]', '诗', 'shi', '', NULL, '愷悌詩（幷序） 良哉二章（一章十句，一章十二句）（良哉，協帝賚也。） 二 孫宗閔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc240408-a909-4a67-9e77-20a9609b3af7', '愷悌詩（幷序） 宜兮一章（二十句）（宜兮，洽民心也。）', '愷悌诗（幷序） 宜兮一章（二十句）（宜兮，洽民心也。）', '4d1454b1-2c2e-45f9-8157-a406c832d18c', '唐', '["啟藩斯境，民之宜兮。","令必響赴，動而悅隨。","濬明宣哲，淑慎經彝。","善化郁郁，羣心披披。","我有惸獨，公則安之，我有弟子，公則教之。","匪民之宜，實德之基，實邦之基。","帝典昭灼，王度清夷。","說命將舉，慰茲羣黎。"]', '["啟藩斯境，民之宜兮。","令必响赴，动而悅隨。","濬明宣哲，淑慎經彝。","善化郁郁，羣心披披。","我有惸独，公則安之，我有弟子，公則教之。","匪民之宜，實德之基，實邦之基。","帝典昭灼，王度清夷。","说命將舉，慰茲羣黎。"]', '诗', 'shi', '', NULL, '愷悌詩（幷序） 宜兮一章（二十句）（宜兮，洽民心也。） 孫宗閔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3102b1e9-813a-429b-a5e4-6b164d71dd95', '愷悌詩（幷序） 里無歎兮二章（一章十二句，一章□句）（里無歎兮，洽頌聲也。） 一', '愷悌诗（幷序） 里無歎兮二章（一章十二句，一章□句）（里無歎兮，洽頌声也。） 一', '4d1454b1-2c2e-45f9-8157-a406c832d18c', '唐', '["公之來矣，里無歎兮。","清猷濬發，輿頌爭馳。","仁聲旁達，廉風□□。","□白攜手，其樂如之。","流轉保業，其心歸心。","□不□響，耕無隨時。"]', '["公之来矣，里無歎兮。","清猷濬發，輿頌爭驰。","仁声旁達，廉风□□。","□白携手，其乐如之。","流轉保業，其心归心。","□不□响，耕無隨时。"]', '诗', 'shi', '', NULL, '愷悌詩（幷序） 里無歎兮二章（一章十二句，一章□句）（里無歎兮，洽頌聲也。） 一 孫宗閔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6810983b-7d29-4c30-8651-1aaa96d8dced', '愷悌詩（幷序） 里無歎兮二章（一章十二句，一章□句）（里無歎兮，洽頌聲也。） 二', '愷悌诗（幷序） 里無歎兮二章（一章十二句，一章□句）（里無歎兮，洽頌声也。） 二', '4d1454b1-2c2e-45f9-8157-a406c832d18c', '唐', '["連衽架肩，途歌巷詠。","邵杜宣慈，（下缺）庭，永膺休命。"]', '["連衽架肩，途歌巷詠。","邵杜宣慈，（下缺）庭，永膺休命。"]', '诗', 'shi', '', NULL, '愷悌詩（幷序） 里無歎兮二章（一章十二句，一章□句）（里無歎兮，洽頌聲也。） 二 孫宗閔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb5787d3-43cc-46c9-b2b5-0b591c651388', '愷悌詩（幷序） 翼翼謹心二章（一章十二句，[一章□句]）（翼翼謹心，蒞事也。） 一', '愷悌诗（幷序） 翼翼謹心二章（一章十二句，[一章□句]）（翼翼謹心，蒞事也。） 一', '4d1454b1-2c2e-45f9-8157-a406c832d18c', '唐', '["克己溫溫，秉心翼翼。","靜以保（下缺）融，沉誦淵塞。","言必再思，動不過則。","（下缺）。"]', '["克己溫溫，秉心翼翼。","静以保（下缺）融，沉誦淵塞。","言必再思，动不過則。","（下缺）。"]', '诗', 'shi', '', NULL, '愷悌詩（幷序） 翼翼謹心二章（一章十二句，[一章□句]）（翼翼謹心，蒞事也。） 一 孫宗閔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f98b709-3a17-4052-9511-aedd7cf0a6d3', '愷悌詩（幷序） 翼翼謹心二章（一章十二句，[一章□句]）（翼翼謹心，蒞事也。） 二', '愷悌诗（幷序） 翼翼謹心二章（一章十二句，[一章□句]）（翼翼謹心，蒞事也。） 二', '4d1454b1-2c2e-45f9-8157-a406c832d18c', '唐', '["（上缺）陽，輝光日新。","兢莊率清，純操持（下缺）誦坐，永昭臣鄰。","。"]', '["（上缺）陽，輝光日新。","兢莊率清，純操持（下缺）誦坐，永昭臣鄰。","。"]', '诗', 'shi', '', NULL, '愷悌詩（幷序） 翼翼謹心二章（一章十二句，[一章□句]）（翼翼謹心，蒞事也。） 二 孫宗閔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa79c5a4-ecf7-482f-ac2d-2fb9bb424703', '愷悌詩（幷序） 千里蒸蒸二章（十句）', '愷悌诗（幷序） 千里蒸蒸二章（十句）', '4d1454b1-2c2e-45f9-8157-a406c832d18c', '唐', '["（上缺）教里閭勃興遠是効敦□崇德（下缺）心因，慕之慎□。","□紀敦淡，黎庶咸歸。","（下缺）公之（下缺）（按：此詩二章，因殘泐已無從分析，姑連錄。","）。"]', '["（上缺）教里閭勃兴远是効敦□崇德（下缺）心因，慕之慎□。","□紀敦淡，黎庶咸归。","（下缺）公之（下缺）（按：此诗二章，因殘泐已無從分析，姑連錄。","）。"]', '诗', 'shi', '', NULL, '愷悌詩（幷序） 千里蒸蒸二章（十句） 孫宗閔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae5dd790-ea99-47f7-a0ae-a9dea47d61e2', '愷悌詩（幷序） 慎□（詩缺）（慎□，無枉也。）', '愷悌诗（幷序） 慎□（诗缺）（慎□，無枉也。）', '4d1454b1-2c2e-45f9-8157-a406c832d18c', '唐', '["空（按：以上組詩及序，皆錄自光緒《潼川府志》卷九、民國《三臺縣志》卷二十一。","《三臺縣志》云：此詩石刻爲正書小楷，首題前進士孫宗閔撰，舊存文廟《干祿碑》側，民國初毀於兵。","）。"]', '["空（按：以上組诗及序，皆錄自光緒《潼川府志》卷九、民国《三台縣志》卷二十一。","《三台縣志》云：此诗石刻爲正书小楷，首題前進士孫宗閔撰，旧存文廟《干祿碑》側，民国初毀於兵。","）。"]', '诗', 'shi', '', NULL, '愷悌詩（幷序） 慎□（詩缺）（慎□，無枉也。） 孫宗閔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e1ff6a5-1a36-494f-a136-cd6397b18d87', '句', '句', 'fec197c1-150b-4862-9e6e-1d0d2ae49cca', '唐', '["晴望東溟小，夜觀南斗長。","（見《吟窗雜錄》卷十三王夢簡《進士王氏詩要格律》。","）。"]', '["晴望东溟小，夜观南斗长。","（见《吟窗杂錄》卷十三王梦簡《進士王氏诗要格律》。","）。"]', '诗', 'shi', '', NULL, '句 康道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cff38349-7d80-4e8c-8073-fbaba1c81805', '詠屏風', '詠屏风', '42fec2b2-d891-406d-84c3-fd6d23bd679a', '唐', '["映花謝上辨色，隔樹不分香。","（見《後村大全集》卷一七七《詩話續集》引李康成《玉臺後集》。","）。"]', '["映花謝上辨色，隔樹不分香。","（见《後村大全集》卷一七七《诗話續集》引李康成《玉台後集》。","）。"]', '诗', 'shi', '', NULL, '詠屏風 晁祖道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('543a4d9d-b27d-4eba-9c40-52a3bd6bd691', '支硎（題擬）', '支硎（題擬）', '77e4b3c5-ed55-42e7-9df9-a7df73be6d3a', '唐', '["挈過太湖風，投宿支硎月。","（見《輿地紀勝》卷五《平江府》。","）。"]', '["挈過太湖风，投宿支硎月。","（见《輿地紀勝》卷五《平江府》。","）。"]', '诗', 'shi', '', NULL, '支硎（題擬） 徐矩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('406e026a-8de9-4594-aded-116c58a97d93', '閑遊賦附長歌', '闲游賦附长歌', '1b2bc94c-7dce-408d-bb95-0b37dc1ac4f0', '唐', '["上幽岫兮得所欽，山蔬塵兮桂酒斟，嗟草木兮洛（疑）春心，悼日月兮遊（疑）相尋，貴龍鳳兮就高深，悅張邴兮託蕭森。","（見《文苑英華》卷一二七。","）。"]', '["上幽岫兮得所欽，山蔬塵兮桂酒斟，嗟草木兮洛（疑）春心，悼日月兮游（疑）相尋，貴龙鳳兮就高深，悅張邴兮託蕭森。","（见《文苑英华》卷一二七。","）。"]', '诗', 'shi', '', NULL, '閑遊賦附長歌 徐魁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47caf6ea-1d0a-47ff-9cb4-18ff83ae1c0d', '句 一', '句 一', 'f5ff52f6-ede8-48c8-aeb2-e388f07eba25', '唐', '["含情欲語淚雙雙。","（胡偉《宮詞》。","）。"]', '["含情欲語泪雙雙。","（胡偉《宮词》。","）。"]', '诗', 'shi', '', NULL, '句 一 梁瓊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('809ca776-b1df-4de6-a971-b2884bc106bd', '句 二', '句 二', 'f5ff52f6-ede8-48c8-aeb2-e388f07eba25', '唐', '["春過門前爭得知。","（同前。","）。"]', '["春過门前爭得知。","（同前。","）。"]', '诗', 'shi', '', NULL, '句 二 梁瓊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e693059a-7bf8-448d-a01b-0c88ae0d396c', '句 三', '句 三', 'f5ff52f6-ede8-48c8-aeb2-e388f07eba25', '唐', '["飛燕不知腸欲斷。","（同前。","）。"]', '["飞燕不知腸欲斷。","（同前。","）。"]', '诗', 'shi', '', NULL, '句 三 梁瓊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98db162a-df43-40c9-8944-debb7469bc85', '題詩枕屏', '題诗枕屏', '98ff1fd8-01a6-4931-ba27-1c86574ef67e', '唐', '["兩意而今惜別離，焚香發願告神祇。","一條綵索雙雙掛，願學千年連理枝。","（見《綠窗新話》卷上引《南楚新聞》）（按：今本《南楚新聞》無此條。","或疑爲宋人僞託。","）。"]', '["兩意而今惜別離，焚香發願告神祇。","一條綵索雙雙掛，願学千年連理枝。","（见《綠窗新話》卷上引《南楚新闻》）（按：今本《南楚新闻》無此條。","或疑爲宋人僞託。","）。"]', '诗', 'shi', '', NULL, '題詩枕屏 章導 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34088553-d111-4cbd-8e22-a341f010f979', '被召過少室', '被召過少室', '77320534-1eb5-4a37-ad91-b9ed1b0073d0', '唐', '["老病無堪合退休，伊川久已得莬裘。","如今又上長安道，好被青山笑白頭。","（見道光十八年刊馬九功等纂《伊陽縣志》卷六）。"]', '["老病無堪合退休，伊川久已得莬裘。","如今又上长安道，好被青山笑白头。","（见道光十八年刊马九功等纂《伊陽縣志》卷六）。"]', '诗', 'shi', '', NULL, '被召過少室 許古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33fe4526-7ce5-44d8-8387-196ddd8fd390', '雨霽', '雨霽', '8593dd0e-cc93-4f32-be3e-b7f862685ad6', '唐', '["風捲亂雲散，天懸暖日明。","（見《吟窗雜錄》卷十四正字王玄《詩中旨格》）。"]', '["风捲亂云散，天懸暖日明。","（见《吟窗杂錄》卷十四正字王玄《诗中旨格》）。"]', '诗', 'shi', '', NULL, '雨霽 許晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4934457-c484-4faf-b01b-187ae731aea3', '教子詩', '教子诗', '34d687f0-9321-4a53-9643-aeff87fbbd78', '唐', '["我本世胄深宮質，下嫁祝門婦道執，汝父從戎干戈戢，命我避難江郎入。","下撫雙郎時訓飭，上侍老祖年九十。","念汝生父喪原隰，生死茫茫不相及。","人生勵志應早立，汝宜經史勤時習。","莫負我身親炊汲，汝父汝祖各飲泣。","（見同治十二年刊王彬等纂《江山縣志》卷十一）。"]', '["我本世胄深宮質，下嫁祝门婦道執，汝父從戎干戈戢，命我避难江郎入。","下撫雙郎时訓飭，上侍老祖年九十。","念汝生父喪原隰，生死茫茫不相及。","人生勵志應早立，汝宜經史勤时習。","莫負我身親炊汲，汝父汝祖各饮泣。","（见同治十二年刊王彬等纂《江山縣志》卷十一）。"]', '诗', 'shi', '', NULL, '教子詩 淑徳郡主 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('680d2dd5-d94b-4513-8265-f68caa65f02a', '感懷', '感懷', '6b4ad935-0287-43c8-8cbf-327309f402eb', '唐', '["年年人自老，日日水東流。"]', '["年年人自老，日日水东流。"]', '诗', 'shi', '', NULL, '感懷 張琰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d195dad-f9ee-4cb8-872b-ef034a05431b', '春詞', '春词', '6b4ad935-0287-43c8-8cbf-327309f402eb', '唐', '["庭芳自搖落，永念結中腸。","（見《吟窗雜錄》卷三十《古今才婦》。","）（按：《全唐詩》卷八百一卷收四句，缺題，故重錄之。","）。"]', '["庭芳自搖落，永念結中腸。","（见《吟窗杂錄》卷三十《古今才婦》。","）（按：《全唐诗》卷八百一卷收四句，缺題，故重錄之。","）。"]', '诗', 'shi', '', NULL, '春詞 張琰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94945286-13de-45f8-aea4-83c8a122ac35', '與三人鼎坐吟（題擬）', '與三人鼎坐吟（題擬）', '4b99ae78-9a9c-4099-9eea-86b1a2790cd1', '唐', '["三人鐺脚坐，一夜掉頭吟。"]', '["三人鐺脚坐，一夜掉头吟。"]', '诗', 'shi', '', NULL, '與三人鼎坐吟（題擬） 張傑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99f5523c-64e7-41a0-8736-2c3927f78cfa', '句', '句', '4b99ae78-9a9c-4099-9eea-86b1a2790cd1', '唐', '["皁角樹頭懸拍板，葫蘆架上釣茶鎚。","（見曾慥《類說》卷五四王仁裕《玉堂閑話》。","）（〖1〗《玉堂閑話》：「張傑滑稽，能爲假對。","嘗與三人鼎坐，吟曰〖略〗。","又曰〖略〗。","嘗取怒一武弁，傑曰：『大夫既欲行拳，小子不甚憂惕。","』」）。"]', '["皁角樹头懸拍板，葫蘆架上釣茶鎚。","（见曾慥《類说》卷五四王仁裕《玉堂闲話》。","）（〖1〗《玉堂闲話》：「張傑滑稽，能爲假对。","嘗與三人鼎坐，吟曰〖略〗。","又曰〖略〗。","嘗取怒一武弁，傑曰：『大夫既欲行拳，小子不甚憂惕。","』」）。"]', '诗', 'shi', '', NULL, '句 張傑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5388b9aa-e385-47b0-af34-7989e188d221', '無弦琴賦附歌', '無弦琴賦附歌', '2d49b036-38a9-458c-ad3a-6c5ba0c98bb1', '唐', '["樂無聲兮情逾倍，琴無弦兮意彌在。","天地同和有真宰，形聲何爲疊相待。","（見《文苑英華》卷七七。","）。"]', '["乐無声兮情逾倍，琴無弦兮意彌在。","天地同和有真宰，形声何爲叠相待。","（见《文苑英华》卷七七。","）。"]', '诗', 'shi', '', NULL, '無弦琴賦附歌 張隨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc910c77-8540-44ac-9bdd-f4b72e052125', '柘枝舞（題擬）', '柘枝舞（題擬）', '584d0df2-543e-40ec-aa5a-6776b3add6a0', '唐', '["白雪慢回拋舊態，黃鶯驕囀唱新詞。","（見《韻語陽秋》卷十五）。"]', '["白雪慢回拋旧態，黄鶯驕囀唱新词。","（见《韻語陽秋》卷十五）。"]', '诗', 'shi', '', NULL, '柘枝舞（題擬） 張承福 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7a9af08-092b-4e1b-9009-6c9cff1be245', '露賦附歌', '露賦附歌', '4663ae97-62f1-496e-9769-16b0fceff2ab', '唐', '["天降氣兮地凝精，皇德茂兮芝蓋平。","金盤漬兮玉盃清，葉有露兮落有聲。","遼東之鶴中夜驚，日南之雞淩晨鳴。","華山栢兮多珠露，松子服之得長生。","（見《文苑英華》卷十五）。"]', '["天降氣兮地凝精，皇德茂兮芝蓋平。","金盤漬兮玉盃清，葉有露兮落有声。","遼东之鹤中夜驚，日南之雞淩晨鳴。","华山栢兮多珠露，松子服之得长生。","（见《文苑英华》卷十五）。"]', '诗', 'shi', '', NULL, '露賦附歌 張彥勝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8794138-808f-4fe4-a0ee-476820a44a09', '句', '句', '4b2f28d3-72d6-48cc-93a8-3cf3c3d81fe4', '唐', '["雨裏落帆遊謝鄉，寒聲古木共荒涼。","（見高似孫《剡錄》卷四）。"]', '["雨裏落帆游謝乡，寒声古木共荒涼。","（见高似孫《剡錄》卷四）。"]', '诗', 'shi', '', NULL, '句 陳充 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('262c3ac9-aa58-4496-81de-a4284e946a0a', '以剡牋贈陳待詔', '以剡牋贈陳待詔', '43229b8a-fdae-4102-9914-15d582ca5a0e', '唐', '["雲母光籠玉杵溫，得來原自剡溪濆。","清含天姥嶺頭雪，潤帶金庭谷口雲。","九萬未充王內史，百番聊贈杜參軍。","從知醉裏縱橫墨，不到羊欣練白裙。","（見同治九年刊蔡以瑺纂《嵊縣志》卷二十八）。"]', '["云母光籠玉杵溫，得来原自剡溪濆。","清含天姥嶺头雪，潤带金庭谷口云。","九万未充王內史，百番聊贈杜參軍。","從知醉裏縱橫墨，不到羊欣練白裙。","（见同治九年刊蔡以瑺纂《嵊縣志》卷二十八）。"]', '诗', 'shi', '', NULL, '以剡牋贈陳待詔 陳端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eed72f85-f724-4f68-9eac-04efd6999fc4', '句', '句', 'e411af75-dc97-44e0-8e7c-096070748ad9', '唐', '["巴益千山翠，潭衡一水通。","（見《輿地紀勝》卷六九《岳州》）。"]', '["巴益千山翠，潭衡一水通。","（见《輿地紀勝》卷六九《岳州》）。"]', '诗', 'shi', '', NULL, '句 陳嘉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b22fd9f-6276-497a-a9ce-f4da2e95963c', '詠海潮詩', '詠海潮诗', '0767be3c-4a5e-433c-9560-dc0ea7ce561b', '唐', '["百谷朝宗處，朝昏洶湧時。","未嘗聞失信，不省與誰期。","落勢分江島，來聲震海涯。","魚龍爭會合，鷗鷺競相隨。","卷釣人眠待，貪程客恠遲。","幸通蓬閼路，孤櫂去何疑。","（見《吟窗雜錄》卷二九《歷代吟譜》）。"]', '["百谷朝宗处，朝昏洶湧时。","未嘗闻失信，不省與誰期。","落勢分江島，来声震海涯。","鱼龙爭會合，鷗鷺競相隨。","卷釣人眠待，貪程客恠遲。","幸通蓬閼路，孤櫂去何疑。","（见《吟窗杂錄》卷二九《歷代吟譜》）。"]', '诗', 'shi', '', NULL, '詠海潮詩 陳文弼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71e80491-d7cd-44ef-bca0-ac9b77521b80', '', '', '7356e51b-a0d3-4fb5-977a-3552032f637b', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 陳從道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42e7f3ac-b472-4bb3-a53c-1285ee46a9ae', '詠扇詩', '詠扇诗', '7356e51b-a0d3-4fb5-977a-3552032f637b', '唐', '["況有明年三伏在，秋風能占幾多時。","（見《吟窗雜錄》卷二九《歷代吟譜》）。"]', '["況有明年三伏在，秋风能占幾多时。","（见《吟窗杂錄》卷二九《歷代吟譜》）。"]', '诗', 'shi', '', NULL, '詠扇詩 陳從道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4504ba7-6a6b-47d3-a6ee-450412c713de', '烏石山', '烏石山', '8d3e163f-9247-41f8-b803-addfdb6431dc', '唐', '["巖壑六七崦，茅茨三兩家。","整巢歸燕子，刺水長蒲芽。","貫碧流春漲，埋紅落野花。","困隨木上坐。","脚力未須嗟。","（見民國十七年余紹纂《龍遊縣志》卷三十七）（《龍遊縣志》附按：「右詩錄自兩舊志。","案原注云：『唐人。","』今考羣書，均未知其爲何人。","豈令君二字，稱其官耶？","明季清初人著書，恒不喜注明出處，以致後人失考類如是，可慨也。","」）。"]', '["巖壑六七崦，茅茨三兩家。","整巢归燕子，刺水长蒲芽。","貫碧流春漲，埋紅落野花。","困隨木上坐。","脚力未須嗟。","（见民国十七年余紹纂《龙游縣志》卷三十七）（《龙游縣志》附按：「右诗錄自兩旧志。","案原注云：『唐人。","』今考羣书，均未知其爲何人。","豈令君二字，稱其官耶？","明季清初人著书，恒不喜注明出处，以致後人失考類如是，可慨也。","」）。"]', '诗', 'shi', '', NULL, '烏石山 陶令君 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fbffb35-c48f-4ce1-88e6-3f5be86583cf', '戲贈', '戲贈', 'b2302f75-e91a-44c0-8ce5-932a14aca702', '唐', '["如今身披上清籙，莫遣落花羽衣。","（見《吟窗雜錄》卷三十《古今才婦》）。"]', '["如今身披上清籙，莫遣落花羽衣。","（见《吟窗杂錄》卷三十《古今才婦》）。"]', '诗', 'shi', '', NULL, '戲贈 崔萱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d98b4347-b957-4575-bb1a-93b017159dd1', '鵲巢背太歲賦附詩', '鵲巢背太歲賦附诗', '8e60e80b-1803-4525-9bbb-f3341096f9fd', '唐', '["日宮騅可躋，月樹復驚棲。","未聽將雛曲，空聞怨夜啼。","（見《文苑英華》卷一三七）。"]', '["日宮騅可躋，月樹复驚棲。","未听將雛曲，空闻怨夜啼。","（见《文苑英华》卷一三七）。"]', '诗', 'shi', '', NULL, '鵲巢背太歲賦附詩 崔元明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('833d4d9e-14a2-431b-ac51-2f85bdcbeabc', '遠意', '远意', 'f4c2a543-ef98-46a3-8c05-76124d5d9046', '唐', '["看花獨不語，裴回雙涙澘。"]', '["看花独不語，裴回雙涙澘。"]', '诗', 'shi', '', NULL, '遠意 崔公遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fca0a2c-e643-4c64-bd62-5e3c2afadd9d', '寄遠', '寄远', 'f4c2a543-ef98-46a3-8c05-76124d5d9046', '唐', '["君今遠戍在何處？","遣妾秋來長望天。","（均見《吟窗雜錄》卷三十《古今才婦》）（按：《全唐詩》卷八百一收四句，缺題，故重錄之。","）。"]', '["君今远戍在何处？","遣妾秋来长望天。","（均见《吟窗杂錄》卷三十《古今才婦》）（按：《全唐诗》卷八百一收四句，缺題，故重錄之。","）。"]', '诗', 'shi', '', NULL, '寄遠 崔公遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f287eefa-da3b-493c-ba55-251eb9b66abe', '贈營妓敦龐者（題擬）', '贈營妓敦龐者（題擬）', '11fd39de-9d42-4c6e-b159-8bffb04c3844', '唐', '["瓦棺寺裏逢行迹，華嶽山頭露掌痕。","不須惆悵愁難嫁，待與將書問嶽神。","（瓦棺寺有大佛迹嶽神大人。","見《增修詩話總龜》卷三七引《南部新書》）（按：此詩與《雲溪友議》卷中所載杜牧嘲妓詩之後半首多相同。","范據此書載事，多與史實相左，頗疑係採立言詩附會成杜牧故事。","杜詩已收《全唐詩》卷八七○。","）。"]', '["瓦棺寺裏逢行迹，华嶽山头露掌痕。","不須惆悵愁难嫁，待與將书问嶽神。","（瓦棺寺有大佛迹嶽神大人。","见《增修诗話總龟》卷三七引《南部新书》）（按：此诗與《云溪友議》卷中所載杜牧嘲妓诗之後半首多相同。","范據此书載事，多與史實相左，頗疑係採立言诗附會成杜牧故事。","杜诗已收《全唐诗》卷八七○。","）。"]', '诗', 'shi', '', NULL, '贈營妓敦龐者（題擬） 崔立言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd2e2d8e-8c3c-419f-843b-7039d1649a86', '贈友人', '贈友人', '3315c25b-e3d2-493f-a24d-7c6279d40293', '唐', '["聞道東山逸興多，爲憐明月映滄波。"]', '["闻道东山逸兴多，爲怜明月映滄波。"]', '诗', 'shi', '', NULL, '贈友人 常浩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b32ed85-7387-45b4-9aae-6fe8833400b3', '閨情', '閨情', '3315c25b-e3d2-493f-a24d-7c6279d40293', '唐', '["門前昨夜信初來，見說行人卒未迴。","誰家樓上吹橫笛，偏送愁聲向妾哀。","（均見明刻本宋陳應時《吟窗雜錄》卷三十《古今才婦》。","又見《名媛詩歸》卷十四。","胡偉《宮詞》收末句。","）。"]', '["门前昨夜信初来，见说行人卒未迴。","誰家楼上吹橫笛，偏送愁声向妾哀。","（均见明刻本宋陳應时《吟窗杂錄》卷三十《古今才婦》。","又见《名媛诗归》卷十四。","胡偉《宮词》收末句。","）。"]', '诗', 'shi', '', NULL, '閨情 常浩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8589e515-56d6-4282-9caf-d376960dcfd7', '井詩', '井诗', '3a5868e4-0cf2-4afd-9e9e-8ffba558a975', '唐', '["淺深人莫測，高下索應知。","（見《吟窗雜錄》卷十四正字王玄《詩中旨格》。","）。"]', '["淺深人莫測，高下索應知。","（见《吟窗杂錄》卷十四正字王玄《诗中旨格》。","）。"]', '诗', 'shi', '', NULL, '井詩 曾扈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b33caec6-739b-43c8-9b2a-416db042766d', '別弟', '別弟', '6021dbbc-ddc8-4153-87f0-1b9aa63decc5', '唐', '["十里河橋蔓草青，片帆瞬息短長亭。","不禁又作天涯客，愁覩郊原有鶺鴒。","。"]', '["十里河橋蔓草青，片帆瞬息短长亭。","不禁又作天涯客，愁覩郊原有鶺鴒。","。"]', '诗', 'shi', '', NULL, '別弟 馮友仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ba0ff26-72f4-426d-a8c2-1cd0c75268a6', '題詩壁上', '題诗壁上', '6021dbbc-ddc8-4153-87f0-1b9aa63decc5', '唐', '["呼號三諫信言難，義利分明一念間。","莫謂求名沽世譽，清風千古首陽山。"]', '["呼號三諫信言难，義利分明一念间。","莫謂求名沽世譽，清风千古首陽山。"]', '诗', 'shi', '', NULL, '題詩壁上 馮友仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('391ba24f-2a88-4aae-b421-a25a78f054bf', '寄弟', '寄弟', '6021dbbc-ddc8-4153-87f0-1b9aa63decc5', '唐', '["義心既重利心輕，分異何乖手足情。","糗飯自飴虞舜樂，採薇獨守伯夷清。","析居不忍從親令，退遜甘當矯世名。","賢弟晨昏勤定省，莫因流落念而兄。","（《堅瓠己集》卷四。","）。"]', '["義心既重利心轻，分異何乖手足情。","糗飯自飴虞舜乐，採薇独守伯夷清。","析居不忍從親令，退遜甘當矯世名。","賢弟晨昏勤定省，莫因流落念而兄。","（《堅瓠己集》卷四。","）。"]', '诗', 'shi', '', NULL, '寄弟 馮友仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37de41af-b833-4fc8-a9aa-c70ef26c5db5', '別兄（題擬）', '別兄（題擬）', 'a137cf36-1299-47b3-a74f-9d41fdd0838d', '唐', '["手足分擕腸斷時，關山千里共相思。","此行願促歸鞭早，莫待枝頭叫子規。"]', '["手足分擕腸斷时，关山千里共相思。","此行願促归鞭早，莫待枝头叫子規。"]', '诗', 'shi', '', NULL, '別兄（題擬） 馮友義 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bea80c7d-e577-4a8b-94ec-efa91b3897b2', '踵韻和兄見寄之作（題擬）', '踵韻和兄见寄之作（題擬）', 'a137cf36-1299-47b3-a74f-9d41fdd0838d', '唐', '["勢利鴻毛眼底輕，異居忍背雁行情。","薛包讓德千年烈，太伯存仁萬古清。","棄禮亂倫趨薄俗，分門割戶總浮名。","懸懸早發歸家念，幷奏塤篪樂弟兄。","（同前。","馮氏兄弟詩承張靖龍同志錄示。","）（按：馮氏兄弟事迹不見唐宋時記載，詩意亦頗俚俗，疑出後人依託。","）。"]', '["勢利鴻毛眼底轻，異居忍背雁行情。","薛包讓德千年烈，太伯存仁万古清。","棄禮亂倫趨薄俗，分门割戶總浮名。","懸懸早發归家念，幷奏塤篪乐弟兄。","（同前。","馮氏兄弟诗承張靖龙同志錄示。","）（按：馮氏兄弟事迹不见唐宋时記載，诗意亦頗俚俗，疑出後人依託。","）。"]', '诗', 'shi', '', NULL, '踵韻和兄見寄之作（題擬） 馮友義 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0eef55b8-cf2d-4ecc-b774-371f484cc355', '北京內晏', '北京內晏', 'c928c211-312d-4bd5-b16f-54435210099c', '唐', '["鏡鳴桂殿千山曉，花發梨園百卉新。","（《千載佳句》卷下《宮省部·禁中》。","）（按：《全唐詩逸》卷中收賀蘭暹詩，注「一作遂」。","今檢《千載佳句》作賀蘭遂，《日本國見在書目》有「《賀蘭遂集》二〖卷〗。","」當以作遂爲是。","）。"]', '["镜鳴桂殿千山晓，花發梨园百卉新。","（《千載佳句》卷下《宮省部·禁中》。","）（按：《全唐诗逸》卷中收賀蘭暹诗，注「一作遂」。","今檢《千載佳句》作賀蘭遂，《日本国见在书目》有「《賀蘭遂集》二〖卷〗。","」當以作遂爲是。","）。"]', '诗', 'shi', '', NULL, '北京內晏 賀蘭遂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('271919bf-47fb-43fd-b02b-82ce98c8f401', '爛柯山（題擬）', '爛柯山（題擬）', '29eb3015-b828-45e7-9a87-51cd65b96d4b', '唐', '["[洞天春遠日]行遲，[幾點殘星（殘）]僊子棋。","[樵斧]爛柯人換世，[碧]桃花影未曾移。","（見光緒卅二年鄭永禧纂《爛柯山志》卷十一《歷朝金石考》錄《唐楊明殘詩碑》。","碑僅存十六字，缺字係鄭氏據《府志》補。","）（〖1〗碑後附款識，上半已缺，殘文云：「諱明，字文舉，號潛醉，文章高古，詩爲耑門〖中缺〗柯山，而先生之詩，遂刻山中，以俟賞者〖中缺〗二年冬十月十有八日門生碣石王主敬謹。","」〖2〗鄭氏跋云：「右碑正書四行，行七字，詩一句。","每字方四寸許。","後二行款識，末一行年月，脫上年號，致難稽考耳。","碑四邊花紋，據瞿溥《日遲亭記》，係唐人詩刻，明代已斷，今尚存兩截。","跋內明無籍貫。","康熙《縣志》稱河東人，碣石在今山東武定府海豐縣黃河入海處，古河東地也，當不誤。","」「《府志》列宋詩，喜慶《志》並改《日致亭記》，取唐人）（『春遠日遲』之詠爲，昔人豈別有攷歟？","留俟知音。","」楊明爲唐人抑爲宋人，尚難確定，今姑錄出以備考詳。","又按：《南部新書》卷丁有王主敬事迹，未知即詩後題識者否。","據勞格《御史臺精舍題名考》卷一云，王主敬即王上客，高宗時人，事詳《劉賓客外集》卷九《王倰神道碑》及《太平廣記》卷二五○引《兩京新記》。","）。"]', '["[洞天春远日]行遲，[幾点殘星（殘）]僊子棋。","[樵斧]爛柯人換世，[碧]桃花影未曾移。","（见光緒卅二年鄭永禧纂《爛柯山志》卷十一《歷朝金石考》錄《唐楊明殘诗碑》。","碑僅存十六字，缺字係鄭氏據《府志》補。","）（〖1〗碑後附款識，上半已缺，殘文云：「諱明，字文舉，號潛醉，文章高古，诗爲耑门〖中缺〗柯山，而先生之诗，遂刻山中，以俟賞者〖中缺〗二年冬十月十有八日门生碣石王主敬謹。","」〖2〗鄭氏跋云：「右碑正书四行，行七字，诗一句。","每字方四寸許。","後二行款識，末一行年月，脫上年號，致难稽考耳。","碑四邊花紋，據瞿溥《日遲亭記》，係唐人诗刻，明代已斷，今尚存兩截。","跋內明無籍貫。","康熙《縣志》稱河东人，碣石在今山东武定府海豐縣黄河入海处，古河东地也，當不誤。","」「《府志》列宋诗，喜慶《志》並改《日致亭記》，取唐人）（『春远日遲』之詠爲，昔人豈別有攷歟？","留俟知音。","」楊明爲唐人抑爲宋人，尚难確定，今姑錄出以備考詳。","又按：《南部新书》卷丁有王主敬事迹，未知即诗後題識者否。","據勞格《御史台精舍題名考》卷一云，王主敬即王上客，高宗时人，事詳《劉賓客外集》卷九《王倰神道碑》及《太平廣記》卷二五○引《兩京新記》。","）。"]', '诗', 'shi', '', NULL, '爛柯山（題擬） 楊明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a136bd94-ae46-4d97-a3e2-6bec1e5cc6f0', '登第後送人歸宜春', '登第後送人归宜春', '1a5a585d-b8d3-4316-adf7-e28932161fa7', '唐', '["君歸爲說龍門事，雷雨初生電遶身。","（見《輿地紀勝》卷二八《袁州》。","）。"]', '["君归爲说龙门事，雷雨初生電遶身。","（见《輿地紀勝》卷二八《袁州》。","）。"]', '诗', 'shi', '', NULL, '登第後送人歸宜春 楊鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cac60fd-713f-4cde-b6a6-00b2ac94ee68', '謝姚月華遺石華詩', '謝姚月华遺石华诗', '743cb80e-754a-4d49-ac64-0876297052b2', '唐', '["青袿仙女隔蓬萊，珠樹金窗向曉開。","燕子羽毛非廣袖，殷勤也帶石花來。","（《瑯嬛記》卷中引《本傳》。","）。"]', '["青袿仙女隔蓬萊，珠樹金窗向晓开。","燕子羽毛非廣袖，殷勤也带石花来。","（《瑯嬛記》卷中引《本傳》。","）。"]', '诗', 'shi', '', NULL, '謝姚月華遺石華詩 楊達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf74c354-66ce-458e-bdd5-10498f79ede8', '茅亭詩', '茅亭诗', '56b43937-bd4d-41ab-a4d9-8e96cff1ab1e', '唐', '["池枯樹老花未開，黃鶯歌春空亭臺。","（見《吟窗雜錄》卷二九。","）。"]', '["池枯樹老花未开，黄鶯歌春空亭台。","（见《吟窗杂錄》卷二九。","）。"]', '诗', 'shi', '', NULL, '茅亭詩 楊少陽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3eaefbf2-7f6a-4e4a-99fe-afe00f97b554', '宿南巖寺感興', '宿南巖寺感兴', '6a0872e6-318c-4c1b-9e1a-a3453572bc09', '唐', '["南巖寺，本滄海，任子釣臺今尚在。","見說垂釣於此中，犗牛釣餌莊書載。","滄海竭，任子歿，波濤打處爲巖窟。","不知任子何所之，唯見釣臺空㟮屼。","（見《會稽掇英總集》卷九。","）（〖1〗《嘉泰會稽志》卷十一云：新昌縣「齊公井，在縣南五里南明山東麓，俗云齊相井。","唐齊顗所居山中有十五題，井其一也。","」原注：「案齊顗不爲相，俗傳誤也。","」）。"]', '["南巖寺，本滄海，任子釣台今尚在。","见说垂釣於此中，犗牛釣餌莊书載。","滄海竭，任子歿，波濤打处爲巖窟。","不知任子何所之，唯见釣台空㟮屼。","（见《會稽掇英總集》卷九。","）（〖1〗《嘉泰會稽志》卷十一云：新昌縣「齊公井，在縣南五里南明山东麓，俗云齊相井。","唐齊顗所居山中有十五題，井其一也。","」原注：「案齊顗不爲相，俗傳誤也。","」）。"]', '诗', 'shi', '', NULL, '宿南巖寺感興 齊顗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a47df408-ecc5-4277-b5a6-a70c4d68f5ee', '分宜讀書臺詩', '分宜读书台诗', '348afd30-020e-4e45-991f-c7655b880fd8', '唐', '["鐘山高高鐘水綠，昔有佳人在幽谷。","臺荒只見草萋萋，萬卷不留誰更讀。","（見明郭子章《豫章詩話》卷二。","）。"]', '["鐘山高高鐘水綠，昔有佳人在幽谷。","台荒只见草萋萋，万卷不留誰更读。","（见明郭子章《豫章诗話》卷二。","）。"]', '诗', 'shi', '', NULL, '分宜讀書臺詩 鄧廷聞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74d3c8da-6066-4428-926f-c1ac201f02db', '朝霞詩', '朝霞诗', '478358ee-e49d-4e8d-8b07-474e526c8fd1', '唐', '["不因紅日照，長作白雲飛。","（見《類說》卷十二《紀異記》。","）。"]', '["不因紅日照，长作白云飞。","（见《類说》卷十二《紀異記》。","）。"]', '诗', 'shi', '', NULL, '朝霞詩 趙林 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e8eabc3-5d7e-4e64-ada4-6a61a4c3cad8', '碧流院（題擬）', '碧流院（題擬）', '640f8a60-500b-4849-8cff-980a6e055c77', '唐', '["一沼光涵四座寒，夕陽迴首更憑欄。","憑師早把香蓮種，他日期來結社看。","（見《咸淳臨安志》卷八五。","）。"]', '["一沼光涵四座寒，夕陽迴首更憑欄。","憑師早把香蓮種，他日期来結社看。","（见《咸淳臨安志》卷八五。","）。"]', '诗', 'shi', '', NULL, '碧流院（題擬） 裴極 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba22869e-73ff-47b3-b498-9c32636d8194', '大丹歌', '大丹歌', '4ca94e12-9075-4c2a-bd2d-cd41339a5f36', '唐', '["大道留丹灶，清心慕煙霞。","陰陽成造化，水火結河車。","鉛汞須歸戊，爐開紫金花。","華池再修育，神水各爲家。","志士得之須保惜，定我性命育神室。","下士聞之多暗笑，真人見說安魂魄。","焚香禮之萬事畢，皆感天地作仙質。","（《正統道藏》本《大丹篇》。","）（按：《大丹篇》作者不詳。","大致可確定爲宋或宋以前人之作。","宋時無裴姓入相者，因知爲唐人之作。","）。"]', '["大道留丹灶，清心慕煙霞。","陰陽成造化，水火結河车。","鉛汞須归戊，爐开紫金花。","华池再修育，神水各爲家。","志士得之須保惜，定我性命育神室。","下士闻之多暗笑，真人见说安魂魄。","焚香禮之万事畢，皆感天地作仙質。","（《正統道藏》本《大丹篇》。","）（按：《大丹篇》作者不詳。","大致可確定爲宋或宋以前人之作。","宋时無裴姓入相者，因知爲唐人之作。","）。"]', '诗', 'shi', '', NULL, '大丹歌 裴相公 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93a1d814-361e-4fe0-9b0d-6232fd7a6384', '句', '句', '66207e84-0a43-4569-a1ed-8d1010e65bab', '唐', '["成童片子時，變老須臾事。","（見《後村大全集》卷一七七《詩話續集》引李康成《玉臺後集》。","）。"]', '["成童片子时，变老須臾事。","（见《後村大全集》卷一七七《诗話續集》引李康成《玉台後集》。","）。"]', '诗', 'shi', '', NULL, '句 劉珃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7adb7570-521f-4904-aa3a-68fa5063c779', '除夜', '除夜', '9971ed19-a203-46a6-a4b3-8886557c7ace', '唐', '["春風報梅柳，一夜發南枝。"]', '["春风報梅柳，一夜發南枝。"]', '诗', 'shi', '', NULL, '除夜 劉媛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a4889cf-b2f8-40e1-a61e-c3e61782788b', '贈怨者', '贈怨者', '9971ed19-a203-46a6-a4b3-8886557c7ace', '唐', '["傍人那得知心事，一面殘粧空涙痕。","（見《吟窗雜錄》卷三十《古今才婦》。","）（按：《全唐詩》卷八百一收四句，缺題，故重錄之。","）。"]', '["傍人那得知心事，一面殘粧空涙痕。","（见《吟窗杂錄》卷三十《古今才婦》。","）（按：《全唐诗》卷八百一收四句，缺題，故重錄之。","）。"]', '诗', 'shi', '', NULL, '贈怨者 劉媛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c562327-a4bc-4948-9f96-4673f31883ed', '句', '句', '95ad05fa-1727-4e59-ab6e-3e3b838fcbfa', '唐', '["門前清江水，流水秦人家。","（見《吟窗雜錄》卷十三王夢簡《進士王氏詩要格律》。","）。"]', '["门前清江水，流水秦人家。","（见《吟窗杂錄》卷十三王梦簡《進士王氏诗要格律》。","）。"]', '诗', 'shi', '', NULL, '句 歐陽皓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c4ddc32-8e1c-4ad9-bb89-7133b99c95fd', '柘枝舞（題擬）', '柘枝舞（題擬）', 'd03d8878-9e6b-485b-b780-5b7b4d938161', '唐', '["三敲畫鼓聲催急，一朵紅蓮出水遲。","（見《韻語陽秋》卷十五。","）。"]', '["三敲畫鼓声催急，一朵紅蓮出水遲。","（见《韻語陽秋》卷十五。","）。"]', '诗', 'shi', '', NULL, '柘枝舞（題擬） 鄭在德 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29e493dd-9ffc-42d9-bc4d-7dadc3a3eac3', '山居（七言）', '山居（七言）', 'f9ed490a-eb5f-483a-8fbc-3a12f94aa67c', '唐', '["犁鋤闊地燒侵雲，焰猛衝巖迸鹿羣。","鼙鼓靜時長霸國，戰爭無事感明君。","啼猿響樹寒山碧，宿鳥喧巢夜霧曛。","梯嶮上巖緣路去，院僧敲磬曉來聞。","（見宋桑世昌《回文類聚》卷三。","）（按：徐松《登科記考》卷二十七引《永樂大典》引《宜春志》，袁州進士及第者有戴光義，及第年代不詳。","光義當即光乂，未詳以孰爲正。","《宋史·藝文志》七著錄「戴文〖一作『乂』〗《迴文詩》一卷」，戴文或戴乂，均爲戴光乂之誤。","）。"]', '["犁鋤闊地燒侵云，焰猛衝巖迸鹿羣。","鼙鼓静时长霸国，戰爭無事感明君。","啼猿响樹寒山碧，宿鸟喧巢夜霧曛。","梯嶮上巖緣路去，院僧敲磬晓来闻。","（见宋桑世昌《回文類聚》卷三。","）（按：徐松《登科記考》卷二十七引《永乐大典》引《宜春志》，袁州進士及第者有戴光義，及第年代不詳。","光義當即光乂，未詳以孰爲正。","《宋史·藝文志》七著錄「戴文〖一作『乂』〗《迴文诗》一卷」，戴文或戴乂，均爲戴光乂之誤。","）。"]', '诗', 'shi', '', NULL, '山居（七言） 戴光乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42530364-6ed0-42bf-8c8a-e8edbb6f30dc', '缺題', '缺題', 'e7e4e1e1-f534-46a3-8fa1-526f95790723', '唐', '["生年一半在燕支，容顏沙場日夜衰。","蕭關不隔鄉園夢，瀚海長愁征戰期。","容顏日日老金{彳數}，砂磧年年卧鐵衣。","白草城中春不入，黃花戍上應長飛。","（伯三六一九卷。","）。"]', '["生年一半在燕支，容顏沙場日夜衰。","蕭关不隔乡园梦，瀚海长愁征戰期。","容顏日日老金{彳數}，砂磧年年卧鐵衣。","白草城中春不入，黄花戍上應长飞。","（伯三六一九卷。","）。"]', '诗', 'shi', '', NULL, '缺題 蕭沼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01f589c4-14aa-4a19-967f-b3d04a700a36', '偶作', '偶作', '0800567f-413c-492d-a19f-88cc1e5b9a6c', '唐', '["籠中鸚鵡囀清歌，盡是蕭娘舊教他。","今日獨來人不見，綠窗斜雨落花多。","（影印本《詩淵》第六冊第三九四五頁。","）。"]', '["籠中鸚鵡囀清歌，尽是蕭娘旧教他。","今日独来人不见，綠窗斜雨落花多。","（影印本《诗淵》第六冊第三九四五頁。","）。"]', '诗', 'shi', '', NULL, '偶作 蕭鐸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b983c7f8-db0b-44d8-8545-7dc524ae2229', '留題曹娥廟', '留題曹娥廟', 'dcdce940-5852-4e1e-b01a-cf2aafac6536', '唐', '["屈平以楚死，死濁不死清。","伍員以吳死，死暗不死明。","死者人所難，一死鴻毛輕。","壯哉二子爲，留得不死名。","曹娥以父死，年齡童未成。","抱屍出洪瀾，非可二子並。","二子諫不從，齊秦韓魏征。","娥若不之死，父葬鱣與鯨。","二子死以介，娥死以孝誠。","於今會稽人，事之如事生。","娥若生堯時，舜不妻女英。","娥若逢孔子，娥名書《孝經》。","娥父若羅辜，豈止爲緹縈。","蔡邕不知娥，但愛碑上銘。","我來拜祠下，古木寒雲橫。","往往大江水，猶作哀哀鳴。","安得娥有知，爲我神用靈。","鼓此大江波，注入四瀆平。","洗濯天下心，皆行娥所行。","（見《會稽掇英總集》卷八。","）。"]', '["屈平以楚死，死濁不死清。","伍員以吳死，死暗不死明。","死者人所难，一死鴻毛轻。","壯哉二子爲，留得不死名。","曹娥以父死，年齡童未成。","抱屍出洪瀾，非可二子並。","二子諫不從，齊秦韓魏征。","娥若不之死，父葬鱣與鯨。","二子死以介，娥死以孝誠。","於今會稽人，事之如事生。","娥若生堯时，舜不妻女英。","娥若逢孔子，娥名书《孝經》。","娥父若羅辜，豈止爲緹縈。","蔡邕不知娥，但愛碑上銘。","我来拜祠下，古木寒云橫。","往往大江水，猶作哀哀鳴。","安得娥有知，爲我神用靈。","鼓此大江波，注入四瀆平。","洗濯天下心，皆行娥所行。","（见《會稽掇英總集》卷八。","）。"]', '诗', 'shi', '', NULL, '留題曹娥廟 蕭闢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c26ef1a-9143-4399-88bb-6aea45cd2c17', '至西山', '至西山', 'e9193e9e-9d32-407d-88e5-6cda93099f27', '唐', '["閒說吳王避暑宮，滿山六月絳紗紅。","（見《輿地紀勝》卷八十一《壽昌軍》）。"]', '["閒说吳王避暑宮，满山六月絳紗紅。","（见《輿地紀勝》卷八十一《壽昌軍》）。"]', '诗', 'shi', '', NULL, '至西山 錢叔獻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aa319c5-71d6-4aab-8734-5926b9072577', '游苑', '游苑', '8795a3b0-ad9b-4a00-94b2-7e51001687f2', '唐', '["庭院開金鏁，周迴賞碧堂。","池深流水慢，岸闊引橋長。","遇石攀藤息，逢林摘果嘗。","更呼園子問，何處可尋涼？","（見伯三六一九卷。","）。"]', '["庭院开金鏁，周迴賞碧堂。","池深流水慢，岸闊引橋长。","遇石攀藤息，逢林摘果嘗。","更呼园子问，何处可尋涼？","（见伯三六一九卷。","）。"]', '诗', 'shi', '', NULL, '游苑 蘇癿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4a1ed93-7c87-4867-b9ff-5c1ab200b053', '清明日登張女郎神廟', '清明日登張女郎神廟', '8795a3b0-ad9b-4a00-94b2-7e51001687f2', '唐', '["汧水北，隴山東，漢家神女廟其中。","寒食盡，清明旦，遠近香車來不斷。","飛泉直注漴道間，大岫橫遮隱（伯三八八五卷無此字）天半。","花正新，草復綠，黃鶯現見（任半塘改爲「睍睆」）[遷喬]（〖千橋〗從任說改）木。","汧流括（任改作「活」），古樹攢，隴[坂]（（返）從任說改）高高布雲族（疑應作「簇」，任改爲「端」，恐非。","）水清靈，竹矇密，無匣仙潭難延碧。","談（任改作「淡」）樓閣，人畫成，翠嶺山花天繍出。","塵冥寞，馬盤桓，爭奔陌上聲散散。","公子王孫一隊隊，管絃歌舞幾般般。","酌醴醑，補（伯三八八五卷作「捕」，似皆未允，任錄作「舞」，似無據）錦筵，羅幃翠幕奄（任改作「掩」）靈泉。","是日（任錄誤作「堤上」）淹留不覺寐，歸來明月滿秦川。","（見伯三六一九卷、伯三八八五卷。","）（按：任半塘先生《敦煌歌辭總編》卷三錄此詩，僅據伯三六一九卷，文字偶有誤，但校改處亦頗可採，又推測蘇癿應爲哥舒翰同時人，亦可備一說。","）。"]', '["汧水北，隴山东，漢家神女廟其中。","寒食尽，清明旦，远近香车来不斷。","飞泉直注漴道间，大岫橫遮隐（伯三八八五卷無此字）天半。","花正新，草复綠，黄鶯現见（任半塘改爲「睍睆」）[遷喬]（〖千橋〗從任说改）木。","汧流括（任改作「活」），古樹攢，隴[坂]（（返）從任说改）高高布云族（疑應作「簇」，任改爲「端」，恐非。","）水清靈，竹矇密，無匣仙潭难延碧。","談（任改作「淡」）楼閣，人畫成，翠嶺山花天繍出。","塵冥寞，马盤桓，爭奔陌上声散散。","公子王孫一隊隊，管絃歌舞幾般般。","酌醴醑，補（伯三八八五卷作「捕」，似皆未允，任錄作「舞」，似無據）錦筵，羅幃翠幕奄（任改作「掩」）靈泉。","是日（任錄誤作「堤上」）淹留不覺寐，归来明月满秦川。","（见伯三六一九卷、伯三八八五卷。","）（按：任半塘先生《敦煌歌辞總編》卷三錄此诗，僅據伯三六一九卷，文字偶有誤，但校改处亦頗可採，又推測蘇癿應爲哥舒翰同时人，亦可備一说。","）。"]', '诗', 'shi', '', NULL, '清明日登張女郎神廟 蘇癿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d690d3c0-5c53-492c-8c71-47545337f2bd', '還丹口訣', '還丹口訣', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["還丹篇，還丹篇，欲得黃芽先炬鉛。","陽壬不去火中走，陰丙如何得作煙。","雞抱卵兮日數足，母生子兮十月全。","但得坤來爲屋宅，坤至何愁不作乾？","伏吾此法在目前，違吾此法饒萬年。","八石須向火中走，莫弄水飽費君錢。","還丹不是世難學，自是時人志不堅。","若明魏君謌十首，千廻海水變桑田。","（《大還丹照鑑》）。"]', '["還丹篇，還丹篇，欲得黄芽先炬鉛。","陽壬不去火中走，陰丙如何得作煙。","雞抱卵兮日數足，母生子兮十月全。","但得坤来爲屋宅，坤至何愁不作乾？","伏吾此法在目前，違吾此法饒万年。","八石須向火中走，莫弄水飽費君錢。","還丹不是世难学，自是时人志不堅。","若明魏君謌十首，千廻海水变桑田。","（《大還丹照鑑》）。"]', '诗', 'shi', '', NULL, '還丹口訣 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bbe9fef-bb77-4dc9-a308-f56237423b67', '金液還丹歌（題擬） 一', '金液還丹歌（題擬） 一', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["真陰真陽是其道，只在目前何還討？凡流歲歲鍊神丹，或見青黃自云好。"]', '["真陰真陽是其道，只在目前何還討？凡流歲歲鍊神丹，或见青黄自云好。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 一 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('357524ff-fe98-42ed-883c-69814b9eee89', '金液還丹歌（題擬） 二', '金液還丹歌（題擬） 二', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["志士應須承法則，莫損心神須見道。","但知求得真黃芽，人得食之壽無老。"]', '["志士應須承法則，莫損心神須见道。","但知求得真黄芽，人得食之壽無老。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 二 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a09cc3a8-0833-40e2-83af-b2c3844901de', '金液還丹歌（題擬） 三', '金液還丹歌（題擬） 三', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["神水華池世所稀，流傳不許俗人知。","還將世上凡鉛汞，相似令教人不疑。","（以上三首又見《金液還丹問訣》）。"]', '["神水华池世所稀，流傳不許俗人知。","還將世上凡鉛汞，相似令教人不疑。","（以上三首又见《金液還丹问訣》）。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 三 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5cdeef0-26b1-4586-a8cb-9c5ebe03e75b', '金液還丹歌（題擬） 四', '金液還丹歌（題擬） 四', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["黃芽不與世鉛同，徒以勞神不見功。"]', '["黄芽不與世鉛同，徒以勞神不见功。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 四 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eddfee19-ead6-49a9-9011-79e75663d25e', '金液還丹歌（題擬） 五', '金液還丹歌（題擬） 五', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["青龍逐虎虎隨龍，赤禽交會聲嗈嗈。","調氣運火逐離宮，丹砂入腹身自沖。"]', '["青龙逐虎虎隨龙，赤禽交會声嗈嗈。","調氣運火逐離宮，丹砂入腹身自沖。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 五 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89db0053-7fc8-4ab3-a9e2-7b4dd9f25da6', '金液還丹歌（題擬） 六', '金液還丹歌（題擬） 六', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["五行深妙義難知，龍虎隱藏在坎離，還丹之術數過百，最妙須得金華池。"]', '["五行深妙義难知，龙虎隐藏在坎離，還丹之術數過百，最妙須得金华池。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 六 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8451add3-d402-46ac-ad06-034faef290f7', '金液還丹歌（題擬） 七', '金液還丹歌（題擬） 七', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["丹砂其位元非赤，四季排來在南宅。","流珠本性無定居，若識其原似秋石。","。"]', '["丹砂其位元非赤，四季排来在南宅。","流珠本性無定居，若識其原似秋石。","。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 七 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd563128-d55d-4453-ae7e-e342bcf0a5d4', '金液還丹歌（題擬） 八', '金液還丹歌（題擬） 八', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["日魂月華二氣真，含胎育子自堪神。","變轉欲終君自見，分明化作明窗塵。"]', '["日魂月华二氣真，含胎育子自堪神。","变轉欲終君自见，分明化作明窗塵。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 八 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1ecc6ee-5abc-4beb-8ca7-1a5031d8ef31', '金液還丹歌（題擬） 九', '金液還丹歌（題擬） 九', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["鉛汞一門不可依，金丹秘訣聖無知。","莫將世上凡鉛汞，論年運火競相持。"]', '["鉛汞一门不可依，金丹秘訣聖無知。","莫將世上凡鉛汞，論年運火競相持。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 九 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a7c3d7e-a061-4340-91aa-d5ae25bd5b2e', '金液還丹歌（題擬） 十', '金液還丹歌（題擬） 十', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["天生二物應虛無，爲妻爲子復爲夫。","二五之門唯日月，能分卯酉座爲初。"]', '["天生二物應虛無，爲妻爲子复爲夫。","二五之门唯日月，能分卯酉座爲初。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 十 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('376fb4fe-9584-454e-9e21-8b3ae6a9ef27', '金液還丹歌（題擬） 十一', '金液還丹歌（題擬） 十一', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["含養天然稟至神，沖和之氣結成身。","富貴只緣懷五彩，心知鉛汞共成親。"]', '["含養天然稟至神，沖和之氣結成身。","富貴只緣懷五彩，心知鉛汞共成親。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 十一 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbbe5309-7c24-4de6-8710-c049d1344846', '金液還丹歌（題擬） 十二', '金液還丹歌（題擬） 十二', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["乾坤不許相爲避，志士元知在天地。"]', '["乾坤不許相爲避，志士元知在天地。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 十二 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54b4cc7b-0e44-4349-9810-745012c81a80', '金液還丹歌（題擬） 十三', '金液還丹歌（題擬） 十三', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["玄黃冥寞不可辯，鉛汞之門義難顯。","世人不曉定其原，細思至行自然見。"]', '["玄黄冥寞不可辯，鉛汞之门義难显。","世人不晓定其原，細思至行自然见。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 十三 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76465774-f634-4894-9d2b-07c00c2aebe6', '金液還丹歌（題擬） 十四', '金液還丹歌（題擬） 十四', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["嬰兒漠漠不可悟，徒以勞神虎見苦。","但知會得聖人言，即是分明上天路。"]', '["嬰兒漠漠不可悟，徒以勞神虎见苦。","但知會得聖人言，即是分明上天路。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 十四 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8d06b8e-6cd5-4228-8e31-8f93ca19adb4', '金液還丹歌（題擬） 十五', '金液還丹歌（題擬） 十五', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["三四同居共一室，一二夫妻爲偶匹。","要假良媒方得親，遂使交遊情意密。"]', '["三四同居共一室，一二夫妻爲偶匹。","要假良媒方得親，遂使交游情意密。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 十五 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc85d8d1-af4a-4cb8-a2e8-33b58bd949e0', '金液還丹歌（題擬） 十六', '金液還丹歌（題擬） 十六', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["浮沉恍惚性難辨，誤取迷途年月遠。","欲知靈藥何日成，陽數終須歸九轉。"]', '["浮沉恍惚性难辨，誤取迷途年月远。","欲知靈藥何日成，陽數終須归九轉。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 十六 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('165403d7-b557-453f-adac-3a2b0ed3cf33', '金液還丹歌（題擬） 十七', '金液還丹歌（題擬） 十七', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["陰陽冥寞不可知，青龍白虎自相持。","年終被轉自相噉，白虎制龍龍漸希。"]', '["陰陽冥寞不可知，青龙白虎自相持。","年終被轉自相噉，白虎制龙龙漸希。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 十七 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54b5dda1-fc6f-43e6-b0ed-bc532be373e6', '金液還丹歌（題擬） 十八', '金液還丹歌（題擬） 十八', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["乾天爲父坤爲母，南方朱雀北玄武。"]', '["乾天爲父坤爲母，南方朱雀北玄武。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 十八 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a91ecefc-8116-4811-a4f6-b25c6cbae31c', '金液還丹歌（題擬） 十九', '金液還丹歌（題擬） 十九', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["三人義合同爲宗，常飲日月照其中。","已過三花金再液，九轉須終歲月功。"]', '["三人義合同爲宗，常饮日月照其中。","已過三花金再液，九轉須終歲月功。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 十九 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f2d7e8d-37af-4fe6-bec5-c8b973801be7', '金液還丹歌（題擬） 二十', '金液還丹歌（題擬） 二十', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["青龍本質在東宮，配合乾坤震位中。","白虎自茲相見後，流珠那肯不相從。"]', '["青龙本質在东宮，配合乾坤震位中。","白虎自茲相见後，流珠那肯不相從。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 二十 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de75809e-fa88-497a-ac93-b0219fc5d7a3', '金液還丹歌（題擬） 二十一', '金液還丹歌（題擬） 二十一', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["龍虎修來五轉強，爐中漸覺菊花香。","如今修鍊正當節，莫恨悠悠歲月長。"]', '["龙虎修来五轉強，爐中漸覺菊花香。","如今修鍊正當節，莫恨悠悠歲月长。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 二十一 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24a553aa-12f2-4df5-81e3-5f6af273b43c', '金液還丹歌（題擬） 二十二', '金液還丹歌（題擬） 二十二', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["欲（一作「要」）識丹砂是木精，移來西位與金幷。","凡（一作「迷」）人何處尋蹤跡（一作「龍虎」），恍惚中（一作「之」）間在（一作「是」）杳冥。","（此首又見《金液還丹百問訣》。","）。"]', '["欲（一作「要」）識丹砂是木精，移来西位與金幷。","凡（一作「迷」）人何处尋蹤跡（一作「龙虎」），恍惚中（一作「之」）间在（一作「是」）杳冥。","（此首又见《金液還丹百问訣》。","）。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 二十二 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adea0876-9705-4303-b03d-ff3f9f719bfb', '金液還丹歌（題擬） 二十三', '金液還丹歌（題擬） 二十三', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["悟者猶如返歧蹤，迷途不易尋路苦。"]', '["悟者猶如返歧蹤，迷途不易尋路苦。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 二十三 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1df8afb4-b0ad-44bf-9b6c-616b5f68e1bf', '金液還丹歌（題擬） 二十四', '金液還丹歌（題擬） 二十四', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["一人本有一人無，金公爲婦木爲夫。","玄冥深奧不可度，志士何曾肯語圖。"]', '["一人本有一人無，金公爲婦木爲夫。","玄冥深奧不可度，志士何曾肯語圖。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 二十四 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('884d895d-d293-45c1-83fe-89d0af63ef13', '金液還丹歌（題擬） 二十五', '金液還丹歌（題擬） 二十五', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["玄天汪汪配地黃，男精和合並同房。","白液爐中隨月化，時人服者瑩心涼。"]', '["玄天汪汪配地黄，男精和合並同房。","白液爐中隨月化，时人服者瑩心涼。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 二十五 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2d2d062-5214-4b6a-8c85-548c9ed0ee9b', '金液還丹歌（題擬） 二十六', '金液還丹歌（題擬） 二十六', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["金木相傷誰定原，五行相返自相連。"]', '["金木相傷誰定原，五行相返自相連。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 二十六 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03a4e8c2-28dc-437e-9d97-47883cf844bd', '金液還丹歌（題擬） 二十七', '金液還丹歌（題擬） 二十七', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["世間鉛汞不相依，志士元知在坎離。","賢者共藏人不見，淮南修秘在華池。"]', '["世间鉛汞不相依，志士元知在坎離。","賢者共藏人不见，淮南修秘在华池。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 二十七 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b50fb164-7eb0-4aad-a4be-f0182dc736f0', '金液還丹歌（題擬） 二十八', '金液還丹歌（題擬） 二十八', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["九轉丹成歲欲終，開爐忽見藥花紅。"]', '["九轉丹成歲欲終，开爐忽见藥花紅。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 二十八 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18ce9a0c-8778-4b01-97f9-080d3fda3909', '金液還丹歌（題擬） 二十九', '金液還丹歌（題擬） 二十九', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["鉛汞相傳世所希，丹砂玉質雪爲衣。","朦朧只在君家舍，日日君看君不知。"]', '["鉛汞相傳世所希，丹砂玉質雪爲衣。","朦朧只在君家舍，日日君看君不知。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 二十九 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13238cda-99d4-4eb0-88bf-d3780f033ac1', '金液還丹歌（題擬） 三十', '金液還丹歌（題擬） 三十', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["還丹入口身自輕，能銷久病去祅精。","貪愛自茲無所染，能改愚人世與情。"]', '["還丹入口身自轻，能銷久病去祅精。","貪愛自茲無所染，能改愚人世與情。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 三十 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b63698a-1d11-447d-a17c-f548b69244cc', '金液還丹歌（題擬） 三十一', '金液還丹歌（題擬） 三十一', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["誰悟靈丹出世塵，三花合會與龍親。","君看前後鍊丹者，誤煞千人與萬人。","（以上皆見《正統道藏》珠字號《元陽子金液集》。","）。"]', '["誰悟靈丹出世塵，三花合會與龙親。","君看前後鍊丹者，誤煞千人與万人。","（以上皆见《正統道藏》珠字號《元陽子金液集》。","）。"]', '诗', 'shi', '', NULL, '金液還丹歌（題擬） 三十一 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a858898-447a-406e-99c5-63ac42e1546f', '還丹金液歌', '還丹金液歌', 'f124c12f-cab9-4845-ad70-394474f981e5', '唐', '["和氣和太初，初氣終歸一。","母子本相生，相生又相失。","陰鍊玄陰精，月旬嫁於日。","日月既相交，還丹赩然出。","北方取河車，南方朱雀一。","碧水生妙花，白花懷玉質。","龍虬入相交，刀圭須謹密。","獨弄在乾坤，能滋於萬物。","姹女玄陰精，二種皆歸一。","河上無水銀，乃合著陰律。","蕩蕩赤龍蟠，火候看容質。","變作裏蹄金，黃芽無根術。","火記三百篇，知之萬不失。","如騾懷姙駒，自懷其形質。","（《正統道藏》珠芓號《還丹金液歌註》。","原有張果註。","）。"]', '["和氣和太初，初氣終归一。","母子本相生，相生又相失。","陰鍊玄陰精，月旬嫁於日。","日月既相交，還丹赩然出。","北方取河车，南方朱雀一。","碧水生妙花，白花懷玉質。","龙虬入相交，刀圭須謹密。","独弄在乾坤，能滋於万物。","姹女玄陰精，二種皆归一。","河上無水銀，乃合著陰律。","蕩蕩赤龙蟠，火候看容質。","变作裏蹄金，黄芽無根術。","火記三百篇，知之万不失。","如騾懷姙駒，自懷其形質。","（《正統道藏》珠芓號《還丹金液歌註》。","原有張果註。","）。"]', '诗', 'shi', '', NULL, '還丹金液歌 元陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a02c1c9-6d91-48ed-83a8-123ae1a2d5c4', '靈草歌 達道草', '靈草歌 達道草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["結汞事如何，莫拋靈草歌。","只何赤勤好，偏用達道多。"]', '["結汞事如何，莫拋靈草歌。","只何赤勤好，偏用達道多。"]', '诗', 'shi', '', NULL, '靈草歌 達道草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e9a4179-1c22-48d7-a336-b114f754acfc', '靈草歌 海寶草', '靈草歌 海寶草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["十年學仙術，靈草少知音。","白祿堪爲櫃，海寶善軟金。","生在沙崗上，常得道家欽。","朱內抽真汞，花紅根自深。"]', '["十年学仙術，靈草少知音。","白祿堪爲櫃，海寶善軟金。","生在沙崗上，常得道家欽。","朱內抽真汞，花紅根自深。"]', '诗', 'shi', '', NULL, '靈草歌 海寶草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('755c8fc0-07f7-4925-a66a-f062c9163cee', '靈草歌 紫芝草', '靈草歌 紫芝草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["此花有不稀，出土並三枝。","朱砂見寶白，煑汞自然癡。"]', '["此花有不稀，出土並三枝。","朱砂见寶白，煑汞自然癡。"]', '诗', 'shi', '', NULL, '靈草歌 紫芝草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a3141af-4d67-4852-ad33-9363e7687814', '靈草歌 合穗草', '靈草歌 合穗草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["天降神櫃草，無過訪合穗。","燒藥實堪誇，不與凡草揆。","衆草經霜軟，此草不憔悴。","寒暑不相侵，燒藥添智慧。"]', '["天降神櫃草，無過訪合穗。","燒藥實堪誇，不與凡草揆。","衆草經霜軟，此草不憔悴。","寒暑不相侵，燒藥添智慧。"]', '诗', 'shi', '', NULL, '靈草歌 合穗草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fc4ba12-99ce-484b-b5e3-207f4d9f3fd1', '靈草歌 望仙草', '靈草歌 望仙草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["春生草鋪煙，未上摘望仙。","伏朱砂作汁，結汞汞便乾。","。"]', '["春生草鋪煙，未上摘望仙。","伏朱砂作汁，結汞汞便乾。","。"]', '诗', 'shi', '', NULL, '靈草歌 望仙草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0cceecf-6ea2-486a-ab18-14c6c852690a', '靈草歌 金蓮草', '靈草歌 金蓮草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["燒丹偏教玄，但採草金蓮。","衆藥堪爲櫃，遇凡不須言。"]', '["燒丹偏教玄，但採草金蓮。","衆藥堪爲櫃，遇凡不須言。"]', '诗', 'shi', '', NULL, '靈草歌 金蓮草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4592cf0b-e47e-4f37-ba7e-562d6d95a096', '靈草歌 玉液草', '靈草歌 玉液草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["玉液草能紅，大藥與相通。","偏櫃草砂子，見寶有殊功。"]', '["玉液草能紅，大藥與相通。","偏櫃草砂子，见寶有殊功。"]', '诗', 'shi', '', NULL, '靈草歌 玉液草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00f90f48-2077-4f62-bade-f53e496f12d4', '靈草歌 大秘草', '靈草歌 大秘草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["大道須懷志，此草深要記。","四神偏能伏，兼燒大二氣。"]', '["大道須懷志，此草深要記。","四神偏能伏，兼燒大二氣。"]', '诗', 'shi', '', NULL, '靈草歌 大秘草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2dda023-b569-47b5-aaa2-5f3700997023', '靈草歌 金風草', '靈草歌 金风草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["子黑根白花葉青，仙家惜似掌中珍。","真汞煮作硬砂子，白體成庚重不輕。"]', '["子黑根白花葉青，仙家惜似掌中珍。","真汞煮作硬砂子，白體成庚重不轻。"]', '诗', 'shi', '', NULL, '靈草歌 金風草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dba0c5d8-736a-4cbf-a23a-b98e8b42253d', '靈草歌 大通草', '靈草歌 大通草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["大通花紅葉似青，子黑根白味不辛。","一生長養河次畔，獨體結成砂子真。"]', '["大通花紅葉似青，子黑根白味不辛。","一生长養河次畔，独體結成砂子真。"]', '诗', 'shi', '', NULL, '靈草歌 大通草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ebd433b-aead-47af-b0f1-ae0c0c23cfa8', '靈草歌 天降草', '靈草歌 天降草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["芝草延年壽，五鳳結成珍。","六龍堪爲櫃，七寶善養庚。","玉柱能香美，青泉苦味辛。","萬通偏煮汞，天降立制成。"]', '["芝草延年壽，五鳳結成珍。","六龙堪爲櫃，七寶善養庚。","玉柱能香美，青泉苦味辛。","万通偏煮汞，天降立制成。"]', '诗', 'shi', '', NULL, '靈草歌 天降草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42cb7206-344e-4ed8-9fd6-4f618aaa472c', '靈草歌 惹羅衣草', '靈草歌 惹羅衣草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["出羣葉綠順五枝，見寶雄煮事相依。","煮汞成珍作砂子，五金偏道定相宜。"]', '["出羣葉綠順五枝，见寶雄煮事相依。","煮汞成珍作砂子，五金偏道定相宜。"]', '诗', 'shi', '', NULL, '靈草歌 惹羅衣草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('581d9cbb-f4da-472e-be1d-763f63f20a02', '靈草歌 大道草', '靈草歌 大道草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, '靈草歌 大道草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a555e57-e77c-4f39-b3df-5e2aa8299a88', '靈草歌 大道草 一', '靈草歌 大道草 一', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["大道名高以傳聲，陰陽二氣子雙新。","抽汞使來經數載，不知標在出靈真。"]', '["大道名高以傳声，陰陽二氣子雙新。","抽汞使来經數載，不知標在出靈真。"]', '诗', 'shi', '', NULL, '靈草歌 大道草 一 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3ce54f4-fec3-4b79-b61b-996238786189', '靈草歌 大道草 二', '靈草歌 大道草 二', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["大道草葉細，一花結二子。","抽汞自然新，水銀見即死。"]', '["大道草葉細，一花結二子。","抽汞自然新，水銀见即死。"]', '诗', 'shi', '', NULL, '靈草歌 大道草 二 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22d8fa5d-b05d-4e19-8f95-93dd154ca573', '靈草歌 長生草', '靈草歌 长生草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["此草功能世所稀，不遇真本少人知。","仙家異呼長生草，偏解常燒伏火砒。"]', '["此草功能世所稀，不遇真本少人知。","仙家異呼长生草，偏解常燒伏火砒。"]', '诗', 'shi', '', NULL, '靈草歌 長生草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c9cdd2d-9100-459b-b5a3-fe8a34188107', '靈草歌 白鶴草', '靈草歌 白鹤草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["白鶴偏有功，葉青花自紅。","獨體伏真汞，長生在林中。"]', '["白鹤偏有功，葉青花自紅。","独體伏真汞，长生在林中。"]', '诗', 'shi', '', NULL, '靈草歌 白鶴草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('040c3dd6-8ce3-4725-832d-3cc0f41bc635', '靈草歌 磨羅草', '靈草歌 磨羅草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["紫花白汁多，大道號磨羅。","不但延年壽，伏藥櫃使多。"]', '["紫花白汁多，大道號磨羅。","不但延年壽，伏藥櫃使多。"]', '诗', 'shi', '', NULL, '靈草歌 磨羅草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91651f23-0b4a-4364-a754-1260c326e8a0', '靈草歌 鳳青草', '靈草歌 鳳青草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["志道要超昇，須訪神草經。","聖事常宜重，非人莫謾輕。","恐折人間壽，看似掌中珍。","欲知庚汞了，須採草鳳青。"]', '["志道要超昇，須訪神草經。","聖事常宜重，非人莫謾轻。","恐折人间壽，看似掌中珍。","欲知庚汞了，須採草鳳青。"]', '诗', 'shi', '', NULL, '靈草歌 鳳青草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79a0793d-d4e8-4c53-813f-07346ebdf6cc', '靈草歌 顯志草', '靈草歌 显志草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["顯志實堪誇，雪內放黃花。","寒暑不相礙，獨體草結砂。"]', '["显志實堪誇，雪內放黄花。","寒暑不相礙，独體草結砂。"]', '诗', 'shi', '', NULL, '靈草歌 顯志草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a0f4d67-cbcd-4995-9940-d519fce01054', '靈草歌 水紅草', '靈草歌 水紅草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["天生號水紅，伏汞意不重。","偏伏碙砂白，兼櫃大雌雄。","。"]', '["天生號水紅，伏汞意不重。","偏伏碙砂白，兼櫃大雌雄。","。"]', '诗', 'shi', '', NULL, '靈草歌 水紅草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12fe4109-62e6-4c7f-8880-f76bf35ea8f4', '靈草歌 地蕉草', '靈草歌 地蕉草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["伏藥偏清高，無過採地蕉。","不但抽真汞，兼伏石中硝。"]', '["伏藥偏清高，無過採地蕉。","不但抽真汞，兼伏石中硝。"]', '诗', 'shi', '', NULL, '靈草歌 地蕉草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d405649f-53ab-4857-b332-990417b3ad26', '靈草歌 寶山草', '靈草歌 寶山草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["寶草號寶山，生居大林間。","仙家偏秘借，價直萬千錢。"]', '["寶草號寶山，生居大林间。","仙家偏秘借，價直万千錢。"]', '诗', 'shi', '', NULL, '靈草歌 寶山草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd4d406b-5e28-496e-9861-80a6fbfa328b', '靈草歌 小金線草', '靈草歌 小金線草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["靈草並光鮮，金線力最堅。","便是稀砂子，葉裏自然乾。"]', '["靈草並光鲜，金線力最堅。","便是稀砂子，葉裏自然乾。"]', '诗', 'shi', '', NULL, '靈草歌 小金線草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13795221-8b65-410d-9e40-a51e2b3fa260', '靈草歌 真珠草', '靈草歌 真珠草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["靈苗櫃藥好，無過真珠草。","伏藥定無憂，服食人不老。"]', '["靈苗櫃藥好，無過真珠草。","伏藥定無憂，服食人不老。"]', '诗', 'shi', '', NULL, '靈草歌 真珠草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0d956ea-51fd-47c7-b1ad-5100217dde38', '靈草歌 金鸞草', '靈草歌 金鸾草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["大道秘金鸞，仙家亦不傳，堪作庚汞櫃，採寶勝湧泉。"]', '["大道秘金鸾，仙家亦不傳，堪作庚汞櫃，採寶勝湧泉。"]', '诗', 'shi', '', NULL, '靈草歌 金鸞草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('777012f9-e504-4b25-bb1a-ec9e2f6cee87', '靈草歌 海石榴草', '靈草歌 海石榴草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["採汞不知休，無過海石榴。"]', '["採汞不知休，無過海石榴。"]', '诗', 'shi', '', NULL, '靈草歌 海石榴草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abc70c1f-36a9-4b8c-8683-9a9a0001d81a', '靈草歌 聚珍草', '靈草歌 聚珍草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["天降號聚珍，四季葉長青。","凡人多不識，看似掌中金。","服食添長命，生餐善治心。","不是真仙本，世間少知音。"]', '["天降號聚珍，四季葉长青。","凡人多不識，看似掌中金。","服食添长命，生餐善治心。","不是真仙本，世间少知音。"]', '诗', 'shi', '', NULL, '靈草歌 聚珍草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e56e392e-3eed-4566-8808-dbbe4217f900', '靈草歌 海桃草', '靈草歌 海桃草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["靈枝號海桃，生服善治勞。","不但添人壽，兼軟汞與錨。","。"]', '["靈枝號海桃，生服善治勞。","不但添人壽，兼軟汞與錨。","。"]', '诗', 'shi', '', NULL, '靈草歌 海桃草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('015ecafb-79b2-4338-9e39-11e5645d87d5', '靈草歌 金燈草', '靈草歌 金灯草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["此草味教辛，仙家喚金燈。","生服能治病，一載自身輕。","伏砒砒能白，結汞汞轉新。","不然濟人命，兼取汞中庚。"]', '["此草味教辛，仙家喚金灯。","生服能治病，一載自身轻。","伏砒砒能白，結汞汞轉新。","不然濟人命，兼取汞中庚。"]', '诗', 'shi', '', NULL, '靈草歌 金燈草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97457a7f-6e9d-4a5e-b300-e28d5f763510', '靈草歌 山青草', '靈草歌 山青草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["仙草名山青，根株似黃精。","人服髪再黑，偏療小兒驚。","燒藥堪爲櫃，秋夏葉長新。"]', '["仙草名山青，根株似黄精。","人服髪再黑，偏療小兒驚。","燒藥堪爲櫃，秋夏葉长新。"]', '诗', 'shi', '', NULL, '靈草歌 山青草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b7ff2ea-050d-4ee3-b639-80bcf025d01b', '靈草歌 萬通草', '靈草歌 万通草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["大道依仙蹤，方顯有神功。","三黃成真體，白虎是一宗。","金丹求靈草，石櫃卒難窮。","欲知鉛汞了，須採草萬通。"]', '["大道依仙蹤，方显有神功。","三黄成真體，白虎是一宗。","金丹求靈草，石櫃卒难窮。","欲知鉛汞了，須採草万通。"]', '诗', 'shi', '', NULL, '靈草歌 萬通草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce616ec0-2947-4189-8909-e808cd92f530', '靈草歌 白珠草', '靈草歌 白珠草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["大道與仙同，須向草中功。","金石能飛走，靈草自相通。","但依真仙草，製向鉛汞中。","欲得金丹就，採取草山紅。"]', '["大道與仙同，須向草中功。","金石能飞走，靈草自相通。","但依真仙草，製向鉛汞中。","欲得金丹就，採取草山紅。"]', '诗', 'shi', '', NULL, '靈草歌 白珠草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6862dbc2-54ba-44d5-9067-47a0520b4e30', '靈草歌 龍泉草', '靈草歌 龙泉草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["萬物萌芽在春前，只有龍泉出土先。","見寶朱砂用葉裏，自然汁煮汞成乾。"]', '["万物萌芽在春前，只有龙泉出土先。","见寶朱砂用葉裏，自然汁煮汞成乾。"]', '诗', 'shi', '', NULL, '靈草歌 龍泉草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b266d60f-bdf5-49aa-bedd-241d85c770b2', '靈草歌 寶峰草', '靈草歌 寶峰草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["大道居鄽市，訪道莫西東。","但求真鉛汞，四事總相通。","聖事依指教，不越大仙蹤。","欲知黃芽現，須採草寶峰。","。"]', '["大道居鄽市，訪道莫西东。","但求真鉛汞，四事總相通。","聖事依指教，不越大仙蹤。","欲知黄芽現，須採草寶峰。","。"]', '诗', 'shi', '', NULL, '靈草歌 寶峰草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03400812-7b9f-44fb-a8d6-d9284989fe7e', '靈草歌 金錢草', '靈草歌 金錢草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["了道與延年，無過訪金錢。","服食添人壽，乾汞兼駐顏。"]', '["了道與延年，無過訪金錢。","服食添人壽，乾汞兼駐顏。"]', '诗', 'shi', '', NULL, '靈草歌 金錢草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ab5a4da-4957-4de3-b466-3725d60cb53b', '靈草歌 仙娥草', '靈草歌 仙娥草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["造化紫河草，不及草仙娥。","能伏飛流藥，大道知也麼。"]', '["造化紫河草，不及草仙娥。","能伏飞流藥，大道知也麼。"]', '诗', 'shi', '', NULL, '靈草歌 仙娥草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('feaa3862-15e0-405b-882a-12a266404c38', '靈草歌 黃芽草', '靈草歌 黄芽草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["花葉能青綠，根白色似金。"]', '["花葉能青綠，根白色似金。"]', '诗', 'shi', '', NULL, '靈草歌 黃芽草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71ddfd51-5c20-4f20-8d9b-b04a3260ed57', '靈草歌 青金草', '靈草歌 青金草', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["久聞有靈草，不過青金好。","葉綠枝條嫩，服食人不老。"]', '["久闻有靈草，不過青金好。","葉綠枝條嫩，服食人不老。"]', '诗', 'shi', '', NULL, '靈草歌 青金草 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9941c5e-2c87-4ba9-b13b-6b1e675583cb', '靈草歌 秘曰', '靈草歌 秘曰', '4685b6aa-a5fb-4cc9-a0e0-b132a17c55e1', '唐', '["七十二草總有靈，各伏丹砂並通神。","不是上方留下界，凡世俗流少聽聞。","（《正統道藏》如字號。","）（〖1〗《崇文總目》卷四道書類七著錄：「《白雲仙人靈草歌》一卷。","」不題撰人。","又見《通志·藝文略》）。"]', '["七十二草總有靈，各伏丹砂並通神。","不是上方留下界，凡世俗流少听闻。","（《正統道藏》如字號。","）（〖1〗《崇文總目》卷四道书類七著錄：「《白云仙人靈草歌》一卷。","」不題撰人。","又见《通志·藝文略》）。"]', '诗', 'shi', '', NULL, '靈草歌 秘曰 白雲仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c170435-78c6-4ff1-a26d-aa318afd135f', '', '', 'd782bf19-6e55-4067-8e74-7929c172af91', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 朱君緒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec5cf976-8b9a-45bb-82fa-96ad4f62ef46', '法師昇高座詠', '法師昇高座詠', 'd782bf19-6e55-4067-8e74-7929c172af91', '唐', '["弟子仰法師，敢啓有所陳。","衆生闇塞久，思聞至法音。","大慈開長夜，設化萬劫新。","主人建福齋，延及四輩人。"]', '["弟子仰法師，敢啓有所陳。","衆生闇塞久，思闻至法音。","大慈开长夜，設化万劫新。","主人建福斋，延及四輩人。"]', '诗', 'shi', '', NULL, '法師昇高座詠 朱君緒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb8a02c3-9096-4d23-a974-8fb40139c4b4', '法師昇高座時詠', '法師昇高座时詠', 'd782bf19-6e55-4067-8e74-7929c172af91', '唐', '["齋直道所務，妙品元始貴。","故設祖劫橋，廣度諸民物。","爾曰設清齋，帳座羅五色。","天仙遊誕上，五帝列方職。","功曹傳符命，擁衛左右直。","我昇龍輿座。","玉梯附機息。","神霄助授護，天魔不舉目。","五神不移動，披宣太上域。"]', '["斋直道所務，妙品元始貴。","故設祖劫橋，廣度諸民物。","爾曰設清斋，帳座羅五色。","天仙游誕上，五帝列方職。","功曹傳符命，擁衛左右直。","我昇龙輿座。","玉梯附機息。","神霄助授護，天魔不舉目。","五神不移动，披宣太上域。"]', '诗', 'shi', '', NULL, '法師昇高座時詠 朱君緒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d09a300-2f5f-4aac-a191-7bb0ddfcd06d', '定座詠', '定座詠', 'd782bf19-6e55-4067-8e74-7929c172af91', '唐', '["大道無爲中，積氣運起形。","爲衆設橋梁，故遺無等經。","修之得長樂，莫有三界生。","燒去六塵垢，一心靜念聽。"]', '["大道無爲中，積氣運起形。","爲衆設橋梁，故遺無等經。","修之得长乐，莫有三界生。","燒去六塵垢，一心静念听。"]', '诗', 'shi', '', NULL, '定座詠 朱君緒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f7e4308-da69-4b22-b317-50bef8277088', '下座詠', '下座詠', 'd782bf19-6e55-4067-8e74-7929c172af91', '唐', '["妙品演布化，迢迢霄玄音。","等受無礙智，三梁度黃津。","神霄功曹使，疲勞小停神。","三會因勞賞，當報不負言。","須啓更當白，便曹未恚懸。","下座服居位，禮拜三寶尊。","（《要修科儀戒律鈔》卷二）。"]', '["妙品演布化，迢迢霄玄音。","等受無礙智，三梁度黄津。","神霄功曹使，疲勞小停神。","三會因勞賞，當報不負言。","須啓更當白，便曹未恚懸。","下座服居位，禮拜三寶尊。","（《要修科儀戒律鈔》卷二）。"]', '诗', 'shi', '', NULL, '下座詠 朱君緒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('142254b6-6be1-4d25-8d9a-c05129f419bc', '還丹口訣', '還丹口訣', 'a7c34620-2c22-48dc-b872-8a281bdb3bbb', '唐', '["天生太素，地產靈津。","能伏能飛，變化如神。","陰陽宗祖，道契君臣。","聖人秘寶，非者不聞。","且太素爲君，靈津爲臣。","合和兩性，呼吸相呑。","爲夫爲婦，男女姻親。","變化鉤牽，恩愛傳真。"]', '["天生太素，地產靈津。","能伏能飞，变化如神。","陰陽宗祖，道契君臣。","聖人秘寶，非者不闻。","且太素爲君，靈津爲臣。","合和兩性，呼吸相呑。","爲夫爲婦，男女姻親。","变化鉤牽，恩愛傳真。"]', '诗', 'shi', '', NULL, '還丹口訣 岑真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd4721d8-0065-4278-a9d6-ad47b888db22', '還丹歌', '還丹歌', 'a7c34620-2c22-48dc-b872-8a281bdb3bbb', '唐', '["東方青龍，丙丁甲乙。","西方白虎，壬癸凝液。","二氣舍真，世人難覓。","機持此寶，一水一石。","灰池焰爍，名除死籍。"]', '["东方青龙，丙丁甲乙。","西方白虎，壬癸凝液。","二氣舍真，世人难覓。","機持此寶，一水一石。","灰池焰爍，名除死籍。"]', '诗', 'shi', '', NULL, '還丹歌 岑真人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dca4b2a2-87b9-42ff-904d-6cf2dbec5b75', '傳付心訣再歌', '傳付心訣再歌', 'a7c34620-2c22-48dc-b872-8a281bdb3bbb', '唐', '["水神投金碧，乾坤日月精。","坎離爲既濟，三才顯其名。","陽數居陰殺，陰數歸陽刑。","欲知顛倒術，相尅是相生。","若修諸八石，千萬無一成。","欲覓真道者，壬癸上尋庚。","（《大還丹照鑑》）。"]', '["水神投金碧，乾坤日月精。","坎離爲既濟，三才显其名。","陽數居陰殺，陰數归陽刑。","欲知顛倒術，相尅是相生。","若修諸八石，千万無一成。","欲覓真道者，壬癸上尋庚。","（《大還丹照鑑》）。"]', '诗', 'shi', '', NULL, '傳付心訣再歌 岑真人 shi');
